// ---- src/game/state.mjs ----
// state.mjs — GameState: the runtime state IS the save shape (architecture §2.3).
// schemaVersion 1. Frontier-ready hooks from day one: badges.symbols (7 locked),
// dex.befriended (third dex state), facilities registry, story.flags open map.


const SCHEMA_VERSION = 1;

function defaultState() {
  return {
    v: SCHEMA_VERSION,
    player: { name: 'ASH', rivalName: 'GARY', trainerId: 0, playtimeSec: 0, money: 300 },
    party: [],
    boxes: {},
    dex: { caught: {}, seen: {}, befriended: {} }, // dexNo -> true
    badges: { kanto: [], orange: [], johto: [], symbols: [null, null, null, null, null, null, null] },
    story: {
      chapter: 0, beat: 0, flags: {},
      // WS6/WS10 story state: quest-log stages + region progression
      // (ADR-019). quests: questId -> 'active' | 'complete' (arc ids included).
      quests: {},
      region: 'kanto',
      regionsDone: [],
      position: { map: 'pallet', x: 7, y: 7, dir: 'down' },
      difficulty: 'normal',
    },
    currentBox: 'box1',
    session: { learnQueue: [] }, // post-battle move-learning prompts (not persisted server-side)
    pikachu: { mood: 'happy', foundItemCooldown: 0 },
    settings: {
      textSpeed: 'normal', battleAnims: true, shake: true, reducedMotion: false,
      mute: false, musicVol: 0.8, sfxVol: 0.8, controlsFlip: false, keymap: null, hudScale: 1,
      vibration: true, autosave: true, showTouch: false, // P1/I5+I2: Wave-3 additions
      battleStyle: 'rt', // ADR-020: 'rt' real-time (default) | 'classic' turn-based
    },
    facilities: { registry: [], unlocked: [] },
    bag: { pokeball: 10, potion: 3 },
    meta: { createdAt: 0, updatedAt: 0, playtimeSec: 0, location: 'Pallet Town' },
  };
}

// Battle-mon factory: {speciesId, nickname, level, xp, moves[{id,pp}], ivs, hp...}
let MON_SEQ = 0;
function makeMon(speciesId, level, speciesTable, movesTable) {
  const sp = speciesTable[speciesId];
  const mon = {
    monId: 'm' + (++MON_SEQ).toString(36) + Date.now().toString(36).slice(-4),
    speciesId,
    nickname: null,
    level,
    xp: xpForLevel(sp.growth, level),
    ivs: { hp: 31, atk: 31, def: 31, spa: 31, spd: 31, spe: 31 },
    moves: [],
    status: null,
    stages: { atk: 0, def: 0, spa: 0, spd: 0, spe: 0 },
    ot: 'ASH',
    friendship: 70,
  };
  const learned = [];
  // Canonical learnset shape: { level: [moveId...] }. species2.mjs delivers
  // [{ level, move }...] — accept both (normalized identically here).
  if (Array.isArray(sp.learnset)) {
    for (const e of [...sp.learnset].sort((a, b) => a.level - b.level)) {
      if (e.level <= level) learned.push(e.move);
    }
  } else {
    for (const lv of Object.keys(sp.learnset).map(Number).sort((a, b) => a - b)) {
      if (lv <= level) learned.push(...sp.learnset[lv]);
    }
  }
  for (const mid of learned.slice(-4)) {
    const mv = movesTable[mid];
    mon.moves.push({ id: mid, pp: mv.pp, maxPp: mv.pp });
  }
  mon.maxHp = hpValue(sp.base.hp, level);
  mon.hp = mon.maxHp;
  mon.stats = {
    atk: statValue(sp.base.atk, level),
    def: statValue(sp.base.def, level),
    spa: statValue(sp.base.spa, level),
    spd: statValue(sp.base.spd, level),
    spe: statValue(sp.base.spe, level),
  };
  return mon;
}


function displayName(mon, speciesTable) {
  return mon.nickname || speciesTable[mon.speciesId].name;
}

// Dex helpers — honest tracked-vs-playable wording lives in the UI layer.
// Yellow hard rules for the partner (Ash's Pikachu): it refuses evolution and
// refuses the PC box. Guards for current + future systems (no evolution or
// deposit UI exists in the slice yet — these are the enforcement points they
// must call). Original refusal lines live in data/dialogue.mjs.
function evolutionCheck(mon) {
  if (mon.speciesId === 'partner') {
    return { ok: false, line: 'PIKACHU turned away! It does not want to change — not ever.' };
  }
  return { ok: true };
}
function boxCheck(mon) {
  if (mon.speciesId === 'partner') {
    return { ok: false, line: 'PIKACHU leapt right back out! It walks beside you, or not at all.' };
  }
  return { ok: true };
}
function dexRegister(dex, kind, dexNo) {
  dex[kind][dexNo] = true;
  if (kind === 'caught' || kind === 'befriended') dex.seen[dexNo] = true;
}
function dexCaughtCount(dex) { return Object.keys(dex.caught).length; }


// ---- src/save/schema.mjs ----
// schema.mjs — save schema v1 validation + migration.
// Hand-rolled typed validator (LCR ruling §9.8). Whitelist, never blacklist.


const SAVE_KEY = 'pdr.save.guest';

// Whitelisted top-level keys. Unknown keys => reject (architecture §3.4).
const TOP_KEYS = ['v', 'player', 'party', 'boxes', 'dex', 'badges', 'story',
  'pikachu', 'settings', 'facilities', 'bag', 'meta', 'currentBox', 'session'];

function isObj(x) { return x !== null && typeof x === 'object' && !Array.isArray(x); }

function validateSave(data) {
  const errors = [];
  if (!isObj(data)) return { ok: false, errors: ['not-an-object'] };
  for (const k of Object.keys(data)) {
    if (!TOP_KEYS.includes(k)) errors.push('unknown-key:' + k);
  }
  if (data.v !== SCHEMA_VERSION) errors.push('bad-schema-version');
  if (!isObj(data.player) || typeof data.player.name !== 'string') errors.push('bad-player');
  if (!Array.isArray(data.party) || data.party.length > 6) errors.push('bad-party');
  for (const m of (data.party || [])) {
    if (!isObj(m) || typeof m.speciesId !== 'string' || typeof m.level !== 'number') { errors.push('bad-mon'); break; }
    if (m.level < 1 || m.level > 100) { errors.push('bad-mon-level'); break; }
    if (!Array.isArray(m.moves) || m.moves.length > 4) { errors.push('bad-mon-moves'); break; }
  }
  if (!isObj(data.dex)) errors.push('bad-dex');
  if (isObj(data.dex) && data.dex.forms !== undefined) {
    if (!isObj(data.dex.forms)) errors.push('bad-dex-forms');
    else for (const k of Object.keys(data.dex.forms)) {
      if (data.dex.forms[k] !== true) { errors.push('bad-dex-form-value'); break; }
    }
  }
  if (!isObj(data.badges) || !Array.isArray(data.badges.kanto)) errors.push('bad-badges');
  if (!isObj(data.story) || !isObj(data.story.position)) errors.push('bad-story');
  if (isObj(data.story) && data.story.quests !== undefined) {
    if (!isObj(data.story.quests)) errors.push('bad-story-quests');
    else for (const k of Object.keys(data.story.quests)) {
      if (!['active', 'complete'].includes(data.story.quests[k])) { errors.push('bad-quest-stage'); break; }
    }
  }
  if (data.currentBox !== undefined && typeof data.currentBox !== 'string') errors.push('bad-current-box');
  return { ok: errors.length === 0, errors };
}

// v0 -> v1 migration chain. v0 never shipped publicly; stub kept for the chain.
function migrate(data) {
  if (!isObj(data)) return null;
  if (data.v === 0) {
    data.v = 1;
    data.facilities = data.facilities || { registry: [], unlocked: [] };
    data.badges = data.badges || { kanto: [], orange: [], johto: [], symbols: [null, null, null, null, null, null, null] };
  }
  return data;
}

function saveSizeBytes(data) {
  try { return new Blob([JSON.stringify(data)]).size; }
  catch (e) { return JSON.stringify(data).length; }
}


// ---- src/save/store.mjs ----
// store.mjs — guest localStorage save store (Track A).
// Versioned JSON, quota-exceeded guard, export-before-overwrite (PRD edge 9).


function storage() {
  try {
    if (typeof localStorage !== 'undefined') return localStorage;
  } catch (e) { /* fall through */ }
  return null;
}

class SaveStore {
  constructor() {
    this.lastError = null;
  }

  exists() {
    const s = storage();
    if (!s) return false;
    return s.getItem(SAVE_KEY) !== null;
  }

  load() {
    const s = storage();
    if (!s) return { ok: false, reason: 'no-storage' };
    const raw = s.getItem(SAVE_KEY);
    if (raw === null) return { ok: false, reason: 'empty' };
    let data;
    try { data = JSON.parse(raw); }
    catch (e) { return { ok: false, reason: 'corrupt-json' }; }
    data = migrate(data);
    const v = validateSave(data);
    if (!v.ok) return { ok: false, reason: 'invalid', errors: v.errors };
    return { ok: true, data };
  }

  save(state) {
    const s = storage();
    if (!s) { this.lastError = 'no-storage'; return { ok: false, reason: 'no-storage' }; }
    state.meta.updatedAt = Date.now();
    const bytes = saveSizeBytes(state);
    if (bytes > 65536) { this.lastError = 'over-budget'; return { ok: false, reason: 'over-budget', bytes }; }
    try {
      s.setItem(SAVE_KEY, JSON.stringify(state));
    } catch (e) {
      // Quota guard: never silently overwrite — surface + offer export.
      this.lastError = 'quota';
      return { ok: false, reason: 'quota', exportPayload: JSON.stringify(state) };
    }
    return { ok: true, bytes };
  }

  erase() {
    const s = storage();
    if (s) s.removeItem(SAVE_KEY);
  }

  exportFile(state) {
    return JSON.stringify(state);
  }
}

function freshState() {
  const st = defaultState();
  st.meta.createdAt = Date.now();
  st.meta.updatedAt = Date.now();
  return st;
}


// ---- src/game/scenes.mjs ----
// scenes.mjs — scene stack (push/pop/replace) + UI-state layer.
// Scenes: boot/title/intro/overworld/battle. UI panels swap without scene reloads.

class SceneStack {
  constructor(game) {
    this.game = game;
    this.stack = [];
  }
  get top() { return this.stack[this.stack.length - 1]; }
  push(scene) {
    const cur = this.top;
    if (cur && cur.suspend) cur.suspend();
    this.stack.push(scene);
    scene.game = this.game;
    if (scene.enter) scene.enter();
  }
  pop() {
    const s = this.stack.pop();
    if (s && s.exit) s.exit();
    const cur = this.top;
    if (cur && cur.resume) cur.resume();
    return s;
  }
  replace(scene) {
    const s = this.stack.pop();
    if (s && s.exit) s.exit();
    this.stack.push(scene);
    scene.game = this.game;
    if (scene.enter) scene.enter();
  }
  clear() {
    while (this.stack.length) this.pop();
  }
  update(dt) { const t = this.top; if (t && t.update) t.update(dt); }
  render(r, alpha) { const t = this.top; if (t && t.render) t.render(r, alpha); }
}


// ---- src/game/ui.mjs ----
// ui.mjs — DOM chrome: D-pad/A/B overlays, dialogue, menus, panels.
// Two backends: browser DOM, and headless (records calls; input-driven).
// Battle command panel: 2x2 grid replacing the D-pad zone (one-thumb rule, gameux §2).
// P0/E8: cmdpanel populated as 2x2 88x64 icon+label buttons, FIGHT top-left.
// P0/E9: move menu as 2x2 grid with type badge pills (icon+text) + PP.
// P0/C3: name-entry A-Z grid keyboard (44px keys, physical-keyboard support).
// P0/B1: Trainer ID Terminal login stub (guest-functional, zero network).

const TEXT_SPEED_CPS = { slow: 15, normal: 30, fast: 60, instant: 9999 };


function stubEl() {
  return {
    children: [], style: {}, dataset: {},
    classList: { add() {}, remove() {}, toggle() {} },
    appendChild(c) { this.children.push(c); return c; },
    remove() {}, addEventListener() {}, removeEventListener() {},
    set textContent(v) { this._t = v; }, get textContent() { return this._t || ''; },
    set innerHTML(v) { this._h = v; }, get innerHTML() { return this._h || ''; },
    querySelector() { return stubEl(); }, querySelectorAll() { return []; },
    focus() {}, click() {},
  };
}

// Hand-authored 12x12 pixel command icons (original, no emoji — contracts §1.3).
// '1' = ink (#ffe9a8 on dark), '.' = transparent.
const CMD_PIX = {
  fight: [
    '.....1......',
    '.....1......',
    '..1..1..1...',
    '...11111....',
    '....111.....',
    '.111111111..',
    '....111.....',
    '...11111....',
    '..1..1..1...',
    '.....1......',
    '.....1......',
    '............',
  ],
  party: [
    '.11...11....',
    '.11...11....',
    '.11...11....',
    '............',
    '.11...11....',
    '.11...11....',
    '............',
    '.1111111....',
    '.1111111....',
    '............',
    '............',
    '............',
  ],
  run: [
    '....1.......',
    '.....1......',
    '......1.....',
    '.......1....',
    '11111111111.',
    '.......1....',
    '......1.....',
    '.....1......',
    '....1.......',
    '............',
    '............',
    '............',
  ],
};

function typePill(type) {
  const col = TYPE_COLORS[type] || '#a8a878';
  const abbr = String(type).slice(0, 2).toUpperCase();
  return '<span class="tpill" style="background:' + col + '"><b>' + abbr + '</b>&nbsp;' + type + '</span>';
}

class UI {
  constructor(game) {
    this.game = game;
    this.headless = (typeof document === 'undefined');
    this.root = null;
    this.frame = null; // UI v2.1: frame-anchored layer (box synced to the canvas rect)
    this.dpadEl = null; this.cmdEl = null;
    this.dlg = null;      // { lines, idx, chars, cb, speaker }
    this.menu = null;     // { title, items, idx, cb, battle }
    this.panel = null;    // named panel open (dex/party/bag/save/options)
    this.toastQ = [];
    this.log = [];        // headless: record of UI calls (test assertions)
    this._els = {};
    this.summary = null; // Platinum summary panel state ({ data, tab, cb })
    this.nameEntry = null; // { value, maxLen, cb, ... } while the A-Z grid is open
    this.loginOpen = false;
    this.inBattle = false; // Track B: battle-mode flag (SYNC defers conflict UI out of battle)
    this.hudVisible = true;
    this.dexDot = false;
    this._guestBannerOff = false;
    this.onMoodTap = null;
    this._moodWanted = false;
    // Seat D HUD chips (overworld seat drives these via the setters below).
    this.hudChips = { location: null, objective: null, dex: null };
    this._chipEls = null;   // { wrap, location, locationText, objective, objectiveText, dex, dexText }
    this._hudToastQ = [];   // headless record for hudToast (cap 2, mirrors the DOM cap)
    this.chapterCard = null; // D2: chapter title card overlay while open
    this._ccT = 0;
  }

  init() {
    if (this.headless) return;
    const doc = document;
    this.root = doc.getElementById('ui');
    // UI v2.1 (defects 2-5): everything that belongs to the GAME — dialogue,
    // menus, battle commands, HUD chips/strip, toasts, chapter cards — lives
    // in this frame layer, whose box is synced to the canvas rect by
    // _syncChipAnchor(). DOM chrome positioned against the viewport is how
    // v2 shipped dialogue/commands/party OUTSIDE the frame on the live build.
    // Viewport-layer elements stay in #ui: touch controls, login/name-entry
    // overlays (full-screen modal dim), hint card, 503 banner, sync dot.
    this.frame = this.el('div', 'frameui', this.root);
    if (typeof window !== 'undefined' && window.addEventListener) {
      window.addEventListener('resize', () => this._syncChipAnchor());
    }
    this.buildControls();
    this.buildDialogue();
    this.buildMenu();
    this.buildSummaryPanel();
    this.buildToasts();
    this.buildHudChips();
    this.buildHudStrip();
    this.buildGuestBanner();
    this.buildMoodPip();
    this.buildHintCard();
    this._syncChipAnchor(); // frame box correct from the first painted frame
  }

  el(tag, cls, parent) {
    if (this.headless) return stubEl();
    const e = document.createElement(tag);
    if (cls) e.className = cls;
    if (parent) parent.appendChild(e);
    return e;
  }

  // ---- touch controls ----
  buildControls() {
    const g = this.el('div', 'controls', this.root);
    const pad = this.el('div', 'dpad', g);
    this.dpadEl = pad;
    const mk = (action, cls, label) => {
      const b = this.el('button', 'padbtn ' + cls, pad);
      b.textContent = label;
      b.setAttribute('aria-label', action);
      const on = (e) => { e.preventDefault(); this.game.audio.unlock(); this.game.input.press(action); };
      const off = (e) => { e.preventDefault(); this.game.input.release(action); };
      b.addEventListener('pointerdown', on);
      b.addEventListener('pointerup', off);
      b.addEventListener('pointercancel', off);
      b.addEventListener('pointerleave', off);
      b.addEventListener('contextmenu', (e) => e.preventDefault());
      return b;
    };
    mk('up', 'p-up', '▲'); mk('down', 'p-down', '▼');
    mk('left', 'p-left', '◀'); mk('right', 'p-right', '▶');
    const ab = this.el('div', 'ab', g);
    const mkA = (action, cls, label) => {
      const b = this.el('button', 'abtn ' + cls, ab);
      b.textContent = label;
      b.addEventListener('pointerdown', (e) => { e.preventDefault(); this.game.audio.unlock(); this.game.input.press(action); });
      b.addEventListener('pointerup', (e) => { e.preventDefault(); this.game.input.release(action); });
      b.addEventListener('pointercancel', (e) => e.preventDefault());
      return b;
    };
    mkA('a', 'a-a', 'A'); mkA('b', 'a-b', 'B');
    // Z-A change order (ADR-021): full emulator pad — X/Y join A/B.
    // X = pageup (bag tabs / dex page / bike), Y = pagedown.
    mkA('pageup', 'a-x', 'X'); mkA('pagedown', 'a-y', 'Y');
    const sys = this.el('div', 'sysbtns', g);
    const mkS = (action, label) => {
      const b = this.el('button', 'sysbtn', sys);
      b.textContent = label;
      b.addEventListener('pointerdown', (e) => { e.preventDefault(); this.game.input.press(action); });
      b.addEventListener('pointerup', (e) => { e.preventDefault(); this.game.input.release(action); });
      return b;
    };
    mkS('start', 'START'); mkS('select', 'SELECT');
    // Command panel (battle) — hidden unless battle scene shows it. P0/E8: populated as a 2x2 grid.
    // D3: child of #ui root, NOT .controls — body.desktop hides .controls (touch
    // buttons), which used to hide the battle commands on every laptop too.
    this.cmdEl = this.el('div', 'cmdpanel hidden', this.frame);
  }

  // ---- P0/E8: battle command 2x2 grid (replaces the D-pad zone) ----
  // items: [{label, value, disabled, dimmed}] — dimmed = tutorial de-emphasis (still selectable).
  showCommands(items, cb, opts) {
    opts = opts || {};
    this.game.input.consumeAll(); // D3: stale walk edges must not move the battle cursor
    this.menu = {
      title: null, items, idx: opts.initialIdx || 0, cb, battle: true,
      kind: 'commands', grid: true, focus: opts.focus || null,
    };
    this.log.push({ ui: 'commands', items: items.map((i) => i.label) });
    if (!this.headless) this.renderCommands();
  }

  cmdIconCanvas(value) {
    const c = document.createElement('canvas');
    c.width = 16; c.height = 16;
    c.className = 'cmdicon';
    const x = c.getContext('2d');
    x.imageSmoothingEnabled = false;
    if (value === 'bag') {
      const art = uiIcon(document, 'pokeball');
      if (art) x.drawImage(art, 0, 0);
      return c;
    }
    const pat = CMD_PIX[value];
    if (pat) {
      x.fillStyle = '#ffe9a8';
      for (let r = 0; r < pat.length; r++) {
        for (let q = 0; q < pat[r].length; q++) {
          if (pat[r][q] === '1') x.fillRect(q + 2, r + 2, 1, 1);
        }
      }
    }
    return c;
  }

  renderCommands() {
    if (this.headless) return;
    const m = this.menu;
    if (!m || m.kind !== 'commands') { this.cmdEl.classList.add('hidden'); return; }
    this.cmdEl.classList.remove('hidden');
    this.cmdEl.innerHTML = '';
    m.items.forEach((it, i) => {
      const b = document.createElement('button');
      b.className = 'cmdf cmdf-' + it.value
        + (i === m.idx ? ' cursor' : '')
        + (it.disabled ? ' disabled' : '')
        + (it.dimmed ? ' dimmed' : '')
        + (m.focus && m.focus === it.value ? ' tut-focus' : '');
      b.appendChild(this.cmdIconCanvas(it.value));
      const lb = document.createElement('span');
      lb.className = 'cmdlabel';
      lb.textContent = it.label;
      b.appendChild(lb);
      b.setAttribute('aria-label', it.label);
      if (!it.disabled) {
        b.addEventListener('pointerdown', (e) => { e.preventDefault(); this.chooseMenu(i); });
      }
      this.cmdEl.appendChild(b);
    });
  }

  hideCommands() {
    if (!this.headless) this.cmdEl.classList.add('hidden');
  }

  // 2x2 grid navigation (P0/E8): arrows move in the grid with edge wrap,
  // skipping disabled cells. Works for any item count (short last row clamps).
  moveMenuGrid(dir) {
    const m = this.menu;
    if (!m) return;
    const n = m.items.length, cols = 2, rows = Math.ceil(n / cols);
    const step = (idx) => {
      let r = Math.floor(idx / cols), c = idx % cols;
      if (dir === 'left') c = (c + cols - 1) % cols;
      else if (dir === 'right') c = (c + 1) % cols;
      else if (dir === 'up') r = (r + rows - 1) % rows;
      else r = (r + 1) % rows;
      let ni = r * cols + c;
      if (ni >= n) ni = n - 1;
      return ni;
    };
    let i = m.idx;
    for (let k = 0; k < n; k++) {
      i = step(i);
      if (!m.items[i].disabled) break;
    }
    m.idx = i;
    this.game.audio.playSfx(SFX['ui-tick']);
    if (!this.headless) {
      if (m.kind === 'commands') this.renderCommands();
      else this.renderMenu();
    }
  }

  buildDialogue() {
    this.dlgEl = this.el('div', 'dialogue hidden', this.frame);
    // UI v2.1 (defect 5): no portrait tab, no name pill — Platinum puts the
    // speaker's name as a plain line in the text flow (see say() + .dlg-name).
    this.dlgFace = null;
    this.dlgName = this.el('div', 'dlg-name', this.dlgEl);
    this.dlgText = this.el('div', 'dlg-text', this.dlgEl);
    this.dlgHint = this.el('div', 'dlg-hint', this.dlgEl);
    this.dlgHint.textContent = '▼';
  }

  say(lines, cb, speaker) {
    this.dlg = { lines: lines.slice(), idx: 0, chars: 0, cb: cb || null, speaker: speaker || null, done: false };
    this.log.push({ ui: 'dialogue', lines });
    if (!this.headless) {
      this.dlgEl.classList.remove('hidden');
      this.dlgName.textContent = this.dlg.speaker || '';
      this.dlgName.style.display = this.dlg.speaker ? 'block' : 'none';
      this.dlgText.textContent = '';
    }
  }

  get dialogueOpen() { return !!this.dlg; }

  advanceDialogue() {
    const d = this.dlg;
    if (!d) return false;
    const full = d.lines[d.idx];
    const speed = TEXT_SPEED_CPS[this.game.state.settings.textSpeed] || 30;
    if (d.chars < full.length && speed < 9999) {
      d.chars = full.length; // first press completes the line
      if (!this.headless) this.dlgText.textContent = full;
      return true;
    }
    d.idx++;
    d.chars = 0;
    if (d.idx >= d.lines.length) {
      this.closeDialogue();
      const cb = d.cb; d.cb = null;
      if (cb) cb();
      return false;
    }
    this.game.audio.playSfx(SFX['dialogue-blip']); // visual twin: the ▼ indicator
    if (!this.headless) this.dlgText.textContent = '';
    return true;
  }

  closeDialogue() {
    this.dlg = null;
    if (!this.headless) this.dlgEl.classList.add('hidden');
  }

  buildMenu() {
    this.menuEl = this.el('div', 'menu hidden', this.frame);
    this.menuTitle = this.el('div', 'menu-title', this.menuEl);
    this.menuList = this.el('div', 'menu-list', this.menuEl);
  }

  // opts: { battle, grid, initialIdx, rowHtml(item, i), focusValue }
  showMenu(title, items, cb, opts) {
    opts = opts || {};
    // D3: a menu opening consumes stale input edges — e.g. the direction key a
    // player was holding while walking into a grass encounter must not move the
    // battle cursor the moment the command menu appears.
    this.game.input.consumeAll();
    this.menu = {
      title, items, idx: opts.initialIdx || 0, cb,
      battle: !!(opts && opts.battle), kind: opts.kind || 'menu',
      grid: !!opts.grid, rowHtml: opts.rowHtml || null,
      menuClass: opts.menuClass || '',
      focusValue: opts.focusValue !== undefined ? opts.focusValue : null,
    };
    this.log.push({ ui: 'menu', title, items: items.map((i) => i.label) });
    if (!this.headless) this.renderMenu();
  }

  renderMenu() {
    if (this.headless) return;
    const m = this.menu;
    if (!m || m.kind === 'commands') { this.menuEl.classList.add('hidden'); return; }
    this.menuEl.classList.remove('hidden');
    this.menuEl.className = 'menu' + (m.menuClass ? ' ' + m.menuClass : '');
    // Full-takeover windows (party screen, PC box, summary) hide the
    // overworld HUD — Platinum screens own the whole frame.
    if (typeof document !== 'undefined' && document.body) {
      document.body.classList.toggle('menu-full', /(plate-full|pcbox)/.test(m.menuClass || ''));
    }
    this.menuTitle.textContent = m.title || '';
    this.menuTitle.style.display = m.title ? 'block' : 'none';
    this.menuList.innerHTML = '';
    this.menuList.className = 'menu-list' + (m.grid ? ' menugrid' : '');
    m.items.forEach((it, i) => {
      const r = document.createElement('button');
      r.className = 'menu-row'
        + (i === m.idx ? ' cursor' : '')
        + (it.disabled ? ' disabled' : '')
        + (it.band ? ' bandrow' : '')
        + (it.wide ? ' wide' : '')
        + (it.closeRow ? ' close-row' : '')
        + (it.zeroPp ? ' zeropp' : '')
        + (it.emptySlot ? ' emptyslot' : '')
        + (m.focusValue !== null && m.focusValue === it.value ? ' tut-focus' : '');
      // Seat D row support: an item may carry `icon` (img src / data URL) to
      // render a .picon sprite tile (party + bag rows) when no rowHtml is set;
      // with rowHtml, the caller's markup can use .picon / .emptyslot directly.
      if (m.rowHtml) r.innerHTML = '<span class="cur">' + (i === m.idx ? '▶' : '&nbsp;') + '</span>' + m.rowHtml(it, i);
      else if (it.icon) r.innerHTML = '<span class="cur">' + (i === m.idx ? '▶' : '&nbsp;') + '</span><img class="picon" src="' + it.icon + '" alt=""><span>' + it.label + '</span>';
      else r.innerHTML = '<span class="cur">' + (i === m.idx ? '▶' : '&nbsp;') + '</span><span>' + it.label + '</span>';
      if (!it.disabled) r.addEventListener('pointerdown', (e) => { e.preventDefault(); this.chooseMenu(i); });
      this.menuList.appendChild(r);
    });
  }

  moveMenu(d) {
    const m = this.menu;
    if (!m) return;
    const n = m.items.length;
    let i = m.idx;
    for (let k = 0; k < n; k++) {
      i = (i + d + n) % n;
      if (!m.items[i].disabled) break;
    }
    m.idx = i;
    this.game.audio.playSfx(SFX['ui-tick']);
    if (!this.headless) this.renderMenu();
  }

  chooseMenu(i) {
    const m = this.menu;
    if (!m) return;
    const idx = (i === undefined ? m.idx : i);
    const it = m.items[idx];
    if (!it || it.disabled) return;
    const wasCommands = m.kind === 'commands';
    this.menu = null;
    if (!this.headless) {
      this.menuEl.classList.add('hidden');
      if (typeof document !== 'undefined' && document.body) document.body.classList.remove('menu-full');
      if (wasCommands) this.hideCommands();
    }
    this.game.audio.playSfx(SFX['ui-blip']);
    const cb = m.cb;
    if (cb) cb(it.value, idx);
  }

  cancelMenu() {
    const m = this.menu;
    if (!m) return;
    const wasCommands = m.kind === 'commands';
    this.menu = null;
    if (!this.headless) {
      this.menuEl.classList.add('hidden');
      if (typeof document !== 'undefined' && document.body) document.body.classList.remove('menu-full');
      if (wasCommands) this.hideCommands();
    }
    this.game.audio.playSfx(SFX['ui-back']);
    const cb = m.cb;
    if (cb) cb(null, -1);
  }

  get menuOpen() { return !!this.menu; }

  // ---- Platinum tabbed summary panel (UI v2) ----
  // data: { name, tabs: [{ id, label, bodyHtml }] }. The caller composes each
  // tab's body HTML from real game data (profile / status / moves in the
  // Platinum summary arrangement); this class owns the chrome: tab strip,
  // framed panel, keyboard routing (left/right switch, B/START close).
  buildSummaryPanel() {
    this.sumEl = this.el('div', 'sumpanel hidden', this.frame);
    this.sumTabsEl = this.el('div', 'sumtabs', this.sumEl);
    this.sumBodyEl = this.el('div', 'sumbody', this.sumEl);
    const close = this.el('button', 'sumclose', this.sumEl);
    close.textContent = 'Close';
    close.addEventListener('pointerdown', (e) => { e.preventDefault(); this.closeSummary(); });
    this.sumCloseBtn = close;
  }

  showSummary(data, cb) {
    this.summary = { data, tab: 0, cb: cb || null };
    this.log.push({ ui: 'summary', name: data && data.name });
    if (!this.headless && typeof document !== 'undefined' && document.body) document.body.classList.add('menu-full');
    if (!this.headless) this.renderSummary();
  }

  renderSummary() {
    if (this.headless || !this.sumEl) return;
    const s = this.summary;
    if (!s) { this.sumEl.classList.add('hidden'); return; }
    this.sumEl.classList.remove('hidden');
    this.sumTabsEl.innerHTML = '';
    s.data.tabs.forEach((t, i) => {
      const b = document.createElement('button');
      b.className = 'sumtab' + (i === s.tab ? ' sel' : '');
      b.textContent = t.label;
      b.addEventListener('pointerdown', (e) => {
        e.preventDefault();
        this.summary.tab = i;
        this.game.audio.playSfx(SFX['ui-tick']);
        this.renderSummary();
      });
      this.sumTabsEl.appendChild(b);
    });
    this.sumBodyEl.innerHTML = s.data.tabs[s.tab].bodyHtml || '';
  }

  summaryTab(d) {
    const s = this.summary;
    if (!s) return;
    const n = s.data.tabs.length;
    s.tab = (s.tab + d + n) % n;
    this.game.audio.playSfx(SFX['ui-tick']);
    if (!this.headless) this.renderSummary();
  }

  closeSummary() {
    const s = this.summary;
    if (!s) return;
    this.summary = null;
    if (!this.headless && typeof document !== 'undefined' && document.body) document.body.classList.remove('menu-full');
    if (!this.headless && this.sumEl) this.sumEl.classList.add('hidden');
    this.game.audio.playSfx(SFX['ui-back']);
    if (s.cb) s.cb();
  }

  get summaryOpen() { return !!this.summary; }

  buildToasts() {
    this.toastEl = this.el('div', 'toasts', this.frame);
  }

  toast(text) {
    this.toastQ.push({ text, t: 0 });
    if (this.toastQ.length > 3) this.toastQ.shift(); // P1/D9: queue cap 3
    this.log.push({ ui: 'toast', text });
    if (this.headless) return;
    const d = document.createElement('div');
    d.className = 'toast';
    d.textContent = text;
    this.toastEl.appendChild(d);
    while (this.toastEl.children.length > 3) this.toastEl.removeChild(this.toastEl.firstChild);
    setTimeout(() => { if (d.parentNode) d.parentNode.removeChild(d); }, 2500);
  }

  // ---- Seat D: HUD chips + bottom-edge HUD toast ----
  // DOM (inside #ui, sibling of .hudstrip):
  //   <div class="hudchips">
  //     <div class="hudchip locchip hidden"><span class="locchip-text"></span></div>
  //     <div class="hudchip objchip hidden"><span class="obj-kicker">▶ OBJECTIVE</span><span class="obj-text"></span></div>
  //     <div class="hudchip dexchip hidden"><span class="dexchip-text"></span></div>
  //   </div>
  // Visibility follows the HUD-strip rules exactly: the column is hidden by
  // .nohud (setHudVisible) and .inbattle (setBattleMode) in CSS, same as
  // .hudstrip — menus/dialogues overlay it, they do not hide it.
  buildHudChips() {
    const wrap = this.el('div', 'hudchips', this.frame);
    const loc = this.el('div', 'hudchip locchip hidden', wrap);
    const locText = this.el('span', 'locchip-text', loc);
    const obj = this.el('div', 'hudchip objchip hidden', wrap);
    const kick = this.el('span', 'obj-kicker', obj);
    kick.textContent = '▶ OBJECTIVE';
    const objText = this.el('span', 'obj-text', obj);
    const dex = this.el('div', 'hudchip dexchip hidden', wrap);
    const dexText = this.el('span', 'dexchip-text', dex);
    this._chipEls = {
      wrap, location: loc, locationText: locText,
      objective: obj, objectiveText: objText, dex, dexText,
    };
    this._syncChipAnchor();
    // Re-apply any state set before init() ran.
    this._renderChip('location');
    this._renderChip('objective');
    this._renderChip('dex');
  }

  _renderChip(key) {
    if (this.headless || !this._chipEls) return;
    const els = this._chipEls;
    const text = this.hudChips[key];
    const chip = key === 'location' ? els.location : key === 'objective' ? els.objective : els.dex;
    const label = key === 'location' ? els.locationText : key === 'objective' ? els.objectiveText : els.dexText;
    if (text) { label.textContent = text; chip.classList.remove('hidden'); }
    else { label.textContent = ''; chip.classList.add('hidden'); }
  }

  _setChip(key, text, logUi) {
    this.hudChips[key] = text ? String(text) : null;
    this.log.push({ ui: logUi, text: this.hudChips[key] });
    this._renderChip(key);
  }

  // Location name only (e.g. 'Pallet Town'). Null/empty hides the chip.
  setLocationChip(textOrNull) { this._setChip('location', textOrNull, 'locationchip'); }

  // Current objective, up to 2 lines (CSS line-clamp + ellipsis). Null hides.
  setObjectiveChip(textOrNull) { this._setChip('objective', textOrNull, 'objectivechip'); }

  // Compact dex pill — caller formats it (e.g. 'DEX 1/1025'). Null hides.
  setDexChip(textOrNull) { this._setChip('dex', textOrNull, 'dexchip'); }

  // Bottom-edge toast: reuses the .toasts stack (CSS anchors it just above
  // the controls zone, centered, max-width 92vw via .toast), gold-rimmed via
  // .hudtoast, auto-dismisses after ms (default 2600), queue capped at 2.
  hudToast(text, ms) {
    const dur = (typeof ms === 'number' && ms > 0) ? ms : 2600;
    this.log.push({ ui: 'hudtoast', text, ms: dur });
    this._hudToastQ.push({ text, ms: dur });
    if (this._hudToastQ.length > 2) this._hudToastQ.shift();
    if (this.headless || !this.toastEl) return;
    const d = document.createElement('div');
    d.className = 'toast hudtoast';
    d.textContent = text;
    this.toastEl.appendChild(d);
    const live = this.toastEl.querySelectorAll('.hudtoast');
    if (live.length > 2) live[0].remove();
    setTimeout(() => { if (d.parentNode) d.parentNode.removeChild(d); }, dur);
  }

  // ---- P0/B1: Trainer ID Terminal (login stub — Track B dark, zero network) ----
  // Track B: when the auth UI is compiled in (vercel target, AUTH_ENABLED), the
  // terminal shows the full LOG IN / REGISTER / GUEST panel (auth.mjs). In the
  // guest target the stub below is byte-identical to Track A behavior.
  showLogin(cb) {
    if (this.headless) {
      // No DOM to click in the harness: the guest path is the only functional one.
      this.log.push({ ui: 'login-guest-auto' });
      cb('guest');
      return;
    }
    if (typeof AUTH_ENABLED !== 'undefined' && AUTH_ENABLED) {
      AUTH.showLoginPanel(this, this.game, cb);
      return;
    }
    this.loginOpen = true;
    this._loginCb = cb;
    const ov = this.el('div', 'loginover', this.root);
    this._loginOv = ov;
    const card = this.el('div', 'login', ov);
    const h = this.el('div', 'login-head', card);
    h.textContent = 'TRAINER ID TERMINAL';
    const tabs = this.el('div', 'login-tabs', card);
    const panes = this.el('div', 'login-panes', card);
    const mkTab = (name, key) => {
      const b = this.el('button', 'logintab', tabs);
      b.textContent = name;
      b.addEventListener('pointerdown', (e) => { e.preventDefault(); this._loginTab(key); });
      return b;
    };
    this._loginTabs = { login: mkTab('LOG IN', 'login'), register: mkTab('REGISTER', 'register'), guest: mkTab('GUEST', 'guest') };
    this._loginPanes = {};
    const mkPane = (key) => {
      const p = this.el('div', 'loginpane hidden', panes);
      this._loginPanes[key] = p;
      return p;
    };
    // LOG IN pane (disabled — honest stub)
    const lp = mkPane('login');
    lp.innerHTML = '<div class="login-note">Accounts arrive in Track B.<br>Your trainer ID lives on this device for now.</div>'
      + '<label>Trainer name<input class="login-in" disabled aria-label="Trainer name (disabled)"></label>'
      + '<label>Password<input class="login-in" type="password" disabled aria-label="Password (disabled)"></label>'
      + '<button class="login-go" disabled>LOG IN (Track B)</button>';
    // REGISTER pane (disabled — honest stub)
    const rp = mkPane('register');
    rp.innerHTML = '<div class="login-note">Accounts arrive in Track B.<br>No credentials are collected or sent anywhere.</div>'
      + '<label>Trainer name<input class="login-in" disabled aria-label="Trainer name (disabled)"></label>'
      + '<label>Password<input class="login-in" type="password" disabled aria-label="Password (disabled)"></label>'
      + '<button class="login-go" disabled>REGISTER (Track B)</button>';
    // GUEST pane (functional, zero network)
    const gp = mkPane('guest');
    const gnote = this.el('div', 'login-note', gp);
    gnote.textContent = 'Play right now — no account needed. Progress stays on this device until cloud saves arrive in Track B.';
    const go = this.el('button', 'login-go active', gp);
    go.textContent = 'PLAY AS GUEST';
    go.addEventListener('pointerdown', (e) => {
      e.preventDefault();
      this.game.audio.unlock();
      this._closeLogin();
      cb('guest');
    });
    this._loginTab('guest');
  }

  _loginTab(key) {
    for (const k of Object.keys(this._loginTabs)) {
      this._loginTabs[k].classList.toggle('sel', k === key);
      this._loginPanes[k].classList.toggle('hidden', k !== key);
    }
    this.game.audio.playSfx(SFX['ui-tick']);
  }

  _closeLogin() {
    this.loginOpen = false;
    if (this._loginOv && this._loginOv.parentNode) this._loginOv.parentNode.removeChild(this._loginOv);
    this._loginOv = null;
  }

  // ---- guest banner element (RETIRED in UI v2.1 — see showGuestBanner) ----
  buildGuestBanner() {
    const b = this.el('div', 'guestbanner hidden', this.root);
    const t = this.el('span', '', b);
    t.textContent = 'Guest — progress stays on this device · LOG IN';
    const x = this.el('button', 'gbx', b);
    x.textContent = '×';
    x.setAttribute('aria-label', 'Dismiss');
    x.addEventListener('pointerdown', (e) => {
      e.preventDefault();
      this._guestBannerOff = true;
      b.classList.add('hidden');
    });
    this._guestBannerEl = b;
    // Track B (vercel): the banner's LOG IN becomes a real button (auth.mjs).
    // Guest target: AUTH.enhanceGuestBanner is a no-op — banner byte-identical.
    if (typeof AUTH !== 'undefined') AUTH.enhanceGuestBanner(this);
  }

  showGuestBanner() {
    // UI v2.1 (defect 2): the in-game guest banner is RETIRED. It rendered as
    // a full-width bar across the top of the gameplay frame on the live
    // build. The guest notice now lives only in the flow where it belongs —
    // the Trainer ID Terminal's guest pane, which already reads "Progress
    // stays on this device — log in anytime to sync" (auth.mjs; the stub
    // terminal's guest pane carries the same message) — i.e. before play
    // starts, never over gameplay. This stays as a hiding no-op so the
    // existing call sites (startOverworld / openLogin) remain safe.
    this.hideGuestBanner();
  }

  hideGuestBanner() {
    if (this.headless || !this._guestBannerEl) return;
    this._guestBannerEl.classList.add('hidden');
  }

  // ---- P0/C3: name-entry A-Z grid keyboard ----
  // DOM: bottom-half grid (portrait) / 480px centered panel (desktop), 44px keys,
  // physical-keyboard support, 8-char max, validation shake on empty.
  showNameEntry(title, initial, maxLen, cb) {
    if (this.headless) {
      // Harness contract: a menu-like state so menuOpen/debugChoose keep working.
      this.menu = {
        title, items: [{ label: initial + ' (default)', value: initial }],
        idx: 0, cb: (v) => cb(v || initial), kind: 'nameentry',
      };
      this.log.push({ ui: 'nameentry', title });
      return;
    }
    this.nameEntry = { value: initial || '', maxLen: maxLen || 8, cb, title };
    const ov = this.el('div', 'nkbover', this.root);
    this._nkbOv = ov;
    const card = this.el('div', 'namekb', ov);
    const h = this.el('div', 'nkb-title', card);
    h.textContent = title;
    const disp = this.el('div', 'nkb-display', card);
    this._nkbDisp = disp;
    this._nkbRender();
    const grid = this.el('div', 'nkb-grid', card);
    const keys = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'.split('');
    for (const k of keys) {
      const b = this.el('button', 'nkb-key', grid);
      b.textContent = k;
      b.addEventListener('pointerdown', (e) => { e.preventDefault(); this._nkbType(k); });
    }
    const row = this.el('div', 'nkb-row', card);
    const bk = this.el('button', 'nkb-key wide', row);
    bk.textContent = '←';
    bk.addEventListener('pointerdown', (e) => { e.preventDefault(); this._nkbBack(); });
    const dash = this.el('button', 'nkb-key', row);
    dash.textContent = '-';
    dash.addEventListener('pointerdown', (e) => { e.preventDefault(); this._nkbType('-'); });
    const ok = this.el('button', 'nkb-key wide go', row);
    ok.textContent = 'OK';
    ok.addEventListener('pointerdown', (e) => { e.preventDefault(); this._nkbOk(); });
    // Physical keyboard: capture at document level so the game's KEYMAP never sees these.
    this._nkbKey = (e) => {
      if (!this.nameEntry) return;
      e.preventDefault();
      e.stopPropagation();
      if (e.key === 'Backspace') this._nkbBack();
      else if (e.key === 'Enter') this._nkbOk();
      else if (/^[a-zA-Z-]$/.test(e.key)) this._nkbType(e.key.toUpperCase());
    };
    document.addEventListener('keydown', this._nkbKey, true);
  }

  _nkbRender() {
    const ne = this.nameEntry;
    if (!ne || !this._nkbDisp) return;
    this._nkbDisp.textContent = ne.value + '▌';
  }

  _nkbType(ch) {
    const ne = this.nameEntry;
    if (!ne || ne.value.length >= ne.maxLen) return;
    ne.value += ch;
    this.game.audio.playSfx(SFX['ui-tick']);
    this._nkbRender();
  }

  _nkbBack() {
    const ne = this.nameEntry;
    if (!ne) return;
    ne.value = ne.value.slice(0, -1);
    this.game.audio.playSfx(SFX['ui-back']);
    this._nkbRender();
  }

  _nkbOk() {
    const ne = this.nameEntry;
    if (!ne) return;
    if (!ne.value.trim()) {
      // Validation shake on empty (P0/C3).
      this.game.audio.playSfx(SFX['error-buzz']);
      if (this._nkbOv) {
        this._nkbOv.classList.remove('shake');
        void this._nkbOv.offsetWidth;
        this._nkbOv.classList.add('shake');
      }
      this.toast('Give your trainer a name!');
      return;
    }
    const cb = ne.cb, v = ne.value.trim().toUpperCase().slice(0, ne.maxLen);
    this._nkbClose();
    cb(v);
  }

  _nkbClose() {
    if (this._nkbKey) document.removeEventListener('keydown', this._nkbKey, true);
    this._nkbKey = null;
    this.nameEntry = null;
    if (this._nkbOv && this._nkbOv.parentNode) this._nkbOv.parentNode.removeChild(this._nkbOv);
    this._nkbOv = null;
  }

  // ---- P1/D4: persistent HUD quick-strip (one-tap Bag/Party/Dex/Menu) ----
  // Choice documented: portrait = overlaid top-right of canvas (gameux §4.1).
  buildHudStrip() {
    const strip = this.el('div', 'hudstrip', this.frame);
    this._hudStrip = strip;
    const defs = [
      ['bag', 'Bag'], ['party', 'Party'], ['dex', 'Dex'], ['menu', 'Menu'],
    ];
    this._hudBtns = {};
    for (const [key, label] of defs) {
      const b = this.el('button', 'hudbtn', strip);
      b.setAttribute('aria-label', label);
      const cv = document.createElement('canvas');
      cv.width = 16; cv.height = 16;
      cv.className = 'hudicon';
      drawHudIcon(cv.getContext('2d'), key);
      b.appendChild(cv);
      const lb = this.el('span', 'hudlabel', b);
      lb.textContent = label;
      if (key === 'dex') {
        const dot = this.el('span', 'dexdot hidden', b);
        this._dexDot = dot;
      }
      b.addEventListener('pointerdown', (e) => {
        e.preventDefault();
        this.game.audio.unlock();
        const g = this.game;
        if (key === 'bag') g.openBag();
        else if (key === 'party') g.openParty();
        else if (key === 'dex') { this.dexDot = false; this._renderDexDot(); g.openDex(); }
        else if (key === 'menu') {
          const ow = g.scenes.top;
          if (ow && ow.openPauseMenu) ow.openPauseMenu();
        }
      });
      this._hudBtns[key] = b;
    }
  }

  _renderDexDot() {
    if (!this._dexDot) return;
    this._dexDot.classList.toggle('hidden', !this.dexDot);
  }

  setHudVisible(v) {
    this.hudVisible = v;
    if (this.headless || !this.root) return;
    this.root.classList.toggle('nohud', !v); // P1/D4: SELECT toggles the strip
  }

  // ---- P1/D7: partner mood pip (persistent, tappable) ----
  // Seat D: CSS re-homes it into the right rail, directly under the HUD
  // button rail (top:110px/right:8px, 48px round ink button); it is hidden
  // in landscape (body.landscape) where the vertical rail owns the right
  // edge. No longer a floating bottom-right page widget.
  buildMoodPip() {
    const b = this.el('button', 'moodpip hidden', this.frame);
    b.setAttribute('aria-label', 'Pikachu');
    const cv = this.headless ? null : document.createElement('canvas');
    if (cv) {
      cv.width = 16; cv.height = 16;
      cv.className = 'moodface';
      b.appendChild(cv);
      this._moodFace = cv;
    }
    const dot = this.el('span', 'mooddot', b);
    this._moodDot = dot;
    b.addEventListener('pointerdown', (e) => {
      e.preventDefault();
      this.game.audio.unlock();
      if (this.onMoodTap) this.onMoodTap();
    });
    this._moodPip = b;
  }

  showMoodPip(v) {
    if (this.headless || !this._moodPip) return;
    this._moodWanted = v;
    this._moodPip.classList.toggle('hidden', !v);
    if (v) this.updateMoodPip();
  }

  updateMoodPip() {
    if (this.headless || !this._moodPip) return;
    const mood = (this.game.state.pikachu && this.game.state.pikachu.mood) || 'happy';
    const col = mood === 'happy' ? '#58c94f' : mood === 'sleepy' ? '#5a9ae8' : '#e8c832';
    if (this._moodDot) this._moodDot.style.background = col;
    if (this._moodFace && this.game.partnerFrame) {
      const x = this._moodFace.getContext('2d');
      x.imageSmoothingEnabled = false;
      x.clearRect(0, 0, 16, 16);
      x.drawImage(this.game.partnerFrame(), 0, 0);
    }
  }
  // ---- P1/K3: desktop keyboard-hint card (dismissible) ----
  buildHintCard() {
    const c = this.el('div', 'hintcard hidden', this.root);
    const t = this.el('div', '', c);
    t.textContent = 'Keyboard: Arrows/WASD move · Z/Space = A · X = B · Enter = START · M = mute · F = fullscreen';
    const x = this.el('button', 'hintcard-x', c);
    x.textContent = 'Got it ×';
    x.addEventListener('pointerdown', (e) => {
      e.preventDefault();
      this._hintOff = true;
      c.classList.add('hidden');
    });
    this._hintCard = c;
  }

  showHintCard(v) {
    if (this.headless || !this._hintCard) return;
    this._hintCard.classList.toggle('hidden', !v || this._hintOff);
  }

  // ---- D2: chapter title cards (anime-chronology spine, ADR-015) ----
  // ch: a CHAPTERS entry (src/data/story.mjs). Paper-panel card, Gen 4/5 idiom,
  // tap/A/START dismisses, auto-dismisses after 4s of game time (reduced-motion
  // safe: no animation). All text >= 14px (QA-001).
  showChapterCard(ch) {
    this.log.push({ ui: 'chaptercard', chapter: ch && ch.n, title: ch && ch.title });
    if (this.headless) { this.chapterCard = null; return; }
    this.hideChapterCard(); // one card at a time
    this._ccT = 0;
    const d = this.el('div', 'chaptercard', this.frame);
    const kick = this.el('div', 'cc-kicker', d);
    kick.textContent = 'CHAPTER ' + ch.n + ' — ACT ' + ch.act;
    const t = this.el('div', 'cc-title', d);
    t.textContent = ch.title;
    const arc = this.el('div', 'cc-arc', d);
    arc.textContent = ch.arc;
    const an = this.el('div', 'cc-anime', d);
    an.textContent = ch.anime;
    if (ch.movies && ch.movies.length) {
      const mv = this.el('div', 'cc-anime', d);
      mv.textContent = 'Special events: ' + ch.movies.join(' · ');
    }
    const hint = this.el('div', 'cc-hint', d);
    hint.textContent = 'Press A / tap to continue';
    d.addEventListener('pointerdown', (e) => {
      e.preventDefault();
      this.game.audio.unlock();
      this.game.input.inject('a');
    });
    this.chapterCard = d;
  }

  hideChapterCard() {
    this.chapterCard = null;
    this._ccT = 0;
    if (this.headless || !this.root) return;
    const old = this.root.querySelector('.chaptercard');
    if (old && old.remove) old.remove();
  }

  // UI v2.1: sync the FRAME LAYER's box to the canvas rect. All in-game DOM
  // (dialogue, menus, battle commands, HUD chips/strip, toasts, chapter
  // cards) positions against this layer, so it is geometrically impossible
  // for game chrome to land outside the frame on any viewport. (The v2
  // version of this method only nudged the chips column; the rest of the
  // DOM stayed viewport-anchored — the root cause of defects 2-5.)
  // Recompute only when the canvas rect actually changes (throttled by
  // update(); also called from buildHudChips, init end, window resize and
  // Game.applyLayout).
  _syncChipAnchor() {
    if (!this.frame || typeof document === 'undefined') return;
    const cv = document.getElementById && document.getElementById('game');
    if (!cv || !cv.getBoundingClientRect) return;
    const r = cv.getBoundingClientRect();
    if (!(r.width > 0)) return;
    const key = Math.round(r.left) + ',' + Math.round(r.top) + ',' + Math.round(r.width) + ',' + Math.round(r.height);
    if (key === this._chipAnchorKey) return;
    this._chipAnchorKey = key;
    const s = this.frame.style;
    s.left = Math.round(r.left) + 'px';
    s.top = Math.round(r.top) + 'px';
    s.width = Math.round(r.width) + 'px';
    s.height = Math.round(r.height) + 'px';
  }

  update(dt) {
    this._chipTick = (this._chipTick || 0) + 1;
    if (this._chipTick % 15 === 0) this._syncChipAnchor();
    const input = this.game.input;
    // Summary panel is modal (UI v2): left/right (or X/Y page keys) switch
    // tabs, B / START / ESC closes.
    if (this.summary) {
      if (input.wasPressed('left') || input.wasPressed('pageup')) this.summaryTab(-1);
      else if (input.wasPressed('right') || input.wasPressed('pagedown')) this.summaryTab(1);
      else if (input.wasPressed('b') || input.wasPressed('start') || input.wasPressed('escape')) { this.closeSummary(); }
      return true;
    }
    // Name-entry grid is modal (P0/C3).
    if (this.nameEntry) return true;
    // Login page is modal (P0/B1).
    if (this.loginOpen) return true;
    // Chapter title card is modal (D2: auto-dismisses; A/START/tap dismiss early).
    if (this.chapterCard) {
      this._ccT += dt;
      if (input.wasPressed('a') || input.wasPressed('start') || this._ccT >= 4) {
        this.game.audio.unlock();
        this.hideChapterCard();
      }
      return true;
    }
    // Typewriter advance
    if (this.dlg) {
      const d = this.dlg;
      const speed = TEXT_SPEED_CPS[this.game.state.settings.textSpeed] || 30;
      if (speed < 9999 && d.chars < d.lines[d.idx].length) {
        d.chars = Math.min(d.lines[d.idx].length, d.chars + speed * dt);
        if (!this.headless) this.dlgText.textContent = d.lines[d.idx].slice(0, Math.floor(d.chars));
      }
      if (input.wasPressed('a') || input.wasPressed('start')) {
        this.game.audio.unlock();
        this.advanceDialogue();
        return true;
      }
      if (input.wasPressed('b')) { /* B does not skip story dialogue */ }
      return true; // dialogue modal
    }
    if (this.menu) {
      const grid = !!this.menu.grid;
      if (input.wasPressed('up')) { grid ? this.moveMenuGrid('up') : this.moveMenu(-1); }
      else if (input.wasPressed('down')) { grid ? this.moveMenuGrid('down') : this.moveMenu(1); }
      else if (input.wasPressed('left') && this.menu.battle) { grid ? this.moveMenuGrid('left') : this.moveMenu(-1); }
      else if (input.wasPressed('right') && this.menu.battle) { grid ? this.moveMenuGrid('right') : this.moveMenu(1); }
      else if (input.wasPressed('a') || input.wasPressed('start')) { this.chooseMenu(); return true; }
      else if (input.wasPressed('b') || input.wasPressed('escape')) { this.cancelMenu(); return true; }
      return true; // menu modal
    }
    return false;
  }

  setBattleMode(on) {
    if (this.headless) { this.inBattle = !!on; return; }
    this.inBattle = !!on; // Track B: SYNC.tick defers the conflict sheet out of battle
    this.dpadEl.classList.toggle('hidden', on);
    this.cmdEl.classList.toggle('hidden', !on);
    if (this.root) this.root.classList.toggle('inbattle', on); // hides the HUD strip in battle
    if (this._moodPip) this._moodPip.classList.toggle('hidden', on || !this._moodWanted);
    if (!on) this.hideCommands();
  }

  // Headless test helper: choose a menu item by index.
  debugChoose(i) { this.chooseMenu(i); }
}

// Original 16x16 HUD icons (pixel data, no emoji — contracts §1.3).
function drawHudIcon(x, key) {
  x.imageSmoothingEnabled = false;
  const P = (px, py, w, h, c) => { x.fillStyle = c; x.fillRect(px, py, w, h); };
  if (key === 'bag') {
    P(3, 4, 10, 9, '#8a5a2a'); P(3, 4, 10, 2, '#a8743a'); // sack
    P(6, 2, 4, 3, '#6a4420'); P(5, 1, 6, 2, '#8a5a2a');  // tied top
    P(2, 3, 12, 1, '#241a20'); P(2, 13, 12, 1, '#241a20');
  } else if (key === 'party') {
    P(2, 2, 4, 4, '#e8c832'); P(10, 2, 4, 4, '#e86a8a'); // two heads
    P(2, 7, 4, 2, '#c8a020'); P(10, 7, 4, 2, '#c04a6a');
    P(2, 10, 4, 4, '#5a9ae8'); P(10, 10, 4, 4, '#58c94f');
    P(2, 10, 4, 1, '#3a7ac0'); P(10, 10, 4, 1, '#3aa83a');
  } else if (key === 'dex') {
    P(3, 1, 10, 14, '#c03028'); P(3, 1, 10, 2, '#e04040'); // dex shell
    P(5, 5, 6, 6, '#bfe8f0'); P(6, 6, 4, 4, '#5a9ae8');   // screen
    P(12, 1, 1, 14, '#7a2020');
  } else if (key === 'menu') {
    P(3, 3, 10, 2, '#f0f0f0'); P(3, 7, 10, 2, '#f0f0f0'); P(3, 11, 10, 2, '#f0f0f0');
  }
}


// ---- src/game/auth.mjs ----
// auth.mjs — Track B client: Trainer ID Terminal (login/register/guest) + account menu.
// ADR-005 (accounts + cloud saves) / ADR-010 (guest-first boot, username-only +
// synthetic emails server-side, recovery codes, 13+ age gate, 7d/1d sessions).
// Same-origin API calls ONLY (our own backend paths); the client never touches
// session tokens — the session cookie is HttpOnly and server-managed (AppSec C4).
// No secrets in this file.
// Compiled IN for the vercel target; compile-time STRIPPED for the guest target
// (see scripts/build.mjs — the auth block markers plus the boolean compile flag).
//
// ---- Output-encoding contract (AppSec C12) ----
// EVERY player-controlled string (usernames, recovery codes, any echoed input)
// is rendered via textContent / createElement ONLY — never innerHTML, never
// string-concatenated HTML. This file performs zero innerHTML assignments.
// The QA stored-XSS corpus covers the login/register/recovery/account surfaces.

const AUTH_ENABLED = false;

// ---- stub surface: compiled into BOTH targets (the guest bundle keeps only this) ----
// Guest behavior is byte-identical to Track A: the terminal is absent, so the
// login path degrades straight to guest. Zero network, zero auth code.
const AUTH = {
  user: null,          // logged-in username, or null
  unavailable: false,  // backend reports auth_unavailable (503 / health flag)
  _bannerShown: false,
  init(game) {},                                    // guest build: no-op (no network)
  showLoginPanel(ui, game, cb) { cb('guest'); },    // guest build: straight to guest
  enhanceGuestBanner(ui) {},                        // guest build: no-op
  openAccountMenu(game) {},                         // guest build: no-op
  signOut(game) { return Promise.resolve({ ok: false, reason: 'guest-build' }); },
  isLoggedIn() { return false; },
  onSessionExpired(game) {},                        // guest build: no sessions exist
  onUnavailable() {},                               // guest build: nothing to announce
};



// ---- src/game/sync.mjs ----
// sync.mjs — Track B cloud-save sync engine (architecture §3.3).
// Local-first: the game NEVER waits on network. Writes go to the local cache
// instantly; cloud PUTs happen in the background with a 60s idle throttle.
// Same-origin backend calls only. No silent last-write-wins: genuine divergence
// opens the conflict sheet (wireframes §9). Compiled IN for the vercel target;
// compile-time STRIPPED for the guest target (see scripts/build.mjs).
//
// ---- Output-encoding contract (AppSec C12) ----
// Player-controlled strings are rendered via textContent / createElement ONLY
// (helpers live in auth.mjs: authEl/authText). Zero innerHTML in this file.
//
// ---- Payload download (GET save?slot=N on the API) ----
// New-device pull (the hotel-phone test, US-N1) downloads the payload via
// GET save?slot=N -> {slot, version, payload, updatedAt}; 404 when the slot
// is empty. Pull paths still degrade honestly on failure (toast + keep
// local) — push, claimGuest, queue, conflict-sheet, and same-device re-login
// never block on network.


const SYNC = {
  activeSlot: 1,
  init(game) {},                                   // guest build: no-op
  tick(game) {},                                  // guest build: no-op
  afterLocalSave(game) {},                        // guest build: no-op
  onHidden(game) {},                              // guest build: no-op
  saveLocal(game) { return { ok: false, reason: 'guest-build' }; },
  syncNow(game, manual) { return Promise.resolve({ ok: false, reason: 'guest-build' }); },
  runLoginMerge(game, mode, done) { done({ load: 'fallback' }); },
  clearSession() {},
  getSlots() { return []; },
  localPayload(game) { return game ? game.state : null; },
  renderDot() {},
};



// ---- src/game/title.mjs ----
// title.mjs — boot disclaimer card (GC verbatim, §2a) + title screen.
// The legal card renders in the shell before any interactive element and is not
// skippable-in-one-tap on first boot (readable dwell >= 3 seconds).
// Title flow (UI v2, Platinum standard): logo plate + framed keyart + a
// blinking PRESS START prompt; the menu (New Game / Continue / Options)
// appears only after Start/A (or a tap, which injects 'a') is pressed.

const DISCLAIMER_BOOT = [
  "ASH'S JOURNEY",
  'An unofficial fan homage. Not affiliated with, endorsed by, or connected to',
  'Nintendo, Creatures Inc., or GAME FREAK inc.',
  '',
  'Pok\u00e9mon, Pikachu, and all character names are trademarks of',
  'Nintendo / Creatures Inc. / GAME FREAK inc.',
  'This is a free, non-commercial fan project made with love by fans.',
  'No purchase is required or accepted. Please support the official releases.',
];

const DISCLAIMER_CREDITS = [
  'LEGAL',
  '',
  'This game is an unofficial fan work and is not affiliated with, endorsed by,',
  'sponsored by, or connected to Nintendo Co., Ltd., Creatures Inc., or',
  'GAME FREAK inc. Pok\u00e9mon and all related names, characters, and indicia are',
  'trademarks of their respective owners.',
  '',
  'All code, artwork, music, sound effects, and dialogue in this game are',
  'original creations made for this fan project; no game assets were copied or',
  'extracted from any official release.',
  '',
  'This game is free, carries no advertising, accepts no payments, donations,',
  'or tips, and collects no personal data for commercial purposes.',
  '',
  'If you represent a rights holder and have concerns about this project,',
  'contact the developer directly and we will respond promptly.',
  '// OQ-grade: rights-holder contact resolves to an owner-designated address',
  '// before any public share. Not a dead link in a signed build.',
];

const GAME_TITLE = "ASH'S JOURNEY";
const GAME_SUBTITLE = 'An Unofficial Fan Homage';
// ADR-012: personal-edition marker. The build substitutes the EDITION_MARKER
// compile-time token with a quoted JS string literal ("NAMAN'S EDITION" for the
// personal target, '' for every other target — guest and vercel show nothing).
// Original text, subtle: a small gold ribbon drawn under the subtitle on the
// title screen. The GC-verbatim disclaimers above stay byte-identical.
const EDITION_MARKER = "NAMAN'S EDITION";

// ---- Title recomposition helpers (Seat B) ----
// Shared design system: UI font stack + ink/paper/gold. UI v2 (Platinum
// standard): Galmuri leads the stack, matching the canvas renderer
// (src/engine/render.mjs UI_FONT_STACK) so measured plates fit drawn text.
const FONT_STACK = "'PtGalmuri', 'PtGothic', system-ui, -apple-system, \"Segoe UI\", Roboto, \"Helvetica Neue\", Arial, sans-serif";
const PAPER = '#f8f8f0';
const GOLD = '#e8c832';

function fontFor(size, bold) {
  return (bold ? '700 ' : '400 ') + size + 'px ' + FONT_STACK;
}

// Measure with the shared UI stack so plates fit what the renderer draws.
// Headless-safe: falls back to a per-glyph estimate when measureText is a stub.
function measureText(r, str, size, bold) {
  try {
    const c = r.ctx;
    c.font = fontFor(size, bold);
    const wdt = Math.ceil(c.measureText(str).width);
    if (wdt > 0) return wdt;
  } catch (e) { /* headless stub — estimate below */ }
  return Math.ceil(str.length * size * 0.58);
}

// Dawn sky: smooth vertical ramp pre-rendered ONCE per viewport size to
// an offscreen canvas (cached, keyed by size) with a subtle ordered-dither
// pass (4x4 Bayer) so banding never shows. Palette family preserved:
// #2a1a3a -> #5a2a4a -> #a04a3a -> #e08a4a -> #f8c86a.
// The ramp is painted as per-row interpolated fills (no gradient API —
// the QA gate bans gradient/glow calls bundle-wide; a cached 1px-row ramp
// is visually identical and costs one offscreen canvas).
// Returns null when no real canvas exists (headless) — caller falls back
// to the flat band fills.
const skyCache = new Map();
const BAYER4 = [
  [0, 8, 2, 10],
  [12, 4, 14, 6],
  [3, 11, 1, 9],
  [15, 7, 13, 5],
];
const SKY_STOPS = [
  [0, 0x2a, 0x1a, 0x3a],
  [0.3, 0x5a, 0x2a, 0x4a],
  [0.55, 0xa0, 0x4a, 0x3a],
  [0.78, 0xe0, 0x8a, 0x4a],
  [1, 0xf8, 0xc8, 0x6a],
];
function skyRowColor(t) {
  for (let i = 1; i < SKY_STOPS.length; i++) {
    if (t <= SKY_STOPS[i][0]) {
      const [t0, r0, g0, b0] = SKY_STOPS[i - 1];
      const [t1, r1, g1, b1] = SKY_STOPS[i];
      const f = (t - t0) / (t1 - t0 || 1);
      return [Math.round(r0 + (r1 - r0) * f), Math.round(g0 + (g1 - g0) * f), Math.round(b0 + (b1 - b0) * f)];
    }
  }
  const last = SKY_STOPS[SKY_STOPS.length - 1];
  return [last[1], last[2], last[3]];
}
function dawnSky(w, h) {
  const key = w + 'x' + h;
  const hit = skyCache.get(key);
  if (hit) return hit;
  let cv = null;
  try {
    if (typeof document === 'undefined' || !document.createElement) return null;
    cv = document.createElement('canvas');
    if (!cv || typeof cv.getContext !== 'function') return null;
    cv.width = w; cv.height = h;
    const c = cv.getContext('2d');
    if (!c) return null;
    for (let y = 0; y < h; y++) {
      const [r, g, b] = skyRowColor(h <= 1 ? 0 : y / (h - 1));
      c.fillStyle = 'rgb(' + r + ',' + g + ',' + b + ')';
      c.fillRect(0, y, w, 1);
    }
    // Ordered-dither pass: nudge each pixel by its Bayer threshold so the
    // gradient steps dissolve instead of banding.
    try {
      const img = c.getImageData(0, 0, w, h);
      const d = img.data;
      for (let y = 0; y < h; y++) {
        for (let x = 0; x < w; x++) {
          const off = ((BAYER4[y & 3][x & 3] / 16) - 0.5) * 7;
          const i = (y * w + x) * 4;
          d[i] = Math.max(0, Math.min(255, d[i] + off));
          d[i + 1] = Math.max(0, Math.min(255, d[i + 1] + off));
          d[i + 2] = Math.max(0, Math.min(255, d[i + 2] + off));
        }
      }
      c.putImageData(img, 0, 0);
    } catch (e) { /* dither is cosmetic — gradient alone is fine */ }
  } catch (e) {
    return null;
  }
  skyCache.set(key, cv);
  return cv;
}

// P1/A5: legal card renders at >=14px. The GC-verbatim DISCLAIMER_BOOT wording
// is preserved word-for-word; only the line-wrap changes, paginated across the
// 3s dwell (page flips at 1.5s, still non-skippable).
const LEGAL_PAGES = [
  [
    "ASH'S JOURNEY",
    'An unofficial fan homage.',
    'Not affiliated with, endorsed',
    'by, or connected to Nintendo,',
    'Creatures Inc., or',
    'GAME FREAK inc.',
  ],
  [
    'Pok\u00e9mon, Pikachu, and all',
    'character names are trademarks',
    'of Nintendo / Creatures Inc. /',
    'GAME FREAK inc.',
    'This is a free, non-commercial',
    'fan project made with love',
    'by fans.',
    'No purchase is required or',
    'accepted. Please support the',
    'official releases.',
  ],
];

class BootScene {
  enter() {
    this.t = 0;
    this.phase = 'legal'; // legal -> title
    this.titleStage = 'pressStart'; // title sub-state: 'pressStart' -> 'menu'
    this.ready = false;  // interactive only after dwell
    this.menuIdx = 0;
    this.game.ui.log.push({ ui: 'boot' });
  }
  update(dt) {
    this.t += dt;
    const input = this.game.input;
    if (this.phase === 'legal') {
      if (this.t >= 3) this.ready = true;
      if (this.ready && (input.wasPressed('a') || input.wasPressed('start'))) {
        this.phase = 'title';
        this.titleStage = 'pressStart';
        this.t = 0;
        this.game.audio.unlock();
        this.game.audio.playMusic('title-theme'); // original score; unlock gate satisfied by the gesture
      }
      return;
    }
    // Platinum title flow: the menu stays hidden behind the blinking
    // PRESS START prompt until Start/A (or a tap, which injects 'a') is
    // pressed. The opening press only opens the menu — it never selects.
    if (this.titleStage !== 'menu') {
      const aP = input.wasPressed('a');
      const sP = input.wasPressed('start');
      input.wasPressed('up'); input.wasPressed('down'); // swallow nav edges so none leak into the opened menu
      if (aP || sP) {
        this.titleStage = 'menu';
        this.game.audio.unlock();
        // Title music starts on the legal->title transition above;
        // playMusic no-ops when the same track is already playing, so
        // this only starts it if that transition somehow did not.
        this.game.audio.playMusic('title-theme');
      }
      return;
    }
    // title menu
    const items = this.menuItems();
    if (input.wasPressed('up')) { this.menuIdx = (this.menuIdx + items.length - 1) % items.length; }
    if (input.wasPressed('down')) { this.menuIdx = (this.menuIdx + 1) % items.length; }
    if (input.wasPressed('a') || input.wasPressed('start')) {
      const it = items[this.menuIdx];
      this.game.audio.unlock();
      // P0/B1: title menu routes through the Trainer ID Terminal (guest-functional stub).
      if (it.value === 'new') this.game.openLogin('new');
      else if (it.value === 'continue') this.game.openLogin('continue');
      else if (it.value === 'options') this.game.openOptions();
    }
  }
  menuItems() {
    const items = [{ label: 'New Game', value: 'new' }];
    if (this.game.store.exists()) items.push({ label: 'Continue', value: 'continue' });
    items.push({ label: 'Options', value: 'options' });
    return items;
  }
  render(r) {
    const g = this.game;
    // Transform discipline: like every other scene, the title/legal screens
    // draw inside begin()/end() so the renderer's display-scale transform
    // applies (camera pinned to the origin — this scene has no world camera).
    const pcx = r.camX, pcy = r.camY; r.camX = 0; r.camY = 0;
    r.begin();
    if (this.phase === 'legal') {
      this.renderLegal(r);
      r.end(); r.camX = pcx; r.camY = pcy;
      return;
    }
    // ---- Sky: cached dithered gradient (flat bands only as headless fallback) ----
    const w = r.viewW, h = r.viewH;
    const cx = w / 2;
    const sky = dawnSky(w, h);
    let skyDrawn = false;
    if (sky) {
      try { r.ctx.drawImage(sky, 0, 0); skyDrawn = true; } catch (e) { /* fall through to bands */ }
    }
    if (!skyDrawn) {
      const bands = ['#2a1a3a', '#5a2a4a', '#a04a3a', '#e08a4a', '#f8c86a'];
      for (let i = 0; i < bands.length; i++) {
        g.ctx2dfill(bands[i], 0, (h * i) / bands.length, w, h / bands.length + 1);
      }
    }

    // ---- Vertical layout (all sizes): header plate / keyart / menu / footer ----
    // Header block: title, subtitle, optional edition ribbon — all centered.
    // Compact heights (landscape 256x192) tighten paddings so the keyart
    // band keeps a usable size instead of being squeezed out.
    const compact = h < 210;
    const titleSize = w >= 320 ? 22 : 19;
    const titleY = compact ? 7 : 9;
    const subY = titleY + titleSize + 4;
    const hasEd = !!EDITION_MARKER;
    const edY = subY + 19;
    const edH = 20;
    const contentBottom = hasEd ? edY + edH : subY + 16;
    const plateY = 4;
    const plateH = contentBottom - plateY + (compact ? 4 : 6);
    const keyTop = plateY + plateH + (compact ? 4 : 6);

    // Footer line first (reserves its band so nothing else can clip into it).
    const footerY = h - 20;

    // Menu panel below the keyart: sized to its rows, centered.
    const items = this.menuItems();
    const rowH = compact ? 18 : 19;
    const menuPadY = compact ? 4 : 6;
    const menuH = items.length * rowH + menuPadY * 2;
    const menuBottom = footerY - (compact ? 4 : 6);
    const menuY = menuBottom - menuH;
    let menuW = 150;
    for (const it of items) {
      menuW = Math.max(menuW, measureText(r, it.label, 14, true) + 44);
    }
    menuW = Math.min(menuW, w - 24);
    const menuX = Math.round(cx - menuW / 2);
    const showMenu = this.titleStage === 'menu';
    // PRESS START band: reserved above the footer while the menu is hidden;
    // in that sub-state the keyart band reclaims the rest of the menu's space.
    const psH = 22;
    const psY = menuBottom - psH + 3;

    // ---- Keyart: centered in the middle band, overlapped by nothing ----
    const kBottom = showMenu ? menuY - 6 : menuBottom - psH - 6;
    const availH = kBottom - keyTop;
    const availW = w - 32;
    if (availH >= 20 && availW >= 32) {
      const s = Math.min(availW / 192, availH / 144);
      const drawW = Math.round(192 * s);
      const drawH = Math.round(144 * s);
      const kx = Math.round(cx - drawW / 2);
      const ky = Math.round(keyTop + (availH - drawH) / 2);
      const keyart = (typeof document !== 'undefined' && typeof artCanvas === 'function')
        ? artCanvas(document, 'title-keyart', 3, false) : null;
      if (keyart) {
        r.blitS(keyart, kx, ky, drawW, drawH);
      } else {
        // Fallback silhouettes (original shapes), composed inside the same
        // keyart rect so the layout holds when key art is absent.
        g.ctx2dcircle(cx, ky + drawH * 0.36, Math.max(10, drawH * 0.18), '#ffe9a8');
        g.ctx2dcircle(cx - drawW * 0.08, ky + drawH * 0.66, 6, '#1a1a22');
        g.ctx2drect(cx - drawW * 0.08 - 6, ky + drawH * 0.66 + 4, 11, 12, '#1a1a22');
        g.ctx2dcircle(cx + drawW * 0.09, ky + drawH * 0.7, 4, '#1a1a22');
      }
      // Platinum border treatment around the keyart rect (strokeRect only):
      // navy outer line + silver-blue inner line, mirroring the r.panel frame.
      const kc = r.ctx;
      kc.strokeStyle = '#2b3040';
      kc.lineWidth = 2;
      kc.strokeRect(kx + 1, ky + 1, drawW - 2, drawH - 2);
      kc.strokeStyle = '#8d9bbf';
      kc.lineWidth = 1;
      kc.strokeRect(kx + 3.5, ky + 3.5, drawW - 7, drawH - 7);
    }

    // ---- Header plate + centered title / subtitle / edition ribbon ----
    let plateW = Math.max(
      measureText(r, GAME_TITLE, titleSize, true),
      measureText(r, GAME_SUBTITLE, 14, false),
    );
    if (hasEd) plateW = Math.max(plateW, measureText(r, EDITION_MARKER, 14, false) + 16);
    plateW = Math.min(plateW + 28, w - 12);
    const plateX = Math.round(cx - plateW / 2);
    r.panel(plateX, plateY, plateW, plateH, 'rgba(16,16,28,0.62)', 'rgba(232,200,50,0.55)');
    r.text(GAME_TITLE, cx, titleY, { size: titleSize, bold: true, align: 'center', color: '#fff' });
    // Platinum logo treatment: a subtle gold rule under the title,
    // sized to the measured Galmuri title text.
    const titleW = measureText(r, GAME_TITLE, titleSize, true);
    g.ctx2dfill('rgba(232,200,50,0.55)', Math.round(cx - titleW / 2), titleY + titleSize + 1, titleW, 2);
    r.text(GAME_SUBTITLE, cx, subY, { size: 14, align: 'center', color: '#ffe9a8' });
    if (hasEd) {
      // ADR-012 personal-edition ribbon: measured dark band + gold underline,
      // centered under the subtitle. Guest/vercel bundles have
      // EDITION_MARKER = '' and skip this entirely.
      const tw = measureText(r, EDITION_MARKER, 14, false);
      const rw = tw + 16;
      const rx = Math.round(cx - rw / 2);
      g.ctx2dfill('rgba(8,8,14,0.72)', rx, edY, rw, edH);
      g.ctx2dfill(GOLD, rx, edY + edH - 2, rw, 2);
      r.text(EDITION_MARKER, cx, edY + 3, { size: 14, align: 'center', color: '#ffe9a8' });
    }

    if (showMenu) {
      // ---- Menu: clean centered panel, gold-tinted highlight bar on selection ----
      r.panel(menuX, menuY, menuW, menuH, 'rgba(18,18,30,0.88)', GOLD);
      items.forEach((it, i) => {
        const rowY = menuY + menuPadY + i * rowH;
        const sel = i === this.menuIdx;
        if (sel) {
          g.ctx2dfill('rgba(232,200,50,0.30)', menuX + 4, rowY, menuW - 8, rowH - 2);
          g.ctx2dfill(GOLD, menuX + 4, rowY, 3, rowH - 2);
        }
        r.text(it.label, cx, rowY + 2, {
          size: 14, bold: sel, align: 'center',
          color: sel ? '#ffe9a8' : PAPER,
        });
      });
    } else {
      // ---- PRESS START: blinking prompt in the band above the footer ----
      // ~1s blink period (0.5s on / 0.5s off — the legal card's pulse
      // idiom); steady-on under reduced motion.
      const reduced = !!(g.state.settings && g.state.settings.reducedMotion);
      if (reduced || Math.floor(this.t * 2) % 2 === 0) {
        r.text('PRESS START', cx, psY, { size: 16, bold: true, align: 'center', color: '#ffe9a8' });
      }
    }

    // ---- Footer: centered, inset from both edges, never clipped ----
    r.text('Unofficial fan homage.', cx, footerY, { size: 14, align: 'center', color: '#f5efdc' });
    r.end(); r.camX = pcx; r.camY = pcy;
  }
  renderLegal(r) {
    const w = r.viewW, h = r.viewH;
    r.panel(6, 6, w - 12, h - 12, '#101018', '#e8c832');
    const page = this.t >= 1.5 ? 1 : 0; // P1/A5: paginated 14px legal copy
    let y = 18;
    for (const line of LEGAL_PAGES[page]) {
      const isTitle = page === 0 && line === "ASH'S JOURNEY";
      if (isTitle) {
        r.text(line, w / 2, y, { size: 14, bold: true, align: 'center', color: '#e8c832' });
      } else {
        r.text(line, 14, y, { size: 14, color: '#f0f0f0' });
      }
      y += 18;
    }
    if (this.ready) {
      const pulse = Math.floor(this.t * 2) % 2 === 0;
      if (pulse) r.text('Press A / tap to continue', 14, h - 24, { size: 14, color: '#e8c832' });
    }
  }
}


// ---- src/game/intro.mjs ----
// intro.mjs — professor intro, name entry, starter moment (Pikachu refuses the ball).
// Original dialogue. P0/C3: name entry is an A-Z grid keyboard (44px keys,
// physical-keyboard support, 8-char max, validation shake). P1/C4: rival name
// entry reuses the grid. P1/C5: "Skip intro (veteran)" offered on replay
// (default OFF); hold START 1s during the intro offers a skip confirm.


class IntroScene {
  enter() {
    this.step = 'ask-skip';
    this.lineIdx = 0;
    this.name = 'ASH';
    this.rival = 'GARY';
    this._startHeld = 0;
    this.game.ui.log.push({ ui: 'intro' });
    const g = this.game;
    if (g.skipIntroVeteran && !g.ui.headless) {
      // P1/C5: offered, never silent — default OFF (watch the intro).
      this.step = 'offer-skip';
      g.ui.showMenu('A save already exists.', [
        { label: 'Watch the intro', value: 'watch' },
        { label: 'Skip intro (veteran)', value: 'skip' },
      ], (v) => {
        if (v === 'skip') { this.finishIntro(); return; }
        this.begin();
      });
      return;
    }
    if (g.skipIntroVeteran) { this.finishIntro(); return; } // headless: keep harness timing
    this.begin();
  }

  begin() {
    const g = this.game;
    this.step = 'professor';
    this._startHeld = 0;
    const lines = INTRO_SCRIPT.lines.map((l) => l.replace('{player}', this.name));
    g.ui.say(lines, () => this.nameEntry(), INTRO_SCRIPT.professor);
  }

  nameEntry() {
    // P0/C3: full A-Z grid ships now (replaces the Wave-1 two-option menu).
    const g = this.game;
    this.step = 'name';
    g.ui.showNameEntry('Your name?', 'ASH', 8, (value) => {
      this.name = value;
      g.state.player.name = this.name;
      if (g.ui.headless) {
        // Harness path: the intro harness asserts starter dialogue immediately
        // after the name choice, so the rival keeps its default here.
        this.rivalEntryDone();
        return;
      }
      // P1/C4: rival name entry reuses the same grid.
      this.step = 'rival';
      g.ui.showNameEntry("Rival's name?", 'GARY', 8, (rv) => {
        this.rival = rv;
        g.state.player.rivalName = this.rival;
        this.rivalEntryDone();
      });
    });
  }

  rivalEntryDone() {
    this.step = 'starter';
    this.starterMoment();
  }

  starterMoment() {
    const g = this.game;
    const lines = INTRO_SCRIPT.starterMoment.map((l) => l.replace('{player}', this.name));
    g.ui.say(lines, () => {
      // Partner joins OUTSIDE the ball system (EP014 homage — hard rule).
      const pikachu = makeMon('partner', 5, SPECIES, MOVES);
      g.state.party.push(pikachu);
      const sp = SPECIES.partner;
      dexRegister(g.state.dex, 'seen', sp.dexNo);
      dexRegister(g.state.dex, 'caught', sp.dexNo);
      g.state.story.flags.metPartner = true;
      g.state.story.flags.refusedBall = true;
      g.audio.playSfx('dex-register');
      g.ui.toast(sp.name + ' joined your party!');
      this.finishIntro();
    }, INTRO_SCRIPT.professor);
  }

  finishIntro() {
    const g = this.game;
    g.state.story.flags.introDone = true;
    g.state.story.chapter = 0; // D2: Act I opens on Chapter 1 (ADR-015 spine)
    g.state.story.position = { map: 'pallet', x: 7, y: 7, dir: 'down' };
    g.saveGame(true);
    g.startOverworld({ chapterCard: 0 });
  }

  update(dt) {
    // P1/C5: hold START 1s during the professor intro -> "Skip intro?" confirm.
    // Reduced motion: the confirm still applies (no animation to replace).
    const g = this.game;
    if (this.step !== 'professor' || !g.ui.dialogueOpen) { this._startHeld = 0; return; }
    if (g.input.isHeld('start')) {
      this._startHeld += dt;
      if (this._startHeld >= 1) {
        this._startHeld = 0;
        this.step = 'confirm-skip';
        g.ui.closeDialogue();
        g.ui.showMenu('Skip the intro?', [
          { label: 'Keep watching', value: 'no' },
          { label: 'Skip intro', value: 'yes' },
        ], (v) => {
          if (v === 'yes') { this.finishIntro(); return; }
          this.begin(); // restart the professor lines
        });
      }
    } else {
      this._startHeld = 0;
    }
  }

  render(r) {
    // Professor's lab: a real interior in the same flat style — warm wall
    // (upper 2/3), darker floor (lower 1/3) with a baseboard line, simple
    // original lab props, and the professor himself, large and centered
    // above the dialogue zone. The speaker name lives on the DOM dialogue
    // name plate (ui.say receives INTRO_SCRIPT.professor) — no bare canvas
    // name text here. All art access is guarded like title.mjs so headless
    // node suites stay green when artCanvas/document are unavailable.
    // Transform discipline: draw inside begin()/end() like every other
    // scene, camera pinned to the origin (no world camera here).
    const pcx = r.camX, pcy = r.camY; r.camX = 0; r.camY = 0;
    r.begin();
    const g = this.game;
    const w = r.viewW, h = r.viewH;
    const cx = w / 2;
    const floorY = Math.round((h * 2) / 3);
    const floorH = h - floorY;

    // --- Interior shell ---
    g.ctx2dfill('#6a5741', 0, 0, w, floorY); // wall (warm lab tone)
    g.ctx2dfill('#5d4b37', 0, 0, w, 8); // soft ceiling shadow band
    g.ctx2dfill('#382c21', 0, floorY, w, floorH); // floor (darker)
    // Floor perspective lines (flat, receding boards).
    g.ctx2dfill('#463829', 0, floorY + Math.round(floorH * 0.38), w, 2);
    g.ctx2dfill('#2f251c', 0, floorY + Math.round(floorH * 0.72), w, 2);
    // Baseboard: light strip + dark seam where wall meets floor.
    g.ctx2dfill('#8a7458', 0, floorY - 4, w, 4);
    g.ctx2dfill('#241a12', 0, floorY, w, 2);

    // --- Prop 1: cabinet / shelf silhouette (left), muted bottles ---
    {
      const cabW = 44, cabH = 54, cabX = 8, cabY = floorY - cabH;
      g.ctx2dfill('#4c5a48', cabX, cabY, cabW, cabH);
      g.ctx2dfill('#333d31', cabX, cabY + cabH - 3, cabW, 3);
      g.ctx2dfill('#3c4838', cabX + 3, cabY + 17, cabW - 6, 2); // shelf lines
      g.ctx2dfill('#3c4838', cabX + 3, cabY + 33, cabW - 6, 2);
      g.ctx2dfill('#7a9a8a', cabX + 7, cabY + 8, 5, 8); // bottles (muted)
      g.ctx2dfill('#c8a86a', cabX + 16, cabY + 9, 4, 7);
      g.ctx2dfill('#8a7a9a', cabX + 27, cabY + 8, 5, 8);
      g.ctx2dfill('#a05a3c', cabX + 8, cabY + 24, 6, 8);
      g.ctx2dfill('#7a9a8a', cabX + 24, cabY + 25, 5, 7);
      g.ctx2dfill('#c8c8d0', cabX + 10, cabY + 40, 10, 9); // stacked books/papers
      g.ctx2dfill('#8a7458', cabX + 12, cabY + 42, 10, 2);
    }

    // --- Prop 2: potted plant (left of the professor) ---
    {
      const potW = 16, potX = 58, potY = floorY - 10;
      g.ctx2dcircle(potX + 3, potY - 5, 5, '#4a7a3a'); // leaves
      g.ctx2dcircle(potX + potW - 3, potY - 5, 5, '#4a7a3a');
      g.ctx2dcircle(potX + potW / 2, potY - 9, 5, '#3c6630');
      g.ctx2dfill('#8a4a32', potX, potY, potW, 10); // pot
      g.ctx2dfill('#a05a3c', potX - 2, potY, potW + 4, 3); // rim
    }

    // --- Prop 3: lab machine with a glass dome (right) ---
    {
      const mW = 48, mH = 46, mX = w - 56, mY = floorY - mH;
      g.ctx2dcircle(mX + mW / 2, mY + 15, 13, 'rgba(170,205,220,0.55)'); // dome
      g.ctx2dcircle(mX + mW / 2, mY + 16, 6, '#d8b84a'); // specimen glow inside
      g.ctx2dfill('#5d646e', mX, mY + 24, mW, mH - 24); // base unit
      g.ctx2dfill('#4a5058', mX + 4, mY + 28, mW - 8, 8); // control inset
      g.ctx2dcircle(mX + mW - 9, mY + 32, 2, '#7ac86a'); // status light
      g.ctx2dfill('#33383f', mX, mY + mH - 3, mW, 3); // feet shadow
    }

    // --- Professor: large portrait, centered above the dialogue zone ---
    const scale = (w >= 320 || h >= 250) ? 5 : 4; // 24x24 art -> 120 or 96 px
    const size = 24 * scale;
    const animT = (g && typeof g._animT === 'number') ? g._animT : 0;
    const bob = Math.round(Math.sin(animT / 600) * 1); // gentle +/-1px idle
    const px = Math.round(cx - size / 2);
    const py = floorY + 6 - size + bob;
    // Soft oval shadow / plate grounding the portrait on the floor line.
    try {
      const c = r.ctx;
      c.fillStyle = 'rgba(20,14,8,0.35)';
      c.beginPath();
      if (typeof c.ellipse === 'function') c.ellipse(cx, floorY + 8, size * 0.42, 6, 0, 0, Math.PI * 2);
      else c.arc(cx, floorY + 8, size * 0.3, 0, Math.PI * 2);
      c.fill();
    } catch (e) {
      g.ctx2dfill('rgba(20,14,8,0.35)', cx - size * 0.4, floorY + 5, size * 0.8, 5);
    }
    let spr = null;
    try {
      if (typeof document !== 'undefined' && typeof artCanvas === 'function') {
        spr = artCanvas(document, 'portrait-hawthorn', scale, false);
      }
    } catch (e) { spr = null; }
    if (spr) {
      r.blitS(spr, px, py, size, size);
    } else {
      // Fallback silhouette (original shapes) when portrait art is absent:
      // head + lab coat, same footprint as the portrait treatment.
      g.ctx2dcircle(cx, py + size * 0.32, size * 0.17, '#c8c4bc'); // hair
      g.ctx2dcircle(cx, py + size * 0.36, size * 0.14, '#f0c090'); // face
      g.ctx2dfill('#f0f0f0', cx - size * 0.21, py + size * 0.5, size * 0.42, size * 0.46); // coat
      g.ctx2dfill('#7a8a5a', cx - size * 0.05, py + size * 0.56, size * 0.1, size * 0.3); // shirt
    }
    r.end(); r.camX = pcx; r.camY = pcy;
  }
}


// ---- src/game/battle.mjs ----
// battle.mjs — turn-based battle state machine (architecture §2.2).
// States: intro | command | moves | bag | party | catchseq | resolve | faint |
//          xp | victory | defeat | run. Transitions are data-ish, no spaghetti.


const HP_DRAIN_PER_SEC = 90; // ADR-004 feel budget

// UI v2 (Platinum standard): status chips for the databox — a solid DS-toned
// rect with the white bold 3-letter code as TEXT on it (never color alone).
// NOTE: burn keeps the legacy 'BUR' code — verify-slice's QA plate check
// asserts that exact text for a burned mon, so the DS 'BRN' abbreviation is
// the one deliberate deviation from Platinum spelling in this table.
const STATUS_CHIPS = {
  burn: ['BUR', '#c84028'],
  poison: ['PSN', '#9848a8'],
  badlyPoisoned: ['PSN', '#7038a0'],
  paralysis: ['PAR', '#b8860b'],
  sleep: ['SLP', '#68707e'],
  freeze: ['FRZ', '#2f88b8'],
};

// Fraction of the current level's XP bar filled (gameux §4.2).
function xpFracOf(mon, add) {
  const sp = SPECIES[mon.speciesId];
  const lo = xpForLevel(sp.growth, mon.level);
  const hi = xpForLevel(sp.growth, mon.level + 1);
  if (hi <= lo) return 1;
  return Math.max(0, Math.min(1, (mon.xp + (add || 0) - lo) / (hi - lo)));
}

class BattleScene {
  constructor(opts) {
    this.kind = opts.kind; // 'wild' | 'trainer'
    this.foeMon = opts.foe;
    this.trainer = opts.trainer || null;
    this.safari = !!opts.safari; // Safari Zone: no ally actions, BALL/BAIT/ROCK/RUN
    this.onEnd = opts.onEnd || null; // story-event continuation callback
    this.uncatchable = !!opts.uncatchable; // scripted presences (the Tower ghost)
    this.onSafariAction = opts.onSafariAction || null; // overworld spends a step per action
    this.safariBait = false;
    this.safariRock = false;
    // ADR-020: real-time mode is the default battle flow; the tutorial and
    // Safari command battles stay on the classic engine, and the player can
    // choose Classic in Settings (opts.rt === false).
    this.rtMode = !opts.tutorial && !opts.safari && opts.rt !== false;
    this.rt = null;
    this.tutorial = !!opts.tutorial; // GD: scripted first-catch gate — certainty, not luck
    this.returnTo = opts.returnTo;
    this.trainerIdx = 0;
  }

  enter() {
    const g = this.game;
    g.ui.setBattleMode(true);
    this.state = 'intro';
    this.t = 0;
    this.msg = '';
    g.audio.playMusic(this.kind === 'trainer' ? 'battle-trainer-theme' : 'battle-wild-theme', { area: false });
    if (this.kind === 'trainer') {
      const t0 = this.trainer.team[0];
      this.foeMon = makeMon(t0.species, t0.level, SPECIES, MOVES);
      if (t0.nickname) this.foeMon.nickname = t0.nickname; // e.g. the duo's named mons
    }
    this.ally = this.firstAble(g);
    this.foe = this.foeMon;
    this.foeStages = { atk: 0, def: 0, spa: 0, spd: 0, spe: 0, acc: 0, eva: 0 };
    this.allyStages = this.ally.stages;
    if (this.allyStages.acc === undefined) { this.allyStages.acc = 0; this.allyStages.eva = 0; }
    // Fidelity pack (ADR-018): XP is split among participants — mons that
    // were active against THIS foe. Reset per foe in afterFaintFoe.
    this.participants = new Set([this.ally]);
    this.runAttempts = 0;
    this.turn = 1;
    this.actions = [];
    this.animQ = [];
    this.hpAnim = { ally: this.ally.hp, foe: this.foe.hp };
    this.xpAnim = 0;
    this.shakeT = 0;
    this.flashT = 0;
    this.fadeT = 0;      // P0/E11: reduced-motion substitute for shake/flash (100ms fade)
    this.atkFx = null;   // { side, t } — README attack transform: 1.2x for 3 frames then back
    this.impactFx = null; // { side, t } — README impact: white palette-swap 2 frames + shake
    this.faintFx = null;  // { side, spr, t } — README faint: sink 8px + fade to 0 over 20 frames
    this.xpBarAnim = null; // [{ mon, from, to }] — P0/E3 XP bar ease-out over 600ms
    this.xpFlashT = 0;    // level-up flash on the XP bar
    this._lastMoveIdx = 0; // P0/E9: cursor memory (last-used move pre-selected)
    this._lowHpPulseT = 0; // P1/E7: plate pulse on first red crossing (skipped under reduced motion)
    this._tutFightDone = false; // P0/C7: guided first-catch tutorial stage flags
    this._tutStage = null;
    this.catchFx = null; // P1/E10: success starburst after the catch click
    this.catchState = null;
    this.fled = false;
    this.critCap = false;
    this.log = [];
    g.ui.log.push({ ui: 'battle', kind: this.kind, foe: this.foe.speciesId });
    const foeName = displayName(this.foe, SPECIES);
    g.audio.playCry(this.foe.speciesId);   // synthesized cry, never sampled
    g.audio.playCry(this.ally.speciesId);
    if (this.tutorial) {
      // Scripted first-catch gate: the tips teach the loop (weaken -> throw),
      // the engine guarantees the outcome (endure + weakened auto-catch).
      this.say('Wild ' + foeName + ' appeared!', () => {
        this.say("AIDE (via Pokegear): There's your first catch! One Thunder Shock to weaken it —", () => {
          this.say('— then open the BAG and throw a Poke Ball while its HP is yellow!', () => this.toCommand());
        });
      });
    } else if (this.kind === 'trainer') {
      // GB-era flow idiom: challenge line, then the lead's send-out.
      this.say('Trainer ' + this.trainer.name + ' wants to battle!', () => {
        this.say(this.trainer.name + ' sent out ' + foeName + '!', () => this.toCommand());
      });
    } else {
      this.say('Wild ' + foeName + ' appeared!');
    }
  }

  safariFleeCheck() {
    // Safari flee model (ADR-019 simplification, documented): base 10%,
    // rock +15%, bait -8%, skittish species (catch rate <= 45) +5%.
    const g = this.game;
    const rate = SPECIES[this.foe.speciesId].catchRate;
    let p = 0.10 + (this.safariRock ? 0.15 : 0) - (this.safariBait ? 0.08 : 0) + (rate <= 45 ? 0.05 : 0);
    if (roll(Math.max(0.02, p), g.rng.battle)) {
      this.say('Wild ' + displayName(this.foe, SPECIES) + ' fled!', () => this.endBattle(true));
      return true;
    }
    return false;
  }

  firstAble(g) {
    for (const m of g.state.party) if (m.hp > 0) return m;
    return g.state.party[0];
  }

  say(text, cb) {
    this.msg = text;
    this.msgCb = cb || null;
    this.msgOpen = true;
    this.game.ui.log.push({ ui: 'battle-msg', text });
  }

  update(dt) {
    const g = this.game;
    const input = g.input;
    const st = g.state.settings;
    // Screen shake / flash decay — P0/E11: gated on the Screen-shake option +
    // reduced motion (assignment is gated at the source; decay is unconditional).
    if (this.shakeT > 0) { this.shakeT -= dt * 1000; g.renderer.shakeX = (Math.random() - 0.5) * 8; g.renderer.shakeY = (Math.random() - 0.5) * 8; }
    else { g.renderer.shakeX = 0; g.renderer.shakeY = 0; }
    if (this.flashT > 0) { this.flashT -= dt * 1000; g.renderer.flashA = Math.max(0, this.flashT / 60) * 0.8; }
    // P0/E11: reduced-motion substitute — a gentle 100ms fade instead of shake/flash.
    if (this.fadeT > 0) {
      this.fadeT -= dt * 1000;
      g.renderer.fadeA = Math.max(0, this.fadeT / 100) * 0.35;
      g.renderer.fadeColor = '#ffffff';
      if (this.fadeT <= 0) g.renderer.fadeA = 0;
    }
    // README runtime transforms.
    if (this.atkFx) { this.atkFx.t += dt * 1000; if (this.atkFx.t > 100) this.atkFx = null; } // 3 frames @30Hz
    if (this.impactFx) { this.impactFx.t += dt * 1000; if (this.impactFx.t > 66) this.impactFx = null; } // 2 frames
    if (this.faintFx) { this.faintFx.t += dt * 1000; if (this.faintFx.t > 660) this.faintFx = null; } // 20 frames
    if (this.catchFx) { this.catchFx.t += dt * 1000; if (this.catchFx.t > 500) this.catchFx = null; } // P1/E10 starburst
    if (this.xpFlashT > 0) this.xpFlashT -= dt * 1000;
    if (this._lowHpPulseT > 0) this._lowHpPulseT -= dt * 1000;

    // Animated HP drain (90 HP/s) — P0/E5: reduced motion snaps instantly.
    this.drainHp(dt);

    if (g.ui.update(dt)) return;
    if (this.msgOpen) {
      if (input.wasPressed('a') || input.wasPressed('start')) {
        this.msgOpen = false;
        const cb = this.msgCb; this.msgCb = null;
        if (cb) cb();
        else this.afterMsg();
      }
      return;
    }
    switch (this.state) {
      case 'intro': break; // driven by msg cb
      case 'rt': this.updateRt(dt); break;
      case 'command': this.updateCommand(input); break;
      case 'resolve': this.updateResolve(dt); break;
      case 'catchseq': this.updateCatch(dt); break;
      case 'xp': this.updateXp(dt); break;
      case 'victory': case 'defeat': break;
    }
  }

  afterMsg() {
    const s = this.state;
    if (s === 'intro') this.toCommand();
    else if (s === 'resolve') this.nextAction();
    else if (s === 'victory') this.finishVictory();
    else if (s === 'defeat') this.finishDefeat();
    else if (s === 'faintfoe') this.afterFaintFoe();
  }

  toCommand() {
    this.state = 'command';
    if (this.rtMode) {
      // ADR-020: real-time flow replaces the command menu. First call enters
      // the arena; a NEW foe (trainer sent out the next mon) resets it;
      // anything else (party-menu return) just resumes.
      if (!this.rt) this.rtInit();
      else if (this.foe !== this._rtLastFoe) this.rtResetFoe();
      else this.state = 'rt';
      return;
    }
    if (this.safari) {
      const balls = this.game.state.bag.safariball || 0;
      const items = [
        { label: 'SAFARI BALL x' + balls, value: 'safariball', disabled: balls <= 0 },
        { label: 'BAIT', value: 'bait' },
        { label: 'ROCK', value: 'rock' },
        { label: 'RUN', value: 'safarirun' },
      ];
      this.game.ui.showCommands(items, (value) => this.onCommand(value), {});
      return;
    }
    // P0/C7: guided first-catch tutorial — FIGHT highlighted first (others dimmed),
    // then BAG highlighted once the foe is weakened. Dimmed = de-emphasized, still usable.
    const tut = this.tutorial;
    const items = [
      { label: 'FIGHT', value: 'fight', dimmed: tut && this._tutStage === 'bag' },
      { label: 'BAG', value: 'bag', dimmed: tut && this._tutStage !== 'bag' },
      { label: 'PARTY', value: 'party', dimmed: tut },
      // GD: no running from the scripted tutorial — it's a lesson, not a gamble.
      { label: this.kind === 'wild' ? 'RUN' : 'RUN', value: 'run', disabled: this.kind !== 'wild' || tut },
    ];
    let focus = null;
    if (tut && !this._tutFightDone) focus = 'fight';
    else if (tut && this._tutStage === 'bag') focus = 'bag';
    this.game.ui.showCommands(items, (value) => this.onCommand(value), { focus });
  }

  updateCommand() { /* menu modal drives via ui */ }

  onCommand(value) {
    const g = this.game;
    if (value === null) { this.toCommand(); return; } // cancelled -> back
    if (this.safari) {
      if (this.onSafariAction) this.onSafariAction();
      if (value === 'safarirun') { this.endBattle(true); return; }
      if (value === 'safariball') { this.beginCatch('safariball'); return; }
      if (value === 'bait' || value === 'rock') {
        if (value === 'bait') { this.safariBait = true; this.safariRock = false; }
        else { this.safariRock = true; this.safariBait = false; }
        const name = displayName(this.foe, SPECIES);
        this.say(value === 'bait' ? 'You threw bait! ' + name + ' is eating...' : 'You threw a rock! ' + name + ' is angry!', () => {
          if (this.safariFleeCheck()) return;
          this.toCommand();
        });
        return;
      }
    }
    if (value === 'fight') {
      // P0/E9: 2x2 move grid — name + type badge pill (icon+text) + PP + power/acc;
      // 0-PP rows grayed with a slash; cursor memory pre-selects the last-used move.
      const ally = this.ally;
      const items = ally.moves.map((m, i) => {
        const mv = MOVES[m.id];
        const disabledMove = ally.disableT > 0 && ally.disabledMove === i;
        return {
          label: mv.name + ' (' + mv.type + ') ' + m.pp + '/' + m.maxPp,
          value: i, disabled: m.pp <= 0 || disabledMove, zeroPp: m.pp <= 0, move: m,
        };
      });
      items.push({ label: 'Back', value: -1 });
      this.state = 'moves';
      const rowHtml = (it) => {
        if (it.value === -1) return '<span>' + it.label + '</span>';
        const mv = MOVES[it.move.id];
        return '<span class="mvcell"><span class="mvname">' + mv.name + '</span>'
          + typePill(mv.type)
          + '<span class="mvpp">' + it.move.pp + '/' + it.move.maxPp + ' PP</span>'
          + '<span class="mvpow">' + (mv.power || '—') + ' pw / ' + (mv.acc || '—') + ' ac</span></span>';
      };
      g.ui.showMenu('Choose a move', items, (v) => {
        if (v === null || v === -1) { this.toCommand(); return; }
        this._lastMoveIdx = v; // P0/E9 cursor memory
        this.playerAction = { type: 'move', idx: v };
        this.foeAction = this.chooseFoeAction();
        this.beginTurn();
      }, { battle: true, grid: true, initialIdx: Math.min(this._lastMoveIdx, items.length - 1), rowHtml });
    } else if (value === 'bag') {
      this.state = 'bag';
      const items = [];
      for (const bid of Object.keys(BALLS)) {
        const n = g.state.bag[bid] || 0;
        items.push({ label: BALLS[bid].name + ' x' + n, value: bid, disabled: n <= 0 || this.kind !== 'wild' });
      }
      const potions = g.state.bag.potion || 0;
      items.push({ label: 'Potion x' + potions, value: 'potion', disabled: potions <= 0 });
      items.push({ label: 'Back', value: null });
      // P0/C7: in the guided tutorial, the Poke Ball row is highlighted once the foe is weakened.
      const focusBall = this.tutorial && this._tutStage === 'bag';
      g.ui.showMenu('Bag', items, (v) => {
        if (v === null) { this.toCommand(); return; }
        if (v === 'potion') { this.usePotion(); return; }
        this.playerAction = { type: 'ball', ball: v };
        this.foeAction = null; // throwing a ball: foe still acts? DS: ball replaces your move; foe moves first if faster. Simplify: foe acts after throw fails only.
        this.beginCatch(v);
      }, { focusValue: focusBall ? 'pokeball' : null });
    } else if (value === 'party') {
      this.openPartyMenu(false);
    } else if (value === 'run') {
      if (this.kind === 'wild') {
        // Gen-1 escape formula (ADR-018): F = allySpe*128/foeSpe + 30*attempts;
        // escape iff F > 255 or a 0-255 roll lands under F. Failure costs the
        // turn — the foe acts.
        this.runAttempts++;
        const allySpe = Math.max(1, this.ally.stats.spe);
        const foeSpe = Math.max(1, this.foe.stats.spe);
        const F = Math.floor((allySpe * 128) / foeSpe) + 30 * this.runAttempts;
        if (F > 255 || Math.floor(g.rng.battle() * 256) < F) {
          g.audio.playSfx('battle-run');
          this.say('Got away safely!', () => this.endBattle(true));
        } else {
          this.say("Can't escape!", () => {
            this.playerAction = { type: 'ran' };
            this.foeAction = this.chooseFoeAction();
            this.state = 'resolve';
            const mkFoe = (action) => {
              const mon = this.foe;
              const stats = this.effStats(mon, this.foeStages);
              const move = action.type === 'move' ? MOVES[mon.moves[action.idx].id] : null;
              return { side: 'foe', action, mon, stats, priority: move ? (move.priority || 0) : 0, move };
            };
            this.actions = [mkFoe(this.foeAction)];
            this.nextAction();
          });
        }
      } else {
        this.say("Can't escape a trainer battle!", () => this.toCommand());
      }
    }
  }

  openPartyMenu(inFaint) {
    const g = this.game;
    const items = g.state.party.map((m, i) => {
      const sp = SPECIES[m.speciesId];
      const tag = m === this.ally ? ' (active)' : '';
      return { label: displayName(m, SPECIES) + ' Lv' + m.level + ' ' + m.hp + '/' + m.maxHp + tag, value: i, disabled: m.hp <= 0 || m === this.ally };
    });
    items.push({ label: 'Back', value: -1 });
    g.ui.showMenu(inFaint ? 'Choose next Pokemon' : 'Party', items, (v) => {
      if (v === null || v === -1) { if (!inFaint) this.toCommand(); return; }
      const old = this.ally;
      this.ally = g.state.party[v];
      this.allyStages = this.ally.stages;
      if (this.allyStages.acc === undefined) { this.allyStages.acc = 0; this.allyStages.eva = 0; }
      this.participants.add(this.ally); // switched-in mons share this foe's XP
      this.hpAnim.ally = this.ally.hp;
      if (inFaint) {
        this.say('Go! ' + displayName(this.ally, SPECIES) + '!', () => this.toCommand());
      } else if (this.rtMode) {
        // ADR-020: live switching — no turn is spent; the incoming mon is
        // briefly vulnerable (no dodge i-frames) as the switch cost.
        this.say('Come back! Go! ' + displayName(this.ally, SPECIES) + '!', () => {
          if (this.rt) { this.rt.switchVulnT = 1000; this.rt.iframes = 0; this.state = 'rt'; }
          else this.toCommand();
        });
      } else {
        this.say('Come back! Go! ' + displayName(this.ally, SPECIES) + '!', () => {
          this.playerAction = { type: 'switch', from: old };
          this.foeAction = this.chooseFoeAction();
          this.beginTurn();
        });
      }
    });
  }

  usePotion() {
    const g = this.game;
    const items = g.state.party.map((m, i) => ({
      label: displayName(m, SPECIES) + ' ' + m.hp + '/' + m.maxHp, value: i, disabled: m.hp <= 0 || m.hp >= m.maxHp,
    }));
    items.push({ label: 'Back', value: -1 });
    g.ui.showMenu('Use Potion on...', items, (v) => {
      if (v === null || v === -1) { this.toCommand(); return; }
      const m = g.state.party[v];
      g.state.bag.potion--;
      m.hp = Math.min(m.maxHp, m.hp + 20);
      this.hpAnim.ally = m.hp; // snap if active
      this.say(displayName(m, SPECIES) + ' recovered 20 HP!', () => {
        this.playerAction = { type: 'item' };
        this.foeAction = this.chooseFoeAction();
        this.beginTurn();
      });
    });
  }

  chooseFoeAction() {
    const g = this.game;
    const usable = this.foe.moves.map((m, i) => i).filter((i) => this.foe.moves[i].pp > 0
      && !(this.foe.disableT > 0 && this.foe.disabledMove === i));
    if (!usable.length) return { type: 'move', idx: 0, struggle: true };
    // GD balance: gym-leader opener — a leader with a self-buff setup move
    // opens with it (classic Brock Defense Curl): gives the player a free
    // turn, teaches setup play, and makes the fight about strategy.
    if (this.trainer && this.trainer.ai === 'opener-setup' && this.turn === 1) {
      const setup = usable.find((i) => {
        const mv = MOVES[this.foe.moves[i].id];
        return mv.cat === 'status' && mv.effect && mv.effect.target === 'self';
      });
      if (setup !== undefined) return { type: 'move', idx: setup };
    }
    // Gen-1 AI tempering (ADR-018): ordinary trainers pick near-randomly —
    // the original's AI rarely optimizes. Leaders (ai:'smart') and the
    // Elite Four prefer super-effective lines.
    const smart = this.trainer && (this.trainer.ai === 'smart' || this.trainer.ai === 'opener-setup');
    if (!smart) {
      return { type: 'move', idx: usable[Math.floor(g.rng.battle() * usable.length)] };
    }
    const allyTypes = SPECIES[this.ally.speciesId].types;
    let best = usable[0], bestScore = -1;
    for (const i of usable) {
      const mv = MOVES[this.foe.moves[i].id];
      if (mv.cat === 'status') continue;
      const e = effectiveness(mv.type, allyTypes);
      const score = e * (0.5 + g.rng.battle());
      if (score > bestScore) { bestScore = score; best = i; }
    }
    if (g.rng.battle() < 0.25) best = usable[Math.floor(g.rng.battle() * usable.length)];
    return { type: 'move', idx: best };
  }

  effStats(mon, stages) {
    const sp = SPECIES[mon.speciesId];
    return {
      atk: Math.floor(mon.stats.atk * stageMultiplier(stages.atk)),
      def: Math.floor(mon.stats.def * stageMultiplier(stages.def)),
      spa: Math.floor(mon.stats.spa * stageMultiplier(stages.spa)),
      spd: Math.floor(mon.stats.spd * stageMultiplier(stages.spd)),
      spe: Math.floor(mon.stats.spe * stageMultiplier(stages.spe)),
    };
  }

  beginTurn() {
    this.state = 'resolve';
    if (this.ally) this.ally.tookPhysicalThisTurn = 0;
    if (this.foe) this.foe.tookPhysicalThisTurn = 0;
    const pa = this.playerAction, fa = this.foeAction;
    const mk = (side, action) => {
      const mon = side === 'ally' ? this.ally : this.foe;
      const stages = side === 'ally' ? this.allyStages : this.foeStages;
      const stats = this.effStats(mon, stages);
      let priority = 0, move = null;
      if (action && action.type === 'move') {
        move = action.struggle ? { name: 'Struggle', type: 'normal', cat: 'physical', power: 50, acc: 100 } : MOVES[mon.moves[action.idx].id];
        priority = move.priority || 0;
      }
      return { side, action, mon, stats, priority, move };
    };
    const order = [];
    if (pa && pa.type !== 'switch' && pa.type !== 'item' && pa.type !== 'ball') order.push(mk('ally', pa));
    if (fa) order.push(mk('foe', fa));
    if (pa && (pa.type === 'switch' || pa.type === 'item' || pa.type === 'ball')) {
      // non-attack actions happen first, then foe acts
      this.actions = fa ? [mk('foe', fa)] : [];
      if (pa.type === 'switch' || pa.type === 'item') { /* already applied */ }
      this.state = 'resolve';
      this.nextAction();
      return;
    }
    // sort by priority -> Speed (paralysis quarters Speed) -> random tiebreak
    const cmp = (x, y) => {
      if (x.priority !== y.priority) return y.priority - x.priority;
      const sx = x.mon.status === 'paralysis' ? Math.floor(x.stats.spe / 4) : x.stats.spe;
      const sy = y.mon.status === 'paralysis' ? Math.floor(y.stats.spe / 4) : y.stats.spe;
      if (sx !== sy) return sy - sx;
      return this.game.rng.battle() < 0.5 ? -1 : 1;
    };
    this.actions = order.slice().sort(cmp);
    this.nextAction();
  }

  nextAction() {
    if (this.state !== 'resolve') return;
    const next = this.actions.shift();
    if (!next) { this.endTurnStatus(); return; }
    if (next.mon.hp <= 0) { this.nextAction(); return; } // fainted mid-turn
    this.execMove(next);
  }

  execMove(entry) {
    const g = this.game;
    const atk = entry.mon, mv = entry.move;
    const foeSide = entry.side === 'ally' ? 'foe' : 'ally';
    const def = foeSide === 'ally' ? this.ally : this.foe;
    const defStages = foeSide === 'ally' ? this.allyStages : this.foeStages;
    const atkName = displayName(atk, SPECIES);

    // Status gates — Generation-I semantics (ADR-018).
    if (atk.flinched) {
      atk.flinched = false;
      this.say(atkName + ' flinched and couldn\'t move!', () => this.nextAction());
      return;
    }
    if (atk.mustRecharge) {
      atk.mustRecharge = false;
      this.say(atkName + ' must recharge!', () => this.nextAction());
      return;
    }
    if (atk.status === 'paralysis' && roll(0.25, g.rng.battle)) {
      this.say(atkName + ' is paralyzed! It can\'t move!', () => this.nextAction());
      return;
    }
    if (atk.status === 'sleep') {
      // Gen 1: sleep lasts 1-7 turns, and the turn you wake up is lost.
      if (atk.sleepTurns === undefined || atk.sleepTurns === null) atk.sleepTurns = 1 + Math.floor(g.rng.battle() * 7);
      atk.sleepTurns--;
      if (atk.sleepTurns > 0) { this.say(atkName + ' is fast asleep.', () => this.nextAction()); return; }
      atk.status = null; atk.sleepTurns = null;
      this.say(atkName + ' woke up!', () => this.nextAction());
      return;
    }
    if (atk.status === 'freeze') {
      // Gen 1: no random thaw — only a Fire-type hit thaws (in damage code).
      this.say(atkName + ' is frozen solid!', () => this.nextAction());
      return;
    }
    if (atk.confused) {
      if (atk.confusedTurns === undefined || atk.confusedTurns === null) atk.confusedTurns = 2 + Math.floor(g.rng.battle() * 4);
      atk.confusedTurns--;
      if (atk.confusedTurns <= 0) {
        atk.confused = false; atk.confusedTurns = null;
        this.say(atkName + ' snapped out of confusion!', () => this.execMoveContinue(entry));
        return;
      }
      if (roll(0.5, g.rng.battle)) {
        // Gen 1: 50% self-hit at full typeless 40-power formula (no halving).
        const dmg = Math.max(1, calcDamage(atk.level, 40, entry.stats.atk, entry.stats.def, {}));
        atk.hp = Math.max(0, atk.hp - dmg);
        this.say(atkName + ' hurt itself in confusion!', () => this.checkFaint(entry.side, () => this.nextAction()));
        return;
      }
    }
    this.execMoveContinue(entry);
  }

  execMoveContinue(entry) {
    const g = this.game;
    const atk = entry.mon;
    let mv = entry.move;
    const foeSide = entry.side === 'ally' ? 'foe' : 'ally';
    const def = foeSide === 'ally' ? this.ally : this.foe;
    const defStages = foeSide === 'ally' ? this.allyStages : this.foeStages;
    const atkName = displayName(atk, SPECIES);
    const defName = displayName(def, SPECIES);

    // Lock-in moves (Wrap/Petal Dance family): the mon keeps using the move
    // until the lock expires; Petal Dance confuses the user afterwards.
    if (atk.lockMove && entry.action && entry.action.type === 'move') {
      entry.action.idx = atk.lockMove.idx;
      mv = MOVES[atk.moves[atk.lockMove.idx].id] || mv;
    }

    // Two-turn charge moves (Solar Beam / Dig / Fly family): first use
    // charges (no PP cost), the locked follow-up executes.
    if (mv.charge && !atk.chargedFor) {
      atk.chargedFor = mv.id;
      atk.lockMove = entry.action && entry.action.type === 'move' ? { idx: entry.action.idx, left: 1, after: null } : null;
      this.say(atkName + ' used ' + mv.name + '!', () => {
        this.say(atkName + ' is charging up!', () => this.nextAction());
      });
      return;
    }
    if (atk.chargedFor === mv.id) atk.chargedFor = null;

    // PP
    if (entry.action && !entry.action.struggle && entry.action.type === 'move') {
      const slot = atk.moves[entry.action.idx];
      if (slot) slot.pp = Math.max(0, slot.pp - 1);
      atk.lastMoveIdx = entry.action.idx;
    }

    // Bide: accumulate for 2 turns, then release double the damage taken.
    if (mv.effect && mv.effect.bide) {
      if (!atk.bideT) { atk.bideT = 2; atk.bideDmg = 0; this.say(atkName + ' used Bide!', () => this.nextAction()); return; }
      const bd = atk.bideDmg * 2; atk.bideT = 0; atk.bideDmg = 0;
      if (bd <= 0) { this.say(atkName + ' used Bide! But it failed!', () => this.nextAction()); return; }
      def.hp = Math.max(0, def.hp - bd);
      this.say(atkName + ' unleashed energy!', () => this.checkFaint(foeSide, () => this.nextAction()));
      return;
    }
    if (atk.bideT) atk.bideT--;

    // Metronome: become a random other move.
    if (mv.effect && mv.effect.metronome) {
      const pool = Object.keys(MOVES).filter((k) => !['metronome', 'mimic', 'transform', 'bide'].includes(k));
      const pick = pool[Math.floor(g.rng.battle() * pool.length)];
      entry.metronomeMove = MOVES[pick];
      this.say(atkName + ' used Metronome!', () => { entry.move = MOVES[pick]; this.execMoveContinue(entry); });
      return;
    }

    // Accuracy — Gen 1 (ADR-018): move acc x acc/eva stage multiplier;
    // even 100%-acc moves miss 1/256 of the time; neverMiss skips all rolls.
    // OHKO moves use their own Gen-1 rule: hit chance (userLv - targetLv
    // + 30) / 256 — they cannot touch a sufficiently higher-level target.
    const atkStages = entry.side === 'ally' ? this.allyStages : this.foeStages;
    if ((mv.effect && mv.effect.ohko) || mv.ohko) {
      const pOhko = Math.max(0, Math.min(255, atk.level - def.level + 30)) / 256;
      if (!roll(pOhko, g.rng.battle)) {
        this.say(atkName + ' used ' + mv.name + '!', () => {
          this.say('But it missed!', () => this.nextAction());
        });
        return;
      }
    } else if (!mv.neverMiss) {
      const stageDelta = (atkStages.acc || 0) - (defStages.eva || 0);
      let p = ((mv.acc || 100) / 100) * accStageMultiplier(Math.max(-6, Math.min(6, stageDelta)));
      if (p >= 1) p = 255 / 256;
      if (!roll(p, g.rng.battle)) {
        this.say(atkName + ' used ' + mv.name + '!', () => {
          this.say('But it missed!', () => this.nextAction());
        });
        return;
      }
    }

    this.say(atkName + ' used ' + mv.name + '!', () => {
      if (mv.cat === 'status') { this.applyStatusMove(entry, mv); return; }
      const efx = mv.effect || {};
      const atkTypes = atk.tempTypes || (atk.transformed ? atk.transformed.types : SPECIES[atk.speciesId].types);
      const defTypes = def.tempTypes || (def.transformed ? def.transformed.types : SPECIES[def.speciesId].types);
      const eff = effectiveness(mv.type, defTypes);
      const stab = atkTypes.includes(mv.type);
      if (eff === 0) {
        this.say('It doesn\'t affect ' + defName + '...', () => this.nextAction());
        return;
      }
      // Dream Eater only works on a sleeping target.
      if (efx.requiresSleep && def.status !== 'sleep') {
        this.say('But it failed! The target is not asleep!', () => this.nextAction());
        return;
      }
      // Counter: succeeds only if the user took physical damage this turn.
      if (efx.counter) {
        const taken = atk.tookPhysicalThisTurn || 0;
        if (taken <= 0) { this.say('But it failed!', () => this.nextAction()); return; }
        def.hp = Math.max(0, def.hp - taken * 2);
        this.say(defName + ' took ' + (taken * 2) + ' damage!', () => this.checkFaint(foeSide, () => this.nextAction()));
        return;
      }
      const baseSpe = (atk.transformed ? atk.transformed.baseSpe : SPECIES[atk.speciesId].base.spe);
      const crit = roll(critChance(baseSpe, { highCrit: !!mv.highcrit, focus: !!atk.focused }), g.rng.battle);
      // Gen 1 crits ignore ALL stat stages (raw stats both sides).
      const atkStat = mv.cat === 'physical'
        ? (crit ? atk.stats.atk : entry.stats.atk)
        : (crit ? atk.stats.spa : entry.stats.spa);
      const defStat = mv.cat === 'physical'
        ? (crit ? def.stats.def : Math.floor(def.stats.def * stageMultiplier(defStages.def)))
        : (crit ? def.stats.spd : Math.floor(def.stats.spd * stageMultiplier(defStages.spd)));
      const burn = atk.status === 'burn';
      if (entry.side === 'ally' && atk.speciesId === 'partner' && (crit || eff > 1)) {
        g.state.pikachu.mood = 'happy';
      }
      // Damage amount: fixed / level-scaled / OHKO / standard formula.
      let dmg;
      if (mv.ohko || efx.ohko) dmg = def.hp;
      else if (efx.fixed) dmg = efx.fixed;
      else if (efx.fixedLevel) dmg = atk.level;
      else if (efx.psywave) dmg = Math.max(1, Math.floor(atk.level * (0.5 + g.rng.battle())));
      else {
        const hits = efx.hits ? (efx.hits[0] + Math.floor(g.rng.battle() * (efx.hits[1] - efx.hits[0] + 1))) : 1;
        dmg = 0;
        for (let hi = 0; hi < hits; hi++) {
          dmg += calcDamage(atk.level, mv.power, atkStat, defStat,
            { stab, effectiveness: eff, crit, random: gen1Random(g.rng.battle), burn, physical: mv.cat === 'physical' });
        }
        if (hits > 1) this._hitCount = hits;
      }
      // Reflect / Light Screen halve the matching category while active.
      if (mv.cat === 'physical' && def.reflectT > 0) dmg = Math.max(1, Math.floor(dmg / 2));
      if (mv.cat === 'special' && def.lightT > 0) dmg = Math.max(1, Math.floor(dmg / 2));
      // Substitute absorbs the hit.
      let subBroke = false;
      if (def.subHp > 0) {
        def.subHp -= dmg;
        if (def.subHp <= 0) { def.subHp = 0; subBroke = true; }
        dmg = 0;
      }
      if (dmg > 0) {
        def.hp = Math.max(0, def.hp - dmg);
        if (mv.cat === 'physical') def.tookPhysicalThisTurn = (def.tookPhysicalThisTurn || 0) + dmg;
        if (def.bideT) def.bideDmg = (def.bideDmg || 0) + dmg;
        // Gen 1: a Fire-type hit thaws a frozen defender.
        if (def.status === 'freeze' && mv.type === 'fire') def.status = null;
      }
      // GD tutorial: the lesson mon endures at 1 HP — the gate teaches
      // catching, so the only exit is a (guaranteed, once weakened) catch.
      let hungOn = false;
      if (this.tutorial && foeSide === 'foe' && def.hp <= 0) {
        def.hp = 1;
        hungOn = !this._endureShown;
        this._endureShown = true;
      }
      if (hungOn) this._tutStage = 'bag'; // P0/C7: foe weakened -> BAG highlight next
      // P0/C7: the tutorial's first damaging move retires the FIGHT highlight.
      if (this.tutorial && entry.side === 'ally' && mv.cat !== 'status') this._tutFightDone = true;
      // README attack transform: the attacker's sprite scales 1.2x for 3 frames.
      // P1/E12: Battle animations OFF skips the lunge/impact anims entirely.
      const animsOn = g.state.settings.battleAnims !== false;
      if (animsOn) this.atkFx = { side: entry.side, t: 0 };
      // Impact theater — P0/E11: shake/flash gated on the Screen-shake option
      // and reduced motion; reduced motion gets a 100ms fade instead.
      const canShake = animsOn && !g.state.settings.reducedMotion && g.state.settings.shake;
      if (canShake) {
        if (eff > 1) { this.shakeT = 120; this.flashT = 60; }
        else if (eff < 1) { this.shakeT = 60; }
        if (crit) this.flashT = 90;
        // README impact: white palette-swap on the defender for 2 frames + shake.
        if (eff !== 1 || crit) this.impactFx = { side: foeSide, t: 0 };
        // P1/I5: haptic tick on super-effective (guarded; mobile only).
        if (eff > 1 && g.state.settings.vibration && typeof navigator !== 'undefined' && navigator.vibrate) {
          try { navigator.vibrate(30); } catch (e) { /* no haptics */ }
        }
      } else if (animsOn && g.state.settings.reducedMotion && (eff !== 1 || crit)) {
        this.fadeT = 100;
      }
      g.audio.hitFeedback(eff); // sound picks the effectiveness tier (visual twin: shake/flash)
      let extra = '';
      if (crit) extra = ' A critical hit!';
      if (eff > 1) extra += " It's super effective!";
      else if (eff < 1) extra += " It's not very effective...";
      const after = () => {
        // Secondary effects, then the damage line.
        let msg2 = hungOn
          ? defName + ' hung on with 1 HP! Now — open the BAG and throw a Poke Ball!'
          : (subBroke ? 'The substitute broke!' : defName + ' took ' + dmg + ' damage!');
        if (this._hitCount) { msg2 += ' Hit ' + this._hitCount + ' times!'; this._hitCount = 0; }
        if (mv.ohko || efx.ohko) msg2 = 'One-hit KO!';
        // Status infliction (single status or Tri Attack's random pick).
        let statusRoll = efx.status;
        if (efx.statusAny) statusRoll = efx.statusAny[Math.floor(g.rng.battle() * efx.statusAny.length)];
        if (statusRoll && def.hp > 0 && (!efx.chance || roll(efx.chance / 100, g.rng.battle))) {
          if (statusRoll === 'confusion') {
            if (!def.confused) { def.confused = true; def.confusedTurns = 2 + Math.floor(g.rng.battle() * 4); msg2 = defName + ' became confused!'; }
          } else if (!def.status) {
            def.status = statusRoll;
            if (statusRoll === 'sleep') def.sleepTurns = null;
            msg2 = defName + this.statusText(statusRoll);
          }
        }
        // Stage changes riding on a damaging move (Bubble Beam family).
        for (const k of ['atk', 'def', 'spa', 'spd', 'spe', 'acc', 'eva']) {
          if (efx[k] && def.hp > 0 && (!efx.stageChance || roll(efx.stageChance / 100, g.rng.battle))) {
            if (!(def.mistT > 0 && efx[k] < 0)) {
              defStages[k] = Math.max(-6, Math.min(6, (defStages[k] || 0) + efx[k]));
            }
          }
        }
        if (efx.flinch && def.hp > 0 && roll(efx.flinch / 100, g.rng.battle)) def.flinched = true;
        if (efx.seed && def.hp > 0) def.seeded = true;
        if (efx.drain && dmg > 0) {
          atk.hp = Math.min(atk.maxHp, atk.hp + Math.floor(dmg * efx.drain));
        }
        if (efx.payday) g.state.player.money += atk.level * 2;
        if (mv.recharge) atk.mustRecharge = true;
        // Lock bookkeeping for Wrap / thrash-family moves.
        if (efx.multi || efx.multiTurn) {
          if (!atk.lockMove && entry.action && entry.action.type === 'move') {
            atk.lockMove = { idx: entry.action.idx, left: 1 + Math.floor(g.rng.battle() * 2), after: efx.multiTurn ? 'confuse' : null };
          }
        }
        if (atk.lockMove && entry.action && entry.action.type === 'move' && entry.action.idx === atk.lockMove.idx) {
          atk.lockMove.left--;
          if (atk.lockMove.left <= 0) {
            const afterLock = atk.lockMove.after;
            atk.lockMove = null;
            if (afterLock === 'confuse' && atk.hp > 0) { atk.confused = true; atk.confusedTurns = 2 + Math.floor(g.rng.battle() * 4); }
          }
        }
        const finishMove = () => {
          if (efx.selfFaint && atk.hp > 0) {
            atk.hp = 0;
            this.checkFaint(entry.side, () => this.nextAction());
            return;
          }
          if (efx.recoil && dmg > 0 && atk.hp > 0) {
            atk.hp = Math.max(0, atk.hp - Math.max(1, Math.floor(dmg * efx.recoil)));
            this.checkFaint(entry.side, () => this.nextAction());
            return;
          }
          this.nextAction();
        };
        this.say(msg2, () => {
          this.checkFaint(foeSide, finishMove);
        });
      };
      if (extra.trim()) this.say(extra.trim(), after);
      else after();
    });
  }

  statusText(s) {
    return { burn: ' was burned!', poison: ' was poisoned!', paralysis: ' was paralyzed!', sleep: ' fell asleep!', freeze: ' was frozen solid!', confusion: ' became confused!' }[s] || ' was afflicted!';
  }

  applyStatusMove(entry, mv) {
    const g = this.game;
    const ef = mv.effect || {};
    const atk = entry.mon;
    const selfSide = entry.side;
    const foeSide = selfSide === 'ally' ? 'foe' : 'ally';
    const foeMon = foeSide === 'ally' ? this.ally : this.foe;
    const target = ef.target === 'self' ? atk : foeMon;
    const stages = ef.target === 'self' ? (selfSide === 'ally' ? this.allyStages : this.foeStages) : (foeSide === 'ally' ? this.allyStages : this.foeStages);
    const tName = displayName(target, SPECIES);
    const aName = displayName(atk, SPECIES);
    const done = (msg) => this.say(msg, () => this.nextAction());
    // Teleport: flee a wild battle; fails against trainers.
    if (ef.flee) {
      if (this.kind === 'wild') { this.say(aName + ' teleported away!', () => this.endBattle(true)); return; }
      done('But it failed!'); return;
    }
    if (ef.haze) {
      for (const s of [this.allyStages, this.foeStages]) for (const k of Object.keys(s)) s[k] = 0;
      if (foeMon.status) foeMon.status = null;
      foeMon.confused = false;
      done('All stat changes were eliminated!');
      return;
    }
    if (ef.heal) {
      if (target.hp >= target.maxHp) { done('But it failed!'); return; }
      target.hp = Math.min(target.maxHp, target.hp + Math.floor(target.maxHp * ef.heal));
      done(tName + ' regained health!');
      return;
    }
    if (ef.rest) {
      target.hp = target.maxHp;
      target.status = 'sleep';
      target.sleepTurns = 3; // Gen 1 Rest: exactly 2 full turns asleep
      done(tName + ' slept and became healthy!');
      return;
    }
    if (ef.substitute) {
      const cost = Math.floor(target.maxHp / 4);
      if (target.subHp > 0 || target.hp <= cost) { done('But it failed!'); return; }
      target.hp -= cost;
      target.subHp = cost;
      done(tName + ' made a substitute!');
      return;
    }
    if (ef.screen) {
      if (ef.screen === 'physical') atk.reflectT = 5; else atk.lightT = 5;
      done(ef.screen === 'physical' ? 'A wall of light weakened physical attacks!' : 'A wall of light weakened special attacks!');
      return;
    }
    if (ef.mist) { atk.mistT = 5; done(aName + ' is shrouded in mist!'); return; }
    if (ef.focus) { atk.focused = true; done(aName + ' is getting pumped!'); return; }
    if (ef.seed) {
      if (foeMon.seeded) { done('But it failed!'); return; }
      foeMon.seeded = true;
      done('Seeds were planted on ' + tName + '!');
      return;
    }
    if (ef.disable) {
      if (foeMon.lastMoveIdx === undefined || foeMon.lastMoveIdx === null || foeMon.disableT > 0) { done('But it failed!'); return; }
      foeMon.disabledMove = foeMon.lastMoveIdx;
      foeMon.disableT = 1 + Math.floor(g.rng.battle() * 7);
      done(tName + "'s " + MOVES[foeMon.moves[foeMon.disabledMove].id].name + ' was disabled!');
      return;
    }
    if (ef.transform) {
      atk._preTransform = { speciesId: atk.speciesId, stats: { ...atk.stats }, moves: atk.moves };
      atk.transformed = { types: [...(foeMon.tempTypes || SPECIES[foeMon.speciesId].types)], baseSpe: SPECIES[foeMon.speciesId].base.spe };
      atk.speciesId = foeMon.speciesId;
      atk.stats = { ...foeMon.stats };
      atk.moves = foeMon.moves.map((m) => ({ id: m.id, pp: 5, maxPp: 5 }));
      done(aName + ' transformed into ' + tName + '!');
      return;
    }
    if (ef.conversion) {
      const first = atk.moves[0] && MOVES[atk.moves[0].id];
      atk.tempTypes = [first ? first.type : 'normal'];
      done(aName + ' became ' + atk.tempTypes[0] + ' type!');
      return;
    }
    if (ef.mimic) {
      const foeMoves = foeMon.moves.filter((m) => MOVES[m.id]);
      if (!foeMoves.length || !entry.action) { done('But it failed!'); return; }
      const pick = foeMoves[Math.floor(g.rng.battle() * foeMoves.length)];
      atk._mimicRestore = atk.moves[entry.action.idx];
      atk.moves[entry.action.idx] = { id: pick.id, pp: MOVES[pick.id].pp, maxPp: MOVES[pick.id].pp };
      done(aName + ' learned ' + MOVES[pick.id].name + '!');
      return;
    }
    let msg = '';
    for (const k of ['atk', 'def', 'spa', 'spd', 'spe', 'acc', 'eva']) {
      if (ef[k]) {
        if (target.mistT > 0 && ef[k] < 0 && target !== atk) { msg = tName + ' is protected by mist!'; continue; }
        stages[k] = Math.max(-6, Math.min(6, (stages[k] || 0) + ef[k]));
        msg = tName + "'s " + k.toUpperCase() + (ef[k] > 0 ? ' rose!' : ' fell!');
      }
    }
    if (ef.status === 'confusion') {
      if (!target.confused) { target.confused = true; target.confusedTurns = 2 + Math.floor(g.rng.battle() * 4); msg = tName + ' became confused!'; }
      else msg = 'But it failed!';
    } else if (ef.status) {
      if (!target.status) {
        target.status = ef.status;
        if (ef.status === 'sleep') target.sleepTurns = null;
        msg = tName + this.statusText(ef.status);
      } else msg = 'But it failed!';
    }
    this.say(msg || 'Nothing happened.', () => this.nextAction());
  }

  checkFaint(side, cb) {
    const g = this.game;
    const mon = side === 'ally' ? this.ally : this.foe;
    if (mon.hp > 0) { cb(); return; }
    // Yellow homage: the partner takes its own faint personally.
    if (side === 'ally' && mon.speciesId === 'partner') g.state.pikachu.mood = 'sad';
    const name = displayName(mon, SPECIES);
    g.audio.playSfx('battle-faint');
    // README faint transform: the sprite sinks 8px + fades to 0 over 20 frames
    // while the message plays (visual-only; the flow is unchanged).
    const art = g.spriteCache[mon.speciesId] || g.spriteCache.partner;
    this.faintFx = { side, spr: side === 'ally' ? art.back : art.front, t: 0 };
    this.say(name + ' fainted!', () => {
      if (side === 'foe') {
        this.state = 'faintfoe';
        this.afterFaintFoe();
      } else {
        const g = this.game;
        const anyLeft = g.state.party.some((m) => m.hp > 0);
        if (!anyLeft) {
          this.state = 'defeat';
          this.say('You have no Pokemon left!', () => this.afterMsg());
        } else {
          this.openPartyMenu(true);
        }
      }
    });
  }

  afterFaintFoe() {
    const g = this.game;
    if (this.kind === 'trainer') {
      this.trainerIdx++;
      if (this.trainerIdx < this.trainer.team.length) {
        const t = this.trainer.team[this.trainerIdx];
        this.foe = makeMon(t.species, t.level, SPECIES, MOVES);
        if (t.nickname) this.foe.nickname = t.nickname;
        this.foeStages = { atk: 0, def: 0, spa: 0, spd: 0, spe: 0, acc: 0, eva: 0 };
        this.participants = new Set([this.ally]); // XP pool resets per foe
        this.hpAnim.foe = this.foe.hp;
        const foeName = displayName(this.foe, SPECIES);
        this.say(this.trainer.name + ' sent out ' + foeName + '!', () => {
          g.audio.playCry(t.species);
          this.state = 'resolve';
          this.awardXp(() => this.toCommand());
        });
        return;
      }
      this.awardXp(() => this.winTrainer());
    } else {
      this.awardXp(() => {
        this.state = 'victory';
        g.audio.playSfx('victory'); // wild-win sting (visual twin: the "defeated" message)
        this.say('Wild ' + displayName(this.foe, SPECIES) + ' was defeated!', () => this.afterMsg());
      });
    }
  }

  awardXp(cb) {
    const g = this.game;
    const base = SPECIES[this.foe.speciesId].baseXp;
    const total = xpYield(base, this.foe.level, this.kind === 'wild');
    // Fidelity pack (ADR-018): XP splits among the participants who faced
    // THIS foe and are still standing — never the whole party for free.
    const parts = [...this.participants].filter((m) => m.hp > 0);
    const share = parts.length ? Math.max(1, Math.floor(total / parts.length)) : 0;
    this.xpShares = new Map(parts.map((m) => [m, share]));
    this.xpBarAnim = parts.map((m) => ({
      mon: m, from: xpFracOf(m, 0), to: xpFracOf(m, share),
    }));
    this.xpCb = cb;
    this.state = 'xp';
    this.xpT = 0;
  }

  // Fraction of the current level's XP progress (for the XP bar).
  xpShownFrac(mon) {
    let frac = xpFracOf(mon, 0);
    if (this.state === 'xp' && this.xpBarAnim) {
      const rec = this.xpBarAnim.find((r) => r.mon === mon);
      if (rec) {
        const k = this.game.state.settings.reducedMotion
          ? 1
          : 1 - Math.pow(1 - Math.min(1, this.xpT / 600), 3); // ease-out cubic
        frac = rec.from + (rec.to - rec.from) * k;
      }
    }
    return frac;
  }

  updateXp(dt) {
    const g = this.game;
    // XP bar ease-out over 600ms (gameux §4.2), then level-ups
    this.xpT += dt * 1000;
    if (this.xpT < 600) return;
    if (!this.xpApplied) {
      this.xpApplied = true;
      const msgs = [];
      for (const [m, share] of (this.xpShares || new Map())) {
        if (m.hp <= 0 || share <= 0) continue;
        m.xp += share;
        let leveled = false;
        while (m.xp >= xpForLevel(SPECIES[m.speciesId].growth, m.level + 1) && m.level < 100) {
          m.level++;
          leveled = true;
          const sp = SPECIES[m.speciesId];
          const oldMax = m.maxHp;
          m.maxHp = hpValue(sp.base.hp, m.level, m.ivs ? m.ivs.hp : undefined);
          // WS7/WS9: level-up evolutions queue for the post-battle ceremony.
          if (sp.evo && sp.evo.method === 'level' && m.level >= sp.evo.level) {
            const q = g.state.session.evolveQueue || (g.state.session.evolveQueue = []);
            if (!q.some((e) => e.monId === m.monId)) q.push({ monId: m.monId });
          }
          m.hp = Math.min(m.maxHp, m.hp + (m.maxHp - oldMax));
          m.stats = {
            atk: statValue(sp.base.atk, m.level, m.ivs ? m.ivs.atk : undefined), def: statValue(sp.base.def, m.level, m.ivs ? m.ivs.def : undefined),
            spa: statValue(sp.base.spa, m.level, m.ivs ? m.ivs.spa : undefined), spd: statValue(sp.base.spd, m.level, m.ivs ? m.ivs.spd : undefined),
            spe: statValue(sp.base.spe, m.level, m.ivs ? m.ivs.spe : undefined),
          };
          // Learn new moves: free slot learns instantly; a full set queues a
          // proper learn/forget prompt after the battle (WS9 — no silent
          // overwrite, HM moves are protected there).
          const newMoves = Array.isArray(sp.learnset)
            ? sp.learnset.filter((e) => e.level === m.level).map((e) => e.move)
            : (sp.learnset[m.level] || []);
          for (const mid of newMoves) {
            if (m.moves.some((x) => x.id === mid)) continue;
            if (m.moves.length < 4) m.moves.push({ id: mid, pp: MOVES[mid].pp, maxPp: MOVES[mid].pp });
            else (g.state.session.learnQueue = g.state.session.learnQueue || []).push({ monId: m.monId, moveId: mid });
          }
        }
        if (leveled) msgs.push(displayName(m, SPECIES) + ' grew to Lv ' + m.level + '!');
      }
      this.xpShares = null;
      g.audio.playSfx('dex-register');
      this.xpApplied = false;
      this.xpFlashT = 250; // P0/E3: level-up flash on the XP bar + fanfare below
      const cb = this.xpCb; this.xpCb = null;
      if (msgs.length) { g.audio.playSfx('levelup'); this.say(msgs.join(' '), () => { this.state = 'resolve'; if (cb) cb(); }); }
      else { this.state = 'resolve'; if (cb) cb(); }
    }
  }

  endTurnStatus() {
    // Burn/poison tick (1/16 max HP), badly-poisoned escalates (1/16 x turns),
    // Leech Seed drains 1/16 to the other side; then timers tick down.
    const tick = (mon, stages, side, done) => {
      if (mon.hp <= 0) { done(); return; }
      const other = side === 'ally' ? this.foe : this.ally;
      if (mon.status === 'burn' || mon.status === 'poison' || mon.status === 'badlyPoisoned') {
        let mult = 1;
        if (mon.status === 'badlyPoisoned') { mon.bpTurns = (mon.bpTurns || 0) + 1; mult = mon.bpTurns; }
        const dmg = Math.max(1, Math.floor(mon.maxHp / 16) * mult);
        mon.hp = Math.max(0, mon.hp - dmg);
        this.say(displayName(mon, SPECIES) + ' is hurt by ' + mon.status + '!', () => {
          this.checkFaint(side, done);
        });
        return;
      }
      if (mon.seeded && other && other.hp > 0) {
        const dmg = Math.max(1, Math.floor(mon.maxHp / 16));
        mon.hp = Math.max(0, mon.hp - dmg);
        other.hp = Math.min(other.maxHp, other.hp + dmg);
        this.say(displayName(mon, SPECIES) + "'s health was sapped by Leech Seed!", () => {
          this.checkFaint(side, done);
        });
        return;
      }
      done();
    };
    for (const m of [this.ally, this.foe]) {
      if (!m) continue;
      if (m.reflectT > 0) m.reflectT--;
      if (m.lightT > 0) m.lightT--;
      if (m.mistT > 0) m.mistT--;
      if (m.disableT > 0) { m.disableT--; if (m.disableT <= 0) m.disabledMove = null; }
    }
    tick(this.ally, this.allyStages, 'ally', () => {
      if (this.state === 'defeat' || !this.ally || this.ally.hp <= 0) { this.nextAfterStatus(); return; }
      tick(this.foe, this.foeStages, 'foe', () => this.nextAfterStatus());
    });
  }

  nextAfterStatus() {
    if (this.state === 'defeat') { this.afterMsg(); return; }
    if (this.state === 'faintfoe') { this.afterFaintFoe(); return; }
    this.turn++;
    this.toCommand();
  }

  // ---- Catch sequence: the theater (gameux §4.2) ----
  beginCatch(ballId) {
    const g = this.game;
    if (this.uncatchable) {
      // Scripted presence: balls are deflected — the story must resolve it.
      g.state.bag[ballId]--;
      this.say('The ball passed right through it! This presence cannot be caught.', () => {
        this.foeAction = this.chooseFoeAction();
        this.state = 'resolve';
        const mon = this.foe;
        const stats = this.effStats(mon, this.foeStages);
        const move = MOVES[mon.moves[this.foeAction.idx].id];
        this.actions = [{ side: 'foe', action: this.foeAction, mon, stats, priority: move.priority || 0, move }];
        this.nextAction();
      });
      return;
    }
    g.state.bag[ballId]--;
    const ball = BALLS[ballId];
    this.state = 'catchseq';
    this.catchState = { ball, phase: 'throw', t: 0, shakes: 0, need: 0, a: 0 };
    g.audio.playSfx('catch-throw');
    this.msg = 'You threw a ' + ball.name + '!'; // throw plays immediately, no modal
    this.msgOpen = false;
    const foe = this.foe;
    // Gen-1 two-roll catch (ADR-018): no critical captures, no approximations.
    // Safari throws adjust the effective rate: rock doubles it, bait halves it.
    let rate = SPECIES[foe.speciesId].catchRate;
    if (this.safari) rate = Math.max(3, Math.min(255, Math.round(rate * (this.safariRock ? 2 : this.safariBait ? 0.5 : 1))));
    const res = gen1Catch(foe.maxHp, foe.hp, rate, ballId, foe.status, g.rng.battle);
    this.catchState.willCatch = res.caught;
    this.catchState.need = res.caught ? 3 : res.shakes;
    if (this.tutorial && foe.hp <= foe.maxHp * 0.5) {
      // GD tutorial: weakened in the lesson battle = guaranteed catch.
      // The teaching is in the weaken step; the outcome is never luck.
      this.catchState.willCatch = true;
      this.catchState.need = 3;
    }
  }

  updateCatch(dt) {
    const g = this.game;
    const c = this.catchState;
    c.t += dt * 1000;
    // throw 26f (~430ms) -> absorb -> ball drop -> 3x800ms shakes -> click
    if (c.phase === 'throw' && c.t >= 430) {
      c.phase = 'shakes'; c.t = 0;
      // P1/E10: absorb flash (the mon is drawn into the ball) — white-swap 2 frames.
      const foeArt = g.spriteCache[this.foe.speciesId] || g.spriteCache.partner;
      if (foeArt.frontWhite && !g.state.settings.reducedMotion) this.impactFx = { side: 'foe', t: 0 };
    }
    else if (c.phase === 'shakes') {
      const want = c.need;
      const doneShakes = Math.floor(c.t / 800);
      if (c.shakes < doneShakes && c.shakes < want) {
        c.shakes++;
        g.audio.playSfx('catch-rattle'); // visual twin: ball wiggle
      }
      if (c.shakes >= want && c.t >= want * 800 + 200) {
        if (c.willCatch) this.catchSuccess();
        else this.catchBreak(c.shakes);
      }
    }
  }

  catchSuccess() {
    const g = this.game;
    g.audio.playSfx('catch-click'); // visual twin: starburst
    g.audio.playSfx('catch-gotcha');
    this.catchFx = { t: 0 }; // P1/E10: success starburst radiates from the ball
    const foe = this.foe;
    const name = displayName(foe, SPECIES);
    dexRegister(g.state.dex, 'caught', SPECIES[foe.speciesId].dexNo);
    let dest = 'party';
    if (g.state.party.length >= 6) {
      // Full party: the catch goes to the current PC box as a complete mon.
      const boxId = g.state.currentBox || 'box1';
      const box = g.state.boxes[boxId] || (g.state.boxes[boxId] = []);
      foe.hp = foe.maxHp;
      foe.status = null; foe.confused = false;
      box.push(foe);
      dest = 'the PC (' + boxId.replace('box', 'Box ') + ')';
    } else {
      foe.hp = foe.maxHp; // caught fresh
      g.state.party.push(foe);
    }
    g.audio.playSfx('dex-register'); // visual twin: dex toast + badge dot
    g.ui.dexDot = true; // P1/D4: badge dot on the HUD strip's Dex button
    if (g.ui._renderDexDot) g.ui._renderDexDot();
    this.say('Gotcha! ' + name + ' was caught! (' + dest + ')', () => {
      g.ui.toast(name + ' registered in the Dex!');
      this.endBattle(true);
    });
  }

  catchBreak(shakesDone) {
    const g = this.game;
    const name = displayName(this.foe, SPECIES);
    if (this.safari) {
      g.audio.catchBreakout();
      this.say('Oh no! ' + name + ' broke free!', () => {
        if (this.safariFleeCheck()) return;
        this.toCommand();
      });
      return;
    }
    g.audio.catchBreakout(); // visual twin: break-out burst
    // P0/E11: break-out flash gated like battle flashes; reduced motion -> fade.
    if (!g.state.settings.reducedMotion && g.state.settings.shake) g.renderer.flashA = 0.8;
    else if (g.state.settings.reducedMotion) { g.renderer.fadeA = 0.35; g.renderer.fadeColor = '#ffffff'; }
    this.say('Oh no! ' + name + ' broke free after ' + shakesDone + ' shake' + (shakesDone === 1 ? '' : 's') + '!', () => {
      g.renderer.flashA = 0;
      g.renderer.fadeA = 0;
      // Break-out mood: it may attack immediately (foe gets a free move)
      this.playerAction = { type: 'ballthrown' };
      this.foeAction = this.chooseFoeAction();
      this.state = 'resolve';
      const mk = (side, action) => {
        const mon = side === 'ally' ? this.ally : this.foe;
        const stages = side === 'ally' ? this.allyStages : this.foeStages;
        const stats = this.effStats(mon, stages);
        let move = null, priority = 0;
        if (action.type === 'move') {
          move = MOVES[mon.moves[action.idx].id];
          priority = move.priority || 0;
        }
        return { side, action, mon, stats, priority, move };
      };
      this.actions = [mk('foe', this.foeAction)];
      this.nextAction();
    });
  }

  winTrainer() {
    const g = this.game;
    const t = this.trainer;
    this.state = 'victory';
    g.state.player.money += t.reward;
    g.state.story.flags['beat_' + t.id] = true;
    // Yellow homage: winning with the partner conscious leaves it buzzing.
    if (g.state.party.some((m) => m.speciesId === 'partner' && m.hp > 0)) {
      g.state.pikachu.mood = 'excited';
    }
    // No battle-message here: the capstone dialogue below ends the battle exactly once.
    this.msg = 'You defeated ' + t.title + ' ' + t.name + '! Got $' + t.reward + '.';
    this.msgOpen = false;
    if (t.badge) {
      if (!g.state.badges.kanto.includes(t.badge)) g.state.badges.kanto.push(t.badge);
      g.state.story.flags['badge_' + t.badge.replace(/badge$/, '')] = true; // quest chain (WS6)
      g.audio.playSfx('badge'); // badge fanfare (visual twin: badge-case shine animation)
      if (t.id === 'brock') {
        // The slice capstone lines are Brock's scene specifically.
        const lines = SLICE_CAPSTONE.map((l) => l.replace('{player}', g.state.player.name));
        g.ui.say(lines, () => this.endBattle(true), '');
      } else {
        g.ui.say(t.lose, () => this.endBattle(true), t.name);
      }
    } else {
      g.ui.say(t.lose, () => this.endBattle(true), t.name);
    }
  }

  finishVictory() {
    this.endBattle(true);
  }

  finishDefeat() {
    const g = this.game;
    // Defeat: fade -> Pokemon Center (overworld, healed, money halved) — architecture §2.2
    g.state.pikachu.mood = 'sad'; // Yellow homage: the partner hates losing
    g.state.player.money = Math.floor(g.state.player.money / 2);
    this.endBattle(false);
    g.ui.say(['You hurried to the Pokemon Center...'], () => {
      const ow = this.returnTo;
      ow.loadMap('center');
      ow.player.tx = 4; ow.player.ty = 3; ow.player.px = 4 * TILE; ow.player.py = 3 * TILE;
      ow.player.fx = 4; ow.player.fy = 3;
      ow.trail = [];
      ow.healParty(false);
      g.state.story.position = { map: 'center', x: 4, y: 3, dir: 'down' };
      g.ui.toast('Your Pokemon were healed. (Lost half your money.)');
    });
  }

  endBattle(won) {
    const g = this.game;
    g.ui.setBattleMode(false);
    if (g.ui.hideCommands) g.ui.hideCommands(); // RT touch move pad retires with the battle
    g.audio.restoreAreaMusic(); // back to the overworld's track
    g.renderer.shakeX = 0; g.renderer.shakeY = 0; g.renderer.flashA = 0;
    // Reset battle temp state on party mons (incl. Transform restoration).
    for (const m of g.state.party) {
      if (m._preTransform) {
        m.speciesId = m._preTransform.speciesId;
        m.stats = m._preTransform.stats;
        m.moves = m._preTransform.moves;
        m._preTransform = null; m.transformed = null;
      }
      if (m._mimicRestore) m._mimicRestore = null;
      m.confused = false; m.confusedTurns = null; m.statusTurns = 0; m.sleepTurns = null;
      m.seeded = false; m.subHp = 0; m.reflectT = 0; m.lightT = 0; m.mistT = 0;
      m.lockMove = null; m.chargedFor = null; m.focused = false; m.tempTypes = null;
      m.flinched = false; m.bpTurns = 0; m.mustRecharge = false; m.bideT = 0; m.bideDmg = 0;
      m.disabledMove = null; m.disableT = 0; m.tookPhysicalThisTurn = 0;
      const st = m.stages; if (st) { st.atk = 0; st.def = 0; st.spa = 0; st.spd = 0; st.spe = 0; st.acc = 0; st.eva = 0; }
    }
    g.scenes.pop();
    g.autosave('battle');
    // Story-event continuation (WS6): scripted battles resume their script
    // only on victory — a loss leaves the event unconsumed for a retry.
    if (this.onEnd) { const f = this.onEnd; this.onEnd = null; f(won); }
  }

  drainHp(dt) {
    const g = this.game;
    // P0/E5: reduced motion -> HP drain snaps instantly (no 90 HP/s animation).
    if (g.state.settings.reducedMotion) {
      this.hpAnim.ally = this.ally.hp;
      this.hpAnim.foe = this.foe.hp;
    } else {
      const rate = HP_DRAIN_PER_SEC * dt;
      if (this.hpAnim.ally !== this.ally.hp) {
        const d = this.ally.hp - this.hpAnim.ally;
        this.hpAnim.ally += Math.sign(d) * Math.min(Math.abs(d), rate);
        if (Math.abs(this.ally.hp - this.hpAnim.ally) < 1) this.hpAnim.ally = this.ally.hp;
      }
      if (this.hpAnim.foe !== this.foe.hp) {
        const d = this.foe.hp - this.hpAnim.foe;
        this.hpAnim.foe += Math.sign(d) * Math.min(Math.abs(d), rate);
        if (Math.abs(this.foe.hp - this.hpAnim.foe) < 1) this.hpAnim.foe = this.foe.hp;
      }
    }
    // Low-HP warning jingle at first crossing into red (<25%), once per ally
    // (gameux §4.2). Visual twin: the HP plate's red pulse + '!' pip.
    if (this._lowHpAlly !== this.ally) { this._lowHpAlly = this.ally; this._lowHpWarned = false; }
    const ratio = this.ally.maxHp > 0 ? this.ally.hp / this.ally.maxHp : 1;
    if (ratio > 0.25) this._lowHpWarned = false;
    else if (!this._lowHpWarned && this.ally.hp > 0) {
      this._lowHpWarned = true;
      g.audio.playSfx('lowhp'); // P0-5: wired (was dead code before the Wave-2 audio merge)
      // P1/E7: pulse the ally plate twice on first red crossing (not under reduced motion).
      if (!g.state.settings.reducedMotion) this._lowHpPulseT = 400;
    }
  }

  // UI v2 (Platinum standard): stepped circular battle platform, rects only
  // (5 horizontal bands, widest at the middle — a pixel disc, no arc/ellipse
  // calls): light rim on top, pale fill, darker shade band at the bottom.
  ptDisc(r, cx, cy, rx, ry) {
    const c = r.ctx;
    const steps = 5;
    for (let i = 0; i < steps; i++) {
      const t = (i / (steps - 1)) * 2 - 1; // -1 (top) .. 1 (bottom)
      const half = Math.max(4, Math.round(rx * Math.sqrt(Math.max(0.12, 1 - t * t))));
      const y0 = Math.round(cy + t * ry - ry / steps);
      const hh = Math.ceil((2 * ry) / steps) + 1;
      c.fillStyle = i === 0 ? '#f2ecd8' : (i === steps - 1 ? '#b3a586' : '#ddd2ac');
      c.fillRect(Math.round(cx - half), y0, half * 2, hh);
    }
  }

  // UI v2 (Platinum standard): the battlefield, rects only, drawn INSIDE
  // begin()/end() (the old pre-begin bands were painted over by begin()'s
  // black clear — that was the dark void). Stepped daylight-blue sky ramp
  // (per-band solid fills; no gradient APIs, no offscreen cache needed at
  // 6 bands), a stepped tree/hill scenery band on the horizon, then the
  // ground field in stepped bands — grass greens for wild encounters,
  // warm stone for trainer battles (this.kind is the terrain data at hand).
  drawArena(r, horizonFrac) {
    const g = this.game;
    const w = r.viewW, h = r.viewH;
    const horizon = Math.round(h * horizonFrac);
    const sky = ['#5f9fe6', '#6fabec', '#7fb7f1', '#8fc3f5', '#9fcdf8', '#b0d7fa'];
    const sb = Math.ceil(horizon / sky.length) || 1;
    for (let i = 0; i < sky.length; i++) g.ctx2dfill(sky[i], 0, i * sb, w, sb + 1);
    // Scenery: hill band + deterministic stepped tree bumps on the horizon.
    g.ctx2dfill('#5d8f66', 0, horizon - 8, w, 8);
    for (let x = 4, i = 0; x < w - 8; x += 18, i++) {
      const bh = 8 + ((i * 5) % 3) * 3;
      g.ctx2dfill('#3f6d4a', x, horizon - bh, 10, bh);
    }
    g.ctx2dfill('#4c7a56', 0, horizon - 3, w, 3);
    // Ground field: stepped bands lightening toward the horizon.
    const ground = this.kind === 'trainer'
      ? ['#cfc2a4', '#c4b696', '#b9aa89', '#ae9e7d', '#a39271', '#988665']
      : ['#a5dc82', '#9bd578', '#91ce6f', '#87c766', '#7dc05d', '#73b954'];
    const gb = Math.ceil((h - horizon) / ground.length) || 1;
    for (let i = 0; i < ground.length; i++) g.ctx2dfill(ground[i], 0, horizon + i * gb, w, gb + 1);
    g.ctx2dfill('#33513c', 0, horizon, w, 2); // horizon line
  }

  render(r) {
    const g = this.game;
    if (this.rtMode && this.rt && (this.state === 'rt' || this.state === 'xp')) { this.renderRt(r); return; }
    const w = r.viewW, h = r.viewH;
    // Transform discipline (title/intro pattern): pin the camera to the
    // origin for the screen-space theater, restore it after end().
    const pcx = r.camX, pcy = r.camY; r.camX = 0; r.camY = 0;
    r.begin();
    this.drawArena(r, 0.42);
    // Platforms: foe upper-right, ally lower-left (wireframes §5.1 — the Uix
    // ruling: gameux §4.2's "upper-left" was the spec's error; the build is correct).
    const foeArt = g.spriteCache[this.foe.speciesId] || g.spriteCache.partner;
    const allyArt = g.spriteCache[this.ally.speciesId] || g.spriteCache.partner;
    const bob = Math.sin(this.t * 0.004) * 2;
    const foePos = { x: w * 0.62, y: h * 0.12 + bob };
    const allyPos = { x: w * 0.14, y: h * 0.52 - bob };
    // Idle bob: the build-time derived bob frame alternates with the sine.
    let foeSpr = (bob > 0 && foeArt.frontBob) ? foeArt.frontBob : foeArt.front;
    let allySpr = allyArt.back;
    // README impact transform: white palette-swap on the defender for 2 frames.
    if (this.impactFx) {
      if (this.impactFx.side === 'foe' && foeArt.frontWhite) foeSpr = foeArt.frontWhite;
      if (this.impactFx.side === 'ally' && allyArt.backWhite) allySpr = allyArt.backWhite;
    }
    const drawBattler = (spr, pos, side) => {
      if (this.faintFx && this.faintFx.side === side) return; // faint anim draws it
      // README attack transform: 1.2x scale for 3 frames, then back.
      if (this.atkFx && this.atkFx.side === side) r.blitS(spr, pos.x - 5, pos.y - 5, 58, 58);
      else r.blitS(spr, pos.x, pos.y, 48, 48); // 32px ART -> 48px draw size
    };
    // Platinum battle platforms: stepped discs under each battler (the far
    // foe disc is smaller — perspective), drawn before the sprites.
    this.ptDisc(r, foePos.x + 24, foePos.y + 44, 34, 8);
    this.ptDisc(r, allyPos.x + 24, allyPos.y + 44, 38, 9);
    drawBattler(foeSpr, foePos, 'foe');
    drawBattler(allySpr, allyPos, 'ally');
    // README faint transform: sink 8px + fade to 0 alpha over 20 frames.
    if (this.faintFx) {
      const k = Math.min(1, this.faintFx.t / 660);
      const c = r.ctx;
      c.save();
      c.globalAlpha = 1 - k;
      const pos = this.faintFx.side === 'foe' ? foePos : allyPos;
      r.blitS(this.faintFx.spr, pos.x, pos.y + 8 * k, 48, 48);
      c.restore();
    }
    // Catch ball arc
    if (this.state === 'catchseq' && this.catchState.phase === 'throw') {
      const k = Math.min(1, this.catchState.t / 430);
      const bx = w * 0.2 + (w * 0.5) * k;
      const by = h * 0.6 - Math.sin(k * Math.PI) * h * 0.35;
      g.ctx2dcircle(bx, by, 5, '#e84040');
    }
    if (this.state === 'catchseq' && this.catchState.phase === 'shakes') {
      const wob = Math.sin(this.catchState.t * 0.05) * 3;
      g.ctx2dcircle(w * 0.7 + wob, h * 0.3, 6, '#e8e8f0');
      g.ctx2dcircle(w * 0.7 + wob, h * 0.3 - 2, 6, '#e84040');
    }
    // P1/E10: success starburst — 8 gold rays radiating from the ball, fading.
    if (this.catchFx) {
      const k = this.catchFx.t / 500;
      const c = r.ctx;
      c.save();
      c.strokeStyle = 'rgba(232,200,50,' + (1 - k).toFixed(3) + ')';
      c.lineWidth = 2;
      const bx = w * 0.7, by = h * 0.3, r0 = 8 + k * 26;
      for (let s = 0; s < 8; s++) {
        const a = (s / 8) * Math.PI * 2;
        c.beginPath();
        c.moveTo(bx + Math.cos(a) * r0, by + Math.sin(a) * r0);
        c.lineTo(bx + Math.cos(a) * (r0 + 8), by + Math.sin(a) * (r0 + 8));
        c.stroke();
      }
      c.restore();
    }
    r.end();
    r.camX = pcx; r.camY = pcy;
    // HP plates (Platinum databoxes, original art) — P1/A5: all plate text >= 14px.
    this.plate(r, 6, 6, this.foe, this.hpAnim.foe, false);
    this.plate(r, w - 146, h - 124, this.ally, this.hpAnim.ally, true);
    // Message box (Platinum frame via r.panel/ptFrame)
    if (this.msgOpen || this.msg) {
      r.panel(4, h - 52, w - 8, 48, PT_PAPER, PT_FRAME);
      const txt = this.msg.length > 30 ? this.msg.slice(0, 30) : this.msg;
      r.text(txt, 10, h - 46, { size: 14, color: '#202028', shadow: false });
      if (this.msg.length > 30) r.text(this.msg.slice(30, 60), 10, h - 28, { size: 14, color: '#202028', shadow: false });
      // UI v2: red advance cue at the box's bottom-right while waiting for input.
      if (this.msgOpen) r.text('▼', w - 20, h - 24, { size: 14, bold: true, color: '#e03c31', shadow: false });
    }
    this.t += 16;
  }

  // UI v2 (Platinum standard): a true Platinum databox on r.ptPlate.
  // Canvas ops used here are fillRect / fillText / strokeRect ONLY (via
  // r.ptPlate, r.hpBar, r.xpBar, r.text and one direct fillRect for the
  // status chip / XP flash) — the QA recording-ctx plate test implements
  // just those. Every instance field is guarded: the QA minimal-this call
  // (only game.state.settings present) must yield zero slide/pulse offsets.
  plate(r, x, y, mon, hpShown, isAlly) {
    const settings = (this.game && this.game.state && this.game.state.settings) || {};
    const w = 140, h = isAlly ? 70 : 48;
    // Platinum plate entrance: foe slides in from the left, ally from the
    // right, ease-out over the battle's opening 450ms of theater time
    // (this.t, reset in enter()). A missing/non-finite timer (the QA
    // minimal-this call) means "entrance finished" — offset 0. Reduced
    // motion skips the slide entirely.
    let slide = 0;
    if (typeof this.t === 'number' && isFinite(this.t) && !settings.reducedMotion) {
      const p = Math.max(0, Math.min(1, this.t / 450));
      const e = 1 - (1 - p) * (1 - p);
      slide = (1 - e) * (w + 16);
    }
    let px = isAlly ? x + slide : x - slide;
    // P1/E7: low-HP pulse — the ally plate nudges twice on first red crossing
    // (never under reduced motion; the pulse timer is only set when motion is on).
    if (isAlly && this._lowHpPulseT > 0) px += Math.sin(this._lowHpPulseT * 0.05) * 2;
    r.ptPlate(px, y, w, h, isAlly);
    const ink = '#20242e';
    const name = displayName(mon, SPECIES).slice(0, 10);
    r.text(name, px + 6, y + 5, { size: 14, bold: true, color: ink, shadow: false });
    // Gender: mons/species carry no gender data anywhere in the game, so
    // the databox is gender-neutral — no symbol is drawn (UI v2 ruling).
    // 'Lv' + level, right-aligned inside the frame (a 10-char name at
    // px + 6 still clears the 'Lv100' block ending at px + w - 6).
    r.text('Lv' + mon.level, px + w - 6, y + 5, { size: 14, color: ink, shadow: false, align: 'right' });
    // HP row: gold 'HP' tag + the Platinum hpBar; the status chip slot is
    // reserved at the row's right end (the bar shortens when a chip shows).
    const fracRaw = hpShown / mon.maxHp;
    const frac = isFinite(fracRaw) ? Math.max(0, Math.min(1, fracRaw)) : 0;
    const chip = mon.status
      ? (STATUS_CHIPS[mon.status] || [String(mon.status).toUpperCase().slice(0, 3), '#5a6478'])
      : null;
    r.text('HP', px + 6, y + 23, { size: 14, bold: true, color: '#a87818', shadow: false });
    r.hpBar(px + 26, y + 27, chip ? w - 66 : w - 32, 7, frac);
    if (chip) {
      const c = r.ctx;
      c.fillStyle = chip[1];
      c.fillRect(px + w - 36, y + 22, 30, 16);
      r.text(chip[0], px + w - 33, y + 23, { size: 14, bold: true, color: '#ffffff', shadow: false });
    } else if (!isAlly && frac < 0.25 && mon.hp > 0) {
      // P0/E6: foe low-HP text cue in the empty chip slot (never color
      // alone; the hpBar's white stripe overlay is the always-on cue).
      // The ally plate carries its own '!' on the HP-numbers row below.
      r.text('!', px + w - 26, y + 23, { size: 14, bold: true, color: '#c02818', shadow: false });
    }
    if (isAlly) {
      // HP numbers row: low-HP '!' cue at the left, cur/max right-aligned.
      if (frac < 0.25 && mon.hp > 0) {
        r.text('!', px + 6, y + 40, { size: 14, bold: true, color: '#c02818', shadow: false });
      }
      r.text(Math.ceil(hpShown) + '/' + mon.maxHp, px + w - 6, y + 40, { size: 14, color: ink, shadow: false, align: 'right' });
      // EXP row: blue 'EXP' tag + the Platinum-blue xpBar (P0/E3: 600ms
      // ease-out via xpShownFrac; instant under reduced motion).
      r.text('EXP', px + 6, y + 54, { size: 14, bold: true, color: '#2f68b8', shadow: false });
      // xpShownFrac lives on the battle instance; the QA minimal-this plate
      // test calls plate() without it — fall back to the static fraction.
      const xfRaw = (typeof this.xpShownFrac === 'function') ? this.xpShownFrac(mon) : xpFracOf(mon, 0);
      const xf = isFinite(xfRaw) ? xfRaw : 0;
      r.xpBar(px + 34, y + 58, w - 40, 5, xf);
      if (this.xpFlashT > 0) {
        const c = r.ctx;
        c.fillStyle = 'rgba(255,255,255,' + (this.xpFlashT / 250 * 0.8).toFixed(3) + ')';
        c.fillRect(px + 34, y + 58, w - 40, 5);
      }
    }
  }
}


// ---- src/game/battle-rt.mjs ----
// battle-rt.mjs — REAL-TIME battle mode (ADR-020): free arena movement,
// per-move cooldowns, lunges/projectiles, a dodge roll with i-frames, live
// switching and real-time ball throws. Damage/catch/status MATH is the same
// classic chassis as the turn-based mode (formulas.mjs) — only the flow is
// real-time. The classic mode remains available (settings: Battle Style)
// and still runs the tutorial + Safari command battles.
// Theatre rule: while a dialogue or menu is open, the arena freezes.


const ARENA = { x0: 26, y0: 56, x1: 454, y1: 258 }; // logical 480x320 space

function clamp(v, a, b) { return Math.max(a, Math.min(b, v)); }
function dist(ax, ay, bx, by) { return Math.hypot(bx - ax, by - ay); }

function cooldownMs(mv, userSpe, foeSpe) {
  // ADR-020 review formula: power/accuracy/speed-advantage scaled, clamped.
  if (mv.cat === 'status') return 1500;
  return clamp(800 + (mv.power || 30) * 9 + (100 - (mv.acc || 100)) * 6 - (userSpe - foeSpe) * 3, 650, 4200);
}

Object.assign(BattleScene.prototype, {
  // ADR-021 control parity: on touch devices the DOM command panel IS the
  // move pad — four move buttons + BALL/TEAM/RUN, all pulsing the same Input
  // actions the keyboard produces (slot1-4 / a / start / select). Neither
  // front-end is a degraded mode.
  rtShowTouchCommands() {
    const g = this.game, ui = g.ui;
    if (!ui || ui.headless || !ui.cmdEl || typeof document === 'undefined') return;
    const inp = g.input;
    ui.cmdEl.innerHTML = '';
    ui.cmdEl.classList.remove('hidden');
    const mk = (label, fn, cls) => {
      const b = document.createElement('button');
      b.className = 'cmdf' + (cls ? ' ' + cls : '');
      b.textContent = label;
      b.addEventListener('pointerdown', (e) => { e.preventDefault(); fn(); });
      ui.cmdEl.appendChild(b);
      return b;
    };
    const pulse = (action) => { inp.press(action); setTimeout(() => inp.release(action), 90); };
    this.ally.moves.forEach((slot, i) => {
      const mv = MOVES[slot.id];
      mk(mv.name + ' (' + slot.pp + ')', () => pulse('slot' + (i + 1)));
    });
    while (this.ally.moves.length && ui.cmdEl.children.length < 4) mk('—', () => {});
    if (this.kind === 'wild') mk('BALL', () => pulse('a'));
    mk('TEAM', () => pulse('start'));
    mk('RUN', () => pulse('select'));
    this._rtCmdFor = this.ally.monId;
  },

  rtInit() {
    const g = this.game;
    this._rtLastFoe = this.foe;
    this.rt = {
      ax: 118, ay: 208, fx: 362, fy: 104, // battler positions
      face: 'right', foeFace: 'left',
      cds: { ally: {}, foe: {} },          // moveId -> ms remaining
      projs: [],                            // {x,y,tx,ty,speed,mv,side,t}
      lunge: null,                          // {side,t,dur,fromX,fromY,toX,toY,mv}
      dodgeT: 0, dodgeCd: 0, iframes: 0,
      foeStrafeT: 0, foeDir: 1, foeHoldT: 0,
      ballFlight: null, catchSeq: null,
      tickT: 0, msgCd: 0,
      allySleepT: 0, foeSleepT: 0,
      switchVulnT: 0,
    };
    this.state = 'rt';
    // (The enter() intro lines already announced the send-out — no repeat.)
  },

  rtResetFoe() {
    // Between trainer mons: fresh positions + cooldowns; XP pool already
    // reset by afterFaintFoe.
    this._rtLastFoe = this.foe;
    this.rt.fx = 362; this.rt.fy = 104;
    this.rt.cds.foe = {};
    this.rt.projs = this.rt.projs.filter((p) => p.side === 'ally');
    this.rt.foeSleepT = 0;
    this.state = 'rt';
  },

  rtFrozen() {
    const g = this.game;
    return this.msgOpen || !!g.ui.menu || !!g.ui.dialogue;
  },

  updateRt(dt) {
    const g = this.game;
    const input = g.input;
    const rt = this.rt;
    if (!rt) { this.toCommand(); return; }
    // Touch move pad follows the active battler (switches rebuild it).
    if (this._rtCmdFor !== this.ally.monId) this.rtShowTouchCommands();
    if (this.rtFrozen()) return;
    const dtms = dt * 1000;
    // Cooldowns
    for (const side of ['ally', 'foe']) {
      for (const k of Object.keys(rt.cds[side])) {
        rt.cds[side][k] -= dtms;
        if (rt.cds[side][k] <= 0) delete rt.cds[side][k];
      }
    }
    if (rt.dodgeCd > 0) rt.dodgeCd -= dtms;
    if (rt.dodgeT > 0) rt.dodgeT -= dtms;
    if (rt.iframes > 0) rt.iframes -= dtms;
    if (rt.switchVulnT > 0) rt.switchVulnT -= dtms;
    if (rt.msgCd > 0) rt.msgCd -= dtms;
    // Status clocks (sleep/paralysis handled at action time)
    if (rt.allySleepT > 0) rt.allySleepT -= dtms;
    if (rt.foeSleepT > 0) rt.foeSleepT -= dtms;
    // Poison/burn tick every 3s (turn-equivalent pressure).
    rt.tickT += dtms;
    if (rt.tickT >= 3000) {
      rt.tickT = 0;
      for (const mon of [this.ally, this.foe]) {
        if (mon && mon.hp > 0 && (mon.status === 'poison' || mon.status === 'burn' || mon.status === 'badlyPoisoned')) {
          mon.hp = Math.max(0, mon.hp - Math.max(1, Math.floor(mon.maxHp / 16)));
        }
        if (mon && mon.hp > 0 && mon.seeded) {
          const other = mon === this.ally ? this.foe : this.ally;
          const d = Math.max(1, Math.floor(mon.maxHp / 16));
          mon.hp = Math.max(0, mon.hp - d);
          if (other && other.hp > 0) other.hp = Math.min(other.maxHp, other.hp + d);
        }
      }
      if (this.rtCheckFaints()) return;
    }
    // Catch sequence animation runs on its own clock.
    if (rt.catchSeq) { this.rtUpdateCatch(dtms); return; }
    if (rt.ballFlight) { this.rtUpdateBall(dtms); return; }

    // ---- Player movement (free, speed-scaled) ----
    const allySpe = this.effStats(this.ally, this.allyStages).spe;
    const allyAsleep = this.ally.status === 'sleep' && rt.allySleepT > 0;
    let mx = 0, my = 0;
    if (!allyAsleep && !rt.lunge) {
      if (input.isHeld('left')) mx -= 1;
      if (input.isHeld('right')) mx += 1;
      if (input.isHeld('up')) my -= 1;
      if (input.isHeld('down')) my += 1;
    }
    const parSlowed = this.ally.status === 'paralysis' ? 0.55 : 1;
    let spd = (52 + allySpe * 0.55) * parSlowed;
    if (rt.dodgeT > 0) spd *= 2.15;
    if (mx || my) {
      const len = Math.hypot(mx, my) || 1;
      rt.ax = clamp(rt.ax + (mx / len) * spd * dt, ARENA.x0, ARENA.x1);
      rt.ay = clamp(rt.ay + (my / len) * spd * dt, ARENA.y0, ARENA.y1);
      rt.face = mx < 0 ? 'left' : mx > 0 ? 'right' : rt.face;
    }
    // Dodge roll: B while moving (or standing) — i-frames, 900ms cooldown.
    if (input.wasPressed('b') && rt.dodgeCd <= 0 && !allyAsleep) {
      rt.dodgeT = 230; rt.iframes = 260; rt.dodgeCd = 900;
      g.audio.playSfx('menu-move');
    }
    // Moves: slot keys fire directly (keyboard) — touch uses the same
    // actions through the on-screen battle buttons.
    if (!allyAsleep && !rt.lunge) {
      for (let i = 0; i < 4; i++) {
        if (input.wasPressed('slot' + (i + 1))) { this.rtUseMove('ally', i); break; }
      }
    }
    // Ball menu on A, party on START, run attempt on SELECT (wild only).
    if (input.wasPressed('a') && this.kind === 'wild' && !rt.ballFlight) this.rtBallMenu();
    if (input.wasPressed('start')) this.openPartyMenu(false);
    if (input.wasPressed('select') && this.kind === 'wild') this.rtTryRun();

    // ---- Foe AI ----
    this.rtFoeThink(dt, dtms);
    // ---- Lunges + projectiles ----
    this.rtUpdateLunge(dtms);
    this.rtUpdateProjs(dtms);
  },

  rtFoeThink(dt, dtms) {
    const g = this.game;
    const rt = this.rt;
    const foe = this.foe;
    if (!foe || foe.hp <= 0 || rt.lunge) return;
    if (foe.status === 'sleep' && rt.foeSleepT > 0) return;
    if (foe.status === 'freeze') return;
    const foeSpe = this.effStats(foe, this.foeStages).spe;
    const d = dist(rt.fx, rt.fy, rt.ax, rt.ay);
    // Preferred range: closest ready move decides (melee 40, ranged 130).
    let want = 120;
    const ready = foe.moves.map((m, i) => i).filter((i) => foe.moves[i].pp > 0 && !rt.cds.foe[foe.moves[i].id]
      && !(foe.disableT > 0 && foe.disabledMove === i));
    for (const i of ready) {
      const mv = MOVES[foe.moves[i].id];
      if (mv.cat === 'physical') { want = 40; break; }
    }
    rt.foeStrafeT -= dtms;
    if (rt.foeStrafeT <= 0) { rt.foeStrafeT = 700 + Math.random() * 900; rt.foeDir = Math.random() < 0.5 ? -1 : 1; }
    const spd = (46 + foeSpe * 0.5) * (foe.status === 'paralysis' ? 0.55 : 1);
    let vx = 0, vy = 0;
    if (d > want + 8) { vx = (rt.ax - rt.fx) / d; vy = (rt.ay - rt.fy) / d; }
    else if (d < want - 26) { vx = -(rt.ax - rt.fx) / d; vy = -(rt.ay - rt.fy) / d; }
    else { vx = (-(rt.ay - rt.fy) / (d || 1)) * rt.foeDir * 0.6; vy = ((rt.ax - rt.fx) / (d || 1)) * rt.foeDir * 0.6; }
    rt.fx = clamp(rt.fx + vx * spd * dt, ARENA.x0, ARENA.x1);
    rt.fy = clamp(rt.fy + vy * spd * dt, ARENA.y0, ARENA.y1);
    rt.foeFace = rt.ax < rt.fx ? 'left' : 'right';
    // Fire a ready move when in range (leaders pick better lines).
    if (ready.length && rt.foeHoldT <= 0) {
      let idx = ready[Math.floor(Math.random() * ready.length)];
      if (this.trainer && (this.trainer.ai === 'smart' || this.trainer.ai === 'opener-setup')) {
        const allyTypes = SPECIES[this.ally.speciesId].types;
        let bestScore = -1;
        for (const i of ready) {
          const mv = MOVES[foe.moves[i].id];
          if (mv.cat === 'status') continue;
          const s = effectiveness(mv.type, allyTypes) * (0.5 + Math.random());
          if (s > bestScore) { bestScore = s; idx = i; }
        }
      }
      const mv = MOVES[foe.moves[idx].id];
      const range = mv.cat === 'physical' ? 52 : 190;
      if (d <= range) { this.rtUseMove('foe', idx); rt.foeHoldT = 260 + Math.random() * 320; }
    }
    if (rt.foeHoldT > 0) rt.foeHoldT -= dtms;
  },

  rtUseMove(side, idx) {
    const g = this.game;
    const rt = this.rt;
    const atk = side === 'ally' ? this.ally : this.foe;
    const def = side === 'ally' ? this.foe : this.ally;
    const slot = atk.moves[idx];
    if (!slot || slot.pp <= 0) return;
    const mv = MOVES[slot.id];
    if (!mv || rt.cds[side][slot.id]) return;
    // Status gates at action time.
    if (atk.status === 'paralysis' && roll(0.25, g.rng.battle)) {
      if (side === 'ally') this.rtFloat(displayName(atk, SPECIES) + ' is paralyzed!');
      return;
    }
    if (atk.status === 'freeze') { if (side === 'ally') this.rtFloat(displayName(atk, SPECIES) + ' is frozen solid!'); return; }
    if (atk.confused && roll(0.5, g.rng.battle)) {
      const st = this.effStats(atk, side === 'ally' ? this.allyStages : this.foeStages);
      const dmg = Math.max(1, calcDamage(atk.level, 40, st.atk, st.def, {}));
      atk.hp = Math.max(0, atk.hp - dmg);
      this.rtFloat(displayName(atk, SPECIES) + ' hurt itself in confusion!');
      rt.cds[side][slot.id] = 900;
      this.rtCheckFaints();
      return;
    }
    slot.pp--;
    atk.lastMoveIdx = idx;
    const atkSpe = this.effStats(atk, side === 'ally' ? this.allyStages : this.foeStages).spe;
    const defSpe = this.effStats(def, side === 'ally' ? this.foeStages : this.allyStages).spe;
    rt.cds[side][slot.id] = cooldownMs(mv, atkSpe, defSpe);
    const ax = side === 'ally' ? rt.ax : rt.fx, ay = side === 'ally' ? rt.ay : rt.fy;
    const dx = side === 'ally' ? rt.fx : rt.ax, dy = side === 'ally' ? rt.fy : rt.ay;
    if (mv.cat === 'status') {
      if (dist(ax, ay, dx, dy) <= 200) this.rtApplyEffect(side, mv);
      else if (side === 'ally') this.rtFloat('Too far away!');
      return;
    }
    if (mv.cat === 'physical') {
      rt.lunge = { side, t: 0, dur: 190, mv, idx, hitDone: false };
      return;
    }
    rt.projs.push({ x: ax, y: ay, tx: dx, ty: dy, speed: 300, mv, side, t: 0 });
    g.audio.playSfx('menu-move');
  },

  rtUpdateLunge(dtms) {
    const rt = this.rt;
    if (!rt.lunge) return;
    const L = rt.lunge;
    L.t += dtms;
    const atkPos = L.side === 'ally' ? { x: rt.ax, y: rt.ay } : { x: rt.fx, y: rt.fy };
    const defPos = L.side === 'ally' ? { x: rt.fx, y: rt.fy } : { x: rt.ax, y: rt.ay };
    const k = Math.min(1, L.t / L.dur);
    const reach = dist(atkPos.x, atkPos.y, defPos.x, defPos.y);
    if (!L.hitDone && reach <= 50) {
      L.hitDone = true;
      this.rtApplyDamage(L.side, L.mv);
    }
    if (k >= 1) rt.lunge = null;
    else {
      // Dash toward the defender.
      const step = (340 * dtms) / 1000;
      const d = reach || 1;
      const nx = atkPos.x + ((defPos.x - atkPos.x) / d) * step;
      const ny = atkPos.y + ((defPos.y - atkPos.y) / d) * step;
      if (L.side === 'ally') { rt.ax = clamp(nx, ARENA.x0, ARENA.x1); rt.ay = clamp(ny, ARENA.y0, ARENA.y1); }
      else { rt.fx = clamp(nx, ARENA.x0, ARENA.x1); rt.fy = clamp(ny, ARENA.y0, ARENA.y1); }
    }
  },

  rtUpdateProjs(dtms) {
    const rt = this.rt;
    for (let i = rt.projs.length - 1; i >= 0; i--) {
      const p = rt.projs[i];
      const defPos = p.side === 'ally' ? { x: rt.fx, y: rt.fy } : { x: rt.ax, y: rt.ay };
      const d = dist(p.x, p.y, defPos.x, defPos.y);
      const step = (p.speed * dtms) / 1000;
      if (d <= Math.max(20, step)) {
        rt.projs.splice(i, 1);
        this.rtApplyDamage(p.side, p.mv);
      } else {
        p.x += ((defPos.x - p.x) / d) * step;
        p.y += ((defPos.y - p.y) / d) * step;
        p.t += dtms;
        if (p.t > 1600) rt.projs.splice(i, 1); // fizzle
      }
    }
  },

  rtAccHit(atk, def, mv, atkStages, defStages) {
    if (mv.neverMiss) return true;
    const g = this.game;
    // Gen-1 OHKO rule (ADR-018): (userLv - targetLv + 30) / 256.
    if ((mv.effect && mv.effect.ohko) || mv.ohko) {
      return roll(Math.max(0, Math.min(255, atk.level - def.level + 30)) / 256, g.rng.battle);
    }
    let p = ((mv.acc || 100) / 100) * accStageMultiplier(clamp((atkStages.acc || 0) - (defStages.eva || 0), -6, 6));
    if (p >= 1) p = 255 / 256;
    return roll(p, g.rng.battle);
  },

  rtApplyDamage(side, mv) {
    const g = this.game;
    const rt = this.rt;
    const atk = side === 'ally' ? this.ally : this.foe;
    const def = side === 'ally' ? this.foe : this.ally;
    const atkStages = side === 'ally' ? this.allyStages : this.foeStages;
    const defStages = side === 'ally' ? this.foeStages : this.allyStages;
    if (!atk || !def || def.hp <= 0) return;
    // Dodge i-frames: a dodging ally takes nothing.
    if (side === 'foe' && rt.iframes > 0) { this.rtFloat('Dodged!'); return; }
    if (!this.rtAccHit(atk, def, mv, atkStages, defStages)) {
      this.rtFloat(displayName(atk, SPECIES) + "'s " + mv.name + ' missed!');
      return;
    }
    const efx = mv.effect || {};
    const atkTypes = atk.tempTypes || (atk.transformed ? atk.transformed.types : SPECIES[atk.speciesId].types);
    const defTypes = def.tempTypes || (def.transformed ? def.transformed.types : SPECIES[def.speciesId].types);
    const eff = effectiveness(mv.type, defTypes);
    if (eff === 0) { this.rtFloat('It doesn\'t affect ' + displayName(def, SPECIES) + '...'); return; }
    if (efx.requiresSleep && def.status !== 'sleep') { this.rtFloat('But it failed!'); return; }
    const stab = atkTypes.includes(mv.type);
    const aStats = this.effStats(atk, atkStages);
    const dStats = this.effStats(def, defStages);
    const baseSpe = atk.transformed ? atk.transformed.baseSpe : SPECIES[atk.speciesId].base.spe;
    const crit = roll(critChance(baseSpe, { highCrit: !!mv.highcrit, focus: !!atk.focused }), g.rng.battle);
    const atkStat = mv.cat === 'physical' ? (crit ? atk.stats.atk : aStats.atk) : (crit ? atk.stats.spa : aStats.spa);
    const defStat = mv.cat === 'physical' ? (crit ? def.stats.def : dStats.def) : (crit ? def.stats.spd : dStats.spd);
    let dmg;
    if (mv.ohko || efx.ohko) dmg = def.hp;
    else if (efx.fixed) dmg = efx.fixed;
    else if (efx.fixedLevel) dmg = atk.level;
    else if (efx.psywave) dmg = Math.max(1, Math.floor(atk.level * (0.5 + g.rng.battle())));
    else {
      const hits = efx.hits ? (efx.hits[0] + Math.floor(g.rng.battle() * (efx.hits[1] - efx.hits[0] + 1))) : 1;
      dmg = 0;
      for (let hi = 0; hi < hits; hi++) {
        dmg += calcDamage(atk.level, mv.power, atkStat, defStat,
          { stab, effectiveness: eff, crit, random: gen1Random(g.rng.battle), burn: atk.status === 'burn', physical: mv.cat === 'physical' });
      }
    }
    if (mv.cat === 'physical' && def.reflectT > 0) dmg = Math.max(1, Math.floor(dmg / 2));
    if (mv.cat === 'special' && def.lightT > 0) dmg = Math.max(1, Math.floor(dmg / 2));
    if (def.subHp > 0) { def.subHp -= dmg; if (def.subHp <= 0) def.subHp = 0; dmg = 0; }
    if (dmg > 0) {
      def.hp = Math.max(0, def.hp - dmg);
      g.audio.hitFeedback(eff);
      if (crit) this.rtFloat('A critical hit!');
      else if (eff > 1) this.rtFloat("It's super effective!");
      else if (eff < 1) this.rtFloat("It's not very effective...");
      if (def.status === 'freeze' && mv.type === 'fire') def.status = null;
      if (efx.drain) atk.hp = Math.min(atk.maxHp, atk.hp + Math.floor(dmg * efx.drain));
      if (efx.recoil) atk.hp = Math.max(0, atk.hp - Math.max(1, Math.floor(dmg * efx.recoil)));
      let statusRoll = efx.status;
      if (efx.statusAny) statusRoll = efx.statusAny[Math.floor(g.rng.battle() * efx.statusAny.length)];
      if (statusRoll && def.hp > 0 && (!efx.chance || roll(efx.chance / 100, g.rng.battle))) {
        if (statusRoll === 'confusion') { def.confused = true; def.confusedTurns = 3; }
        else if (!def.status) {
          def.status = statusRoll;
          if (statusRoll === 'sleep') {
            const turns = 1 + Math.floor(g.rng.battle() * 7);
            if (def === this.foe) this.rt.foeSleepT = turns * 1100; else this.rt.allySleepT = turns * 1100;
          }
        }
      }
      for (const k of ['atk', 'def', 'spa', 'spd', 'spe', 'acc', 'eva']) {
        if (efx[k] && def.hp > 0 && (!efx.stageChance || roll(efx.stageChance / 100, g.rng.battle))) {
          if (!(def.mistT > 0 && efx[k] < 0)) defStages[k] = clamp((defStages[k] || 0) + efx[k], -6, 6);
        }
      }
      if (efx.flinch && def.hp > 0 && roll(efx.flinch / 100, g.rng.battle)) {
        rt.cds[side === 'ally' ? 'foe' : 'ally'] = {};
        this.rtFloat(displayName(def, SPECIES) + ' flinched!');
      }
      if (efx.seed) def.seeded = true;
      if (mv.recharge) rt.cds[side][atk.moves[atk.lastMoveIdx] ? atk.moves[atk.lastMoveIdx].id : mv.id] = (rt.cds[side][mv.id] || 0) + 1200;
      if (efx.selfFaint) atk.hp = 0;
    }
    this.rtCheckFaints();
  },

  rtApplyEffect(side, mv) {
    const g = this.game;
    const atk = side === 'ally' ? this.ally : this.foe;
    const def = side === 'ally' ? this.foe : this.ally;
    const ef = mv.effect || {};
    const atkStages = side === 'ally' ? this.allyStages : this.foeStages;
    const defStages = side === 'ally' ? this.foeStages : this.allyStages;
    if (ef.heal) { atk.hp = Math.min(atk.maxHp, atk.hp + Math.floor(atk.maxHp * ef.heal)); return; }
    if (ef.rest) { atk.hp = atk.maxHp; atk.status = 'sleep'; if (side === 'ally') this.rt.allySleepT = 2200; else this.rt.foeSleepT = 2200; return; }
    if (ef.substitute) { const c = Math.floor(atk.maxHp / 4); if (atk.subHp <= 0 && atk.hp > c) { atk.hp -= c; atk.subHp = c; } return; }
    if (ef.screen) { if (ef.screen === 'physical') atk.reflectT = 5; else atk.lightT = 5; return; }
    if (ef.mist) { atk.mistT = 5; return; }
    if (ef.focus) { atk.focused = true; return; }
    if (ef.seed) { def.seeded = true; return; }
    if (ef.haze) { for (const s of [this.allyStages, this.foeStages]) for (const k of Object.keys(s)) s[k] = 0; return; }
    if (ef.flee) { if (this.kind === 'wild' && side === 'ally') this.endBattle(true); return; }
    let applied = false;
    for (const k of ['atk', 'def', 'spa', 'spd', 'spe', 'acc', 'eva']) {
      if (ef[k]) {
        const stages = ef.target === 'self' ? atkStages : defStages;
        if (!(ef.target !== 'self' && def.mistT > 0 && ef[k] < 0)) {
          stages[k] = clamp((stages[k] || 0) + ef[k], -6, 6);
          applied = true;
        }
      }
    }
    if (ef.status && !applied) {
      const target = ef.target === 'self' ? atk : def;
      if (ef.status === 'confusion') { target.confused = true; target.confusedTurns = 3; }
      else if (!target.status) {
        target.status = ef.status;
        if (ef.status === 'sleep') {
          const turns = 1 + Math.floor(g.rng.battle() * 7);
          if (target === this.foe) this.rt.foeSleepT = turns * 1100; else this.rt.allySleepT = turns * 1100;
        }
      }
    }
  },

  rtFloat(text) {
    // Lightweight announcement lane for RT (full dialogue would freeze play).
    const rt = this.rt;
    if (!rt || rt.msgCd > 0) return;
    rt.msgCd = 500;
    this.game.ui.log.push({ ui: 'battle-rt', text });
    this.rtFloatText = text;
    this.rtFloatT = 1400;
  },

  rtBallMenu() {
    const g = this.game;
    const items = [];
    for (const bid of ['pokeball', 'greatball', 'ultraball', 'masterball']) {
      const n = g.state.bag[bid] || 0;
      items.push({ label: (bid === 'pokeball' ? 'Poke Ball' : bid === 'greatball' ? 'Great Ball' : bid === 'ultraball' ? 'Ultra Ball' : 'Master Ball') + ' x' + n, value: bid, disabled: n <= 0 });
    }
    items.push({ label: 'Back', value: null });
    g.ui.showMenu('Throw which ball? (A)', items, (v) => {
      if (v) this.rtThrowBall(v);
    });
  },

  rtThrowBall(ballId) {
    const g = this.game;
    if ((g.state.bag[ballId] || 0) <= 0) return;
    g.state.bag[ballId]--;
    const rt = this.rt;
    rt.ballFlight = { x: rt.ax, y: rt.ay, t: 0, dur: 330, ballId, fromX: rt.ax, fromY: rt.ay };
    g.audio.playSfx('catch-throw');
  },

  rtUpdateBall(dtms) {
    const rt = this.rt;
    const b = rt.ballFlight;
    b.t += dtms;
    const k = Math.min(1, b.t / b.dur);
    b.x = b.fromX + (rt.fx - b.fromX) * k;
    b.y = b.fromY + (rt.fy - b.fromY) * k - Math.sin(k * Math.PI) * 40;
    if (k >= 1) {
      rt.ballFlight = null;
      // A sprinting/dodging wild mon can evade the throw itself.
      const g = this.game;
      const foeMoving = Math.abs(this.rt.foeDir) > 0 && this.foe.status !== 'sleep' && this.foe.status !== 'freeze';
      if (foeMoving && roll(0.18, g.rng.battle)) {
        this.rtFloat('It dodged the ball!');
        return;
      }
      const foe = this.foe;
      const res = gen1Catch(foe.maxHp, foe.hp, SPECIES[foe.speciesId].catchRate, b.ballId, foe.status, g.rng.battle);
      rt.catchSeq = { t: 0, shakes: 0, need: res.caught ? 3 : res.shakes, willCatch: res.caught, ballId: b.ballId };
      g.audio.playSfx('catch-rattle');
    }
  },

  rtUpdateCatch(dtms) {
    const rt = this.rt;
    const c = rt.catchSeq;
    c.t += dtms;
    const doneShakes = Math.floor(c.t / 700);
    if (c.shakes < doneShakes && c.shakes < c.need) { c.shakes++; this.game.audio.playSfx('catch-rattle'); }
    if (c.t >= c.need * 700 + 260) {
      rt.catchSeq = null;
      if (c.willCatch) this.catchSuccess();
      else this.rtFloat('Oh no! ' + displayName(this.foe, SPECIES) + ' broke free!');
    }
  },

  rtTryRun() {
    const g = this.game;
    this.runAttempts++;
    const F = Math.floor((Math.max(1, this.ally.stats.spe) * 128) / Math.max(1, this.foe.stats.spe)) + 30 * this.runAttempts;
    if (F > 255 || Math.floor(g.rng.battle() * 256) < F) {
      this.say('Got away safely!', () => this.endBattle(true));
    } else {
      this.rtFloat("Can't escape!");
      this.rt.dodgeCd = Math.max(this.rt.dodgeCd, 600);
    }
  },

  rtCheckFaints() {
    const g = this.game;
    if (this.foe && this.foe.hp <= 0) {
      this.state = 'faintfoe';
      this.afterFaintFoe();
      return true;
    }
    if (this.ally && this.ally.hp <= 0) {
      const anyLeft = g.state.party.some((m) => m.hp > 0);
      if (!anyLeft) {
        this.state = 'defeat';
        this.say('You have no Pokemon left!', () => this.afterMsg());
      } else {
        this.openPartyMenu(true);
      }
      return true;
    }
    return false;
  },

  renderRt(r) {
    const g = this.game;
    const rt = this.rt;
    const w = r.viewW, h = r.viewH;
    const sx = w / 480, sy = h / 320;
    // Transform discipline (title/intro pattern): pin the camera to the
    // origin for the screen-space arena, restore it after end().
    const pcx = r.camX, pcy = r.camY; r.camX = 0; r.camY = 0;
    r.begin();
    // UI v2 (Platinum standard): the shared battlefield (drawArena/ptDisc
    // live in battle.mjs). The horizon is compressed to a top strip —
    // the RT arena's free movement spans the rest of the field, so the
    // stepped platforms travel with their battlers instead of sitting
    // fixed like the classic theater's (documented RT divergence).
    const c = r.ctx;
    this.drawArena(r, 0.22);
    if (!(rt.catchSeq || rt.ballFlight)) {
      this.ptDisc(r, rt.fx * sx, rt.fy * sy + 20, 30, 8);
    }
    this.ptDisc(r, rt.ax * sx, rt.ay * sy + 20, 30, 8);
    const foeArt = g.spriteCache[this.foe.speciesId] || g.spriteCache.partner;
    const allyArt = g.spriteCache[this.ally.speciesId] || g.spriteCache.partner;
    const bobA = Math.sin(this.t * 0.006) * 1.5;
    if (!(rt.catchSeq || rt.ballFlight)) {
      r.blitS(foeArt.front, rt.fx * sx - 24, rt.fy * sy - 24 + bobA, 48, 48);
    }
    const allySpr = this.ally.status === 'sleep' ? allyArt.back : allyArt.back;
    r.blitS(allySpr, rt.ax * sx - 24, rt.ay * sy - 24 - bobA, 48, 48);
    // Projectiles.
    for (const p of rt.projs) {
      g.ctx2dcircle(p.x * sx, p.y * sy, 4, p.side === 'ally' ? '#ffe27a' : '#ff9a7a');
    }
    // Ball flight + catch shakes.
    if (rt.ballFlight) {
      g.ctx2dcircle(rt.ballFlight.x * sx, rt.ballFlight.y * sy, 5, '#e84040');
    }
    if (rt.catchSeq) {
      const wob = Math.sin(rt.catchSeq.t * 0.05) * 3;
      g.ctx2dcircle(rt.fx * sx + wob, rt.fy * sy, 6, '#e8e8f0');
      g.ctx2dcircle(rt.fx * sx + wob, rt.fy * sy - 2, 6, '#e84040');
    }
    r.end();
    r.camX = pcx; r.camY = pcy;
    this.plate(r, 6, 6, this.foe, this.hpAnim.foe, false);
    this.plate(r, w - 146, h - 124, this.ally, this.hpAnim.ally, true);
    // Cooldown chips for the ally's four moves (bottom strip). Chip width is
    // derived from the actual view: the old fixed 108px assumed a 480-wide
    // canvas, so at real 256/384-wide layouts chips 3-4 started offscreen.
    const chipW = Math.floor((w - 24) / 4); // 4 chips, 3 gaps of 4, 6px margins
    const labelMax = Math.max(4, Math.min(10, Math.floor((chipW - 8) / 7)));
    for (let i = 0; i < 4; i++) {
      const slot = this.ally.moves[i];
      const x = 6 + i * (chipW + 4);
      const y = h - 26;
      if (!slot) { r.panel(x, y, chipW, 20, 'rgba(43,48,64,0.55)', PT_FRAME); continue; }
      const mv = MOVES[slot.id];
      const cd = rt.cds.ally[slot.id] || 0;
      const ready = cd <= 0 && slot.pp > 0;
      // UI v2: chips are Platinum windows (r.panel -> ptFrame) in PT tones —
      // navy PT_FRAME interior, PT_PAPER text when ready, PT_FRAME2 when not.
      r.panel(x, y, chipW, 20, ready ? 'rgba(43,48,64,0.92)' : 'rgba(43,48,64,0.6)', PT_FRAME);
      const label = (i + 1) + ' ' + (mv ? mv.name : slot.id);
      // A spent slot also carries 'NO PP' at the chip's right end — shorten
      // the label so the two never collide on narrow chips.
      const maxChars = slot.pp <= 0 ? Math.max(3, Math.min(labelMax, Math.floor((chipW - 46) / 7))) : labelMax;
      r.text(label.slice(0, maxChars), x + 4, y + 2, { size: 14, color: ready ? PT_PAPER : PT_FRAME2, shadow: false });
      if (!ready && slot.pp > 0) {
        // Cooldown pip: a PT_FRAME2 sweep draining along the chip's base.
        const total = cooldownMs(mv, 50, 50);
        const frac = Math.max(0, Math.min(1, cd / total));
        c.fillStyle = PT_FRAME2;
        c.fillRect(x + 2, y + 16, (chipW - 4) * (1 - frac), 2);
      }
      if (slot.pp <= 0) r.text('NO PP', x + chipW - 40, y + 2, { size: 14, color: '#f84838', shadow: false });
    }
    if (this.rtFloatText && this.rtFloatT > 0) {
      this.rtFloatT -= 16;
      // Panel fits the view and the text slice fits the panel (~7px/char at
      // 14px): the old fixed 30-char slice could overrun the 220px panel.
      const floatW = Math.min(220, w - 16);
      const floatMax = Math.max(8, Math.floor((floatW - 12) / 7));
      r.panel(w / 2 - floatW / 2, 40, floatW, 22, 'rgba(43,48,64,0.88)', PT_FRAME);
      r.text(this.rtFloatText.slice(0, floatMax), w / 2 - floatW / 2 + 6, 44, { size: 14, color: PT_PAPER, shadow: false });
    }
    if (this.msgOpen || this.msg) {
      r.panel(4, h - 52, w - 8, 48, PT_PAPER, PT_FRAME);
      const txt = this.msg.length > 30 ? this.msg.slice(0, 30) : this.msg;
      r.text(txt, 10, h - 46, { size: 14, color: '#202028', shadow: false });
      if (this.msg.length > 30) r.text(this.msg.slice(30, 60), 10, h - 28, { size: 14, color: '#202028', shadow: false });
      // UI v2: red advance cue at the box's bottom-right while waiting for input.
      if (this.msgOpen) r.text('▼', w - 20, h - 24, { size: 14, bold: true, color: '#e03c31', shadow: false });
    }
    this.t += 16;
  },
});


// ---- src/game/overworld.mjs ----
// overworld.mjs — tile-map exploration: interpolated grid movement, tall-grass
// encounters (rustle -> ! -> transition, 900ms per ADR-004), follower partner,
// NPCs, signs, warps, pause menu (Bag/Party/Dex/Save/Options).


const WALK_MS = 200; // ~200ms per walked tile (GD feel note)

class OverworldScene {
  enter() {
    const g = this.game;
    this.mapId = g.state.story.position.map;
    this.loadMap(this.mapId);
    const p = g.state.story.position;
    this.player = { tx: p.x, ty: p.y, px: p.x * TILE, py: p.y * TILE, dir: p.dir || 'down', moving: false, moveT: 0, fx: p.x, fy: p.y };
    this.trail = []; // partner path history
    this.partner = { px: this.player.px, py: this.player.py, hop: 0 };
    this.enc = null; // encounter sequence state
    this.challenge = null; // Yellow-style trainer spot challenge (sight -> ! -> walk-up)
    this.banner = { text: this.map.name.toUpperCase(), t: 0 };
    this.stepsSinceEncounter = 0;
    this.chainCount = 0;
    this.pausedMenu = false;
    // P1/C6: movement tutorial shows once until the player takes a first step (or 30s).
    this.moveTut = g.state.story.flags.moveTutDone ? null : { t: 0 };
    // HUD chip change-detection state (the DOM chips live in the UI seat;
    // syncHud pushes values only when they change). undefined = never sent.
    this._hudLoc = undefined; this._hudObj = undefined; this._hudDex = undefined;
    this._hudBannerObj = null;
    // P1/D7: partner mood pip — tap = pet (same as facing + A on Pikachu).
    g.ui.onMoodTap = () => this.petPartner();
    g.ui.showMoodPip(true);
    g.ui.setBattleMode(false);
    g.audio.playMusic(this.map.music || 'route1-theme'); // per-map original score (maps.mjs `music`)
  }

  loadMap(id) {
    this.mapId = id;
    this.map = MAPS[id];
    this.w = this.map.rows[0].length;
    this.h = this.map.rows.length;
    if (this.sysLoadMap) this.sysLoadMap(id);
    // Dynamic Pokemon Center exit (WS9): remember which city we came from.
    if (id === 'center' && this._lastCity) this.centerReturn = this._lastCity;
    if (id !== 'center') this._lastCity = { map: id, x: this.player ? this.player.tx : 7, y: this.player ? this.player.ty : 9 };
  }

  tileAt(x, y) {
    if (x < 0 || y < 0 || x >= this.w || y >= this.h) return ' ';
    return this.map.rows[y][x];
  }

  walkable(x, y) {
    const t = this.tileAt(x, y);
    if (this.boulderAt && this.boulderAt(x, y)) return false;
    const base = WALKABLE.has(t) || (this.sysWalkableExtra && this.sysWalkableExtra(x, y));
    if (!base) return false;
    // NPCs block
    for (const n of this.map.npcs) if (n.x === x && n.y === y) return false;
    return true;
  }

  warpAt(x, y) {
    for (const wp of this.map.warps) if (wp.x === x && wp.y === y) return wp;
    return null;
  }

  npcAt(x, y) {
    for (const n of this.map.npcs) if (n.x === x && n.y === y) return n;
    return null;
  }

  signAt(x, y) {
    for (const s of this.map.signs) if (s.x === x && s.y === y) return s;
    return null;
  }

  update(dt) {
    const g = this.game;
    if (g.ui.update(dt)) return; // modal UI consumes input
    if (this.enc) { this.updateEncounter(dt); return; }
    if (this.challenge) { this.updateChallenge(dt); return; } // input locked: a trainer is walking up
    if (this.checkSightLines()) return; // spotted this tick — challenge takes over

    const input = g.input;
    // Pause menu
    if (input.wasPressed('start') || input.wasPressed('escape')) {
      this.openPauseMenu();
      return;
    }
    // P1/D4: SELECT = registered item first (bicycle), then HUD quick-strip.
    if (input.wasPressed('select')) {
      if (!(this.sysSelect && this.sysSelect())) g.ui.setHudVisible(!g.ui.hudVisible);
      return;
    }
    // Interact
    if (input.wasPressed('a')) {
      if (this.tryInteract()) return;
    }

    // Movement
    const p = this.player;
    if (!p.moving) {
      const d = input.dir();
      if (d) {
        p.dir = d;
        const dx = d === 'left' ? -1 : d === 'right' ? 1 : 0;
        const dy = d === 'up' ? -1 : d === 'down' ? 1 : 0;
        if (this.walkable(p.tx + dx, p.ty + dy)) {
          p.moving = true; p.moveT = 0;
          p.fx = p.tx; p.fy = p.ty;
          p.tx += dx; p.ty += dy;
        } else if (this.fxState && this.fxState.strengthOn && this.boulderAt && this.boulderAt(p.tx + dx, p.ty + dy)) {
          // Strength push: shove the boulder one tile if the far side is free.
          const bx = p.tx + dx * 2, by = p.ty + dy * 2;
          const bt = this.tileAt(bx, by);
          if ((WALKABLE.has(bt) || bt === 'R') && !this.boulderAt(bx, by) && !this.npcAt(bx, by)) {
            const b = this.boulderAt(p.tx + dx, p.ty + dy);
            b.x = bx; b.y = by;
            p.moving = true; p.moveT = 0;
            p.fx = p.tx; p.fy = p.ty;
            p.tx += dx; p.ty += dy;
            g.audio.playSfx('menu-move');
          }
        }
      }
    } else {
      p.moveT += dt * 1000;
      const k = Math.min(1, p.moveT / (this.moveMs ? this.moveMs() : WALK_MS));
      p.px = (p.fx + (p.tx - p.fx) * k) * TILE;
      p.py = (p.fy + (p.ty - p.fy) * k) * TILE;
      if (k >= 1) {
        p.moving = false;
        p.px = p.tx * TILE; p.py = p.ty * TILE;
        this.trail.push({ x: p.tx, y: p.ty });
        if (this.trail.length > 24) this.trail.shift();
        this.onStep(p.tx, p.ty);
      }
    }
    // Partner follows 1 tile behind with hop
    const tp = this.trail.length >= 2 ? this.trail[this.trail.length - 2] : { x: p.tx, y: p.ty };
    const tpx = tp.x * TILE, tpy = tp.y * TILE;
    this.partner.px += (tpx - this.partner.px) * Math.min(1, dt * 10);
    this.partner.py += (tpy - this.partner.py) * Math.min(1, dt * 10);
    this.partner.hop += dt * 6;

    // Playtime + banner
    g.state.story.playtimeSec = (g.state.story.playtimeSec || 0);
    this.playAcc = (this.playAcc || 0) + dt;
    if (this.playAcc >= 1) { this.playAcc -= 1; g.state.player.playtimeSec++; }
    if (this.banner.t > 0) this.banner.t -= dt;
    // P1/C6: movement tutorial dismisses on first step or after 30s.
    if (this.moveTut) {
      this.moveTut.t += dt;
      if (this.moveTut.t > 30 || this.trail.length > 0) {
        this.moveTut = null;
        g.state.story.flags.moveTutDone = true;
      }
    }
  }

  onStep(x, y) {
    const g = this.game;
    const wp = this.warpAt(x, y);
    if (wp) {
      let to = wp.to;
      if (wp.viaExit) to = this.centerReturn || { map: 'pallet', x: 7, y: 9 };
      if (to.map === 'center' && wp.via) this.centerReturn = wp.via;
      this.loadMap(to.map);
      this.player.tx = to.x; this.player.ty = to.y;
      this.player.px = to.x * TILE; this.player.py = to.y * TILE;
      this.player.fx = to.x; this.player.fy = to.y;
      this.trail = [];
      this.partner.px = this.player.px; this.partner.py = this.player.py;
      g.state.story.position = { map: to.map, x: to.x, y: to.y, dir: this.player.dir };
      this.banner = { text: this.map.name.toUpperCase(), t: 1.6 };
      g.state.meta.location = this.map.name;
      g.audio.playMusic(this.map.music || 'route1-theme'); // no-op when the track is already playing
      g.audio.playSfx('map-enter'); // visual twin: the location banner slide-in
      g.autosave('area');
      return;
    }
    // Systems layer: events, safari steps, poison, water/cave encounters.
    if (this.sysOnStep && this.sysOnStep(x, y)) return;
    // Tall grass encounter check (anti-frustration: force after 20 silent steps)
    const t = this.tileAt(x, y);
    if (t === ',' && this.map.encounters && !g.state.story.flags.noEncounters) {
      // GD balance: the FIRST grass step on Route 1 is a scripted tutorial
      // encounter (Lv 3 Rattata), not a random roll — the <3min first-catch
      // gate is a certainty that teaches, never a gamble.
      if (this.mapId === 'route1' && !g.state.story.flags.tutorialDone) {
        this.startTutorialEncounter();
        return;
      }
      this.stepsSinceEncounter++;
      let p = this.map.encounters.rate;
      if (this.stepsSinceEncounter > 20) p = 1;
      if (this.chainCount >= 2) p = 0; // no triple chains
      if (roll(p, g.rng.encounter)) {
        this.startEncounter();
      } else {
        // GD balance (QA-003): the anti-chain counter measures CONSECUTIVE
        // random encounters — a quiet grass step breaks the chain, otherwise
        // encounters stay dead for the rest of the map visit.
        this.chainCount = 0;
      }
    } else {
      this.stepsSinceEncounter = 0;
    }
  }

  // ---- Yellow-style trainer vision (sight -> "!" -> walk-up -> battle) ----
  // An unbeaten trainer NPC with a `sight` cone spots the player standing in
  // its line, plays the alert, and walks over. Checked between steps only.
  // Duo NPCs (duoPartner) walk up together for a shared ambush.
  checkSightLines() {
    const p = this.player;
    if (p.moving) return false;
    const g = this.game;
    for (const n of this.map.npcs) {
      if (!n.trainer || !n.sight) continue;
      if (g.state.story.flags['beat_' + n.trainer]) continue;
      const dir = n.sight.dir || 'down';
      const range = n.sight.range || 3;
      const dx = dir === 'left' ? -1 : dir === 'right' ? 1 : 0;
      const dy = dir === 'up' ? -1 : dir === 'down' ? 1 : 0;
      for (let i = 1; i <= range; i++) {
        const tx = n.x + dx * i, ty = n.y + dy * i;
        if (tx === p.tx && ty === p.ty) { this.startChallenge(n); return true; }
        if (!this.walkable(tx, ty)) break; // sight blocked (wall, rock, another NPC)
      }
    }
    return false;
  }

  startChallenge(spotter) {
    const g = this.game;
    const parts = [{ npc: spotter, cx: spotter.x, cy: spotter.y }];
    if (spotter.duoPartner) {
      const mate = this.map.npcs.find((n) => n.name === spotter.duoPartner);
      if (mate && !g.state.story.flags['beat_' + mate.trainer]) {
        parts.push({ npc: mate, cx: mate.x, cy: mate.y });
      }
    }
    this.challenge = { parts, phase: 'spot', t: 0, stepT: 0 };
    g.audio.playSfx('trainer-spot'); // original two-note alert (visual twin: the ! mark)
    g.ui.log.push({ ui: 'trainer-spot', npcs: parts.map((q) => q.npc.name) });
  }

  updateChallenge(dt) {
    const g = this.game;
    const ch = this.challenge;
    ch.t += dt * 1000;
    const pl = this.player;
    if (ch.phase === 'spot') {
      if (ch.t >= 500) { ch.phase = 'walk'; ch.t = 0; ch.stepT = 0; }
      return;
    }
    // Walk phase: each challenger steps toward a tile adjacent to the player
    // (150ms/tile). The battle transition covers the snap-back to home tiles.
    const arrived = (q) => Math.abs(q.cx - pl.tx) + Math.abs(q.cy - pl.ty) <= 1;
    if (ch.parts.every(arrived) || ch.t > 3500) {
      const npc = ch.parts[0].npc;
      this.challenge = null;
      this.startTrainerBattle(npc);
      return;
    }
    ch.stepT += dt * 1000;
    if (ch.stepT >= 150) {
      ch.stepT = 0;
      for (const q of ch.parts) this.stepChallengerToward(q);
    }
  }

  stepChallengerToward(q) {
    const pl = this.player;
    if (Math.abs(q.cx - pl.tx) + Math.abs(q.cy - pl.ty) <= 1) return;
    const dx = pl.tx - q.cx, dy = pl.ty - q.cy;
    const opts = Math.abs(dx) >= Math.abs(dy)
      ? [[q.cx + Math.sign(dx), q.cy], [q.cx, q.cy + Math.sign(dy)]]
      : [[q.cx, q.cy + Math.sign(dy)], [q.cx + Math.sign(dx), q.cy]];
    for (const [nx, ny] of opts) {
      if (nx === pl.tx && ny === pl.ty) continue; // never step onto the player
      if (this.walkable(nx, ny)) { q.cx = nx; q.cy = ny; return; }
    }
  }

  startTutorialEncounter() {
    const g = this.game;
    g.state.story.flags.tutorialDone = true;
    this.stepsSinceEncounter = 0;
    this.chainCount = 0; // scripted tutorial isn't part of the random chain (QA-003)
    // Lv 3 Rattata: one Thunder Shock drops it to yellow (teaches weakening),
    // its Tackle does ~4 to a Lv 5 Pikachu (cannot threaten), and the battle
    // engine guarantees the catch once weakened + never lets it faint.
    this.enc = {
      phase: 'rustle', t: 0, tutorial: true,
      foe: makeMon('rattata', 3, SPECIES, MOVES),
    };
    g.audio.stopMusic();
    g.audio.encounter();
  }

  startEncounter() {
    const g = this.game;
    const table = this.map.encounters.table;
    const spId = pickWeighted(table.map((e) => [e.weight, e.species]), g.rng.encounter);
    const entry = table.find((e) => e.species === spId);
    const level = intIn(entry.min, entry.max, g.rng.encounter);
    this.enc = {
      phase: 'rustle', t: 0,
      foe: makeMon(spId, level, SPECIES, MOVES),
    };
    this.stepsSinceEncounter = 0;
    this.chainCount++;
    g.audio.stopMusic();       // area music yields to the battle
    g.audio.encounter();       // rustle + "!" melody (visual twin: rustle anim, then the ! mark)
  }

  updateEncounter(dt) {
    const g = this.game;
    const e = this.enc;
    e.t += dt * 1000;
    // 3-beat: rustle 200ms -> ! 300ms -> transition 400ms (ADR-004, gameux §6)
    if (e.phase === 'rustle' && e.t >= 200) { e.phase = 'exclaim'; e.t = 0; }
    else if (e.phase === 'exclaim' && e.t >= 300) {
      e.phase = 'transition'; e.t = 0;
      // P0/E11: encounter flash gated like battle flashes; reduced motion -> fade.
      if (!g.state.settings.reducedMotion && g.state.settings.shake) g.renderer.flashA = 0.7;
      else if (g.state.settings.reducedMotion) { g.renderer.fadeA = 0.35; g.renderer.fadeColor = '#ffffff'; }
      g.audio.transition(); // whoosh on the wipe; soft blip under reduced motion
    }
    else if (e.phase === 'transition' && e.t >= 400) {
      g.renderer.flashA = 0;
      g.renderer.fadeA = 0;
      const foe = e.foe;
      this.enc = null;
      dexRegister(g.state.dex, 'seen', SPECIES[foe.speciesId].dexNo);
      g.scenes.push(new BattleScene({ kind: 'wild', foe, returnTo: this, tutorial: !!e.tutorial, rt: g.state.settings.battleStyle !== 'classic' }));
    }
    if (g.renderer.flashA > 0 && e.phase !== 'transition') {
      g.renderer.flashA = Math.max(0, g.renderer.flashA - dt * 3);
    }
  }

  petPartner() {
    // P1/D7: mood-pip tap and the faced-tile interaction share one path.
    // Yellow homage: the partner emotes when talked to; petting cheers it up.
    const g = this.game;
    g.state.pikachu.mood = 'happy'; // a petting cheers it up (D7: mood reacts to beats)
    g.ui.toast('Pikachu ' + (PARTNER_MOODS[g.state.pikachu.mood] || PARTNER_MOODS.happy));
    g.audio.playSfx('partner-happy'); // visual twin: Pikachu hop + mood pip
    g.ui.updateMoodPip();
    return true;
  }

  tryInteract() {
    const g = this.game;
    const p = this.player;
    const dx = p.dir === 'left' ? -1 : p.dir === 'right' ? 1 : 0;
    const dy = p.dir === 'up' ? -1 : p.dir === 'down' ? 1 : 0;
    const fx = p.tx + dx, fy = p.ty + dy;
    // Partner interaction (facing Pikachu's tile)
    const ptx = Math.round(this.partner.px / TILE), pty = Math.round(this.partner.py / TILE);
    if (fx === ptx && fy === pty) return this.petPartner();
    // Systems interactions (item balls, hidden items, field moves, fishing)
    if (this.sysInteract && this.sysInteract(fx, fy)) return true;
    const npc = this.npcAt(fx, fy);
    if (npc) {
      if (this.sysNpc && this.sysNpc(npc)) return true;
      if (npc.trainer) { this.startTrainerBattle(npc); return true; }
      const lines = npc.dialogue.map((l) => l.replace('{player}', g.state.player.name));
      // GD balance: data-driven one-time item gifts (ball economy top-ups).
      const after = () => {
        if (npc.give && !g.state.story.flags[npc.give.flag]) {
          g.state.story.flags[npc.give.flag] = true;
          for (const item of Object.keys(npc.give.items)) {
            g.state.bag[item] = (g.state.bag[item] || 0) + npc.give.items[item];
          }
          g.ui.toast('Received ' + npc.give.text + '!');
        }
      };
      if (npc.heal) {
        g.ui.say(lines, () => {
          this.healParty(false);
          g.ui.say(npc.afterHeal || ['All better!'], after, npc.name);
        }, npc.name);
      } else {
        g.ui.say(lines, after, npc.name);
      }
      return true;
    }
    const sign = this.signAt(fx, fy);
    if (sign) { g.ui.say([sign.text]); return true; }
    // Also check the tile the player stands on for signs (adjacent readability)
    return false;
  }

  startTrainerBattle(npc) {
    const g = this.game;
    if (g.state.story.flags['beat_' + npc.trainer]) {
      g.ui.say(npc.dialogue.slice(1), null, npc.name);
      return;
    }
    const t = TRAINERS[npc.trainer];
    g.ui.say(t.intro, () => {
      g.scenes.push(new BattleScene({ kind: 'trainer', trainer: t, returnTo: this, rt: g.state.settings.battleStyle !== 'classic' }));
    }, npc.name);
  }

  healParty(announce) {
    const g = this.game;
    for (const m of g.state.party) {
      m.hp = m.maxHp; m.status = null;
      m.stages = { atk: 0, def: 0, spa: 0, spd: 0, spe: 0 };
      for (const mv of m.moves) mv.pp = mv.maxPp;
    }
    g.audio.playSfx('heal');
    if (announce) g.ui.toast('Your Pokemon were healed to full health!');
  }

  openPauseMenu() {
    const g = this.game;
    // P1/J2: player card header + Quit to title (confirm; autosaves first).
    const badges = g.state.badges.kanto.length;
    const mins = Math.floor((g.state.player.playtimeSec || 0) / 60);
    // Track B: account row — logged in shows the account menu; guest target
    // keeps the honest disabled row (Track A). Guests get NO row here: the
    // old 'Log in to sync ★' upsell was removed (login lives on the title
    // Terminal); a null row is filtered out of the menu list below.
    const authEnabled = (typeof AUTH_ENABLED !== 'undefined' && AUTH_ENABLED);
    const accountRow = !authEnabled
      ? { label: 'Account — coming in Track B', value: 'account', disabled: true }
      : g.authUser
        ? { label: 'Account', value: 'account' }
        : null;
    g.ui.showMenu('MENU', [
      { label: g.state.player.name + ' · ' + badges + ' badges · ' + mins + 'm', value: null, disabled: true },
      { label: this.map.name, value: null, disabled: true },
      { label: 'Bag', value: 'bag' },
      { label: 'Party', value: 'party' },
      { label: 'Dex', value: 'dex' },
      { label: 'Journey', value: 'journey' },
      { label: 'Save', value: 'save' },
      { label: 'Options', value: 'options' },
      ...(accountRow ? [accountRow] : []),
      { label: 'Quit to title', value: 'quit' },
      { label: 'Close', value: 'close' },
    ], (value) => {
      if (value === 'bag') g.openBag();
      else if (value === 'party') g.openParty();
      else if (value === 'dex') g.openDex();
      else if (value === 'journey') g.openJourney();
      else if (value === 'save') g.openSave();
      else if (value === 'options') g.openOptions();
      else if (value === 'account' && authEnabled && g.authUser) AUTH.openAccountMenu(g);
      else if (value === 'quit') {
        g.ui.showMenu('Quit to title? (autosaves first)', [
          { label: 'Quit', value: 'yes' },
          { label: 'Keep playing', value: 'no' },
        ], (v) => {
          if (v === 'yes') {
            g.saveGame(true);
            g.scenes.replace(new BootScene());
          }
        });
      }
    });
  }

  areaCompletion() {
    const g = this.game;
    if (!this.map.encounters) return null;
    const species = [...new Set(this.map.encounters.table.map((e) => e.species))];
    const caught = species.filter((s) => g.state.dex.caught[SPECIES[s].dexNo]).length;
    return { caught, total: species.length };
  }

  render(r) {
    const g = this.game;
    const T = TILE;
    // Camera centers on player
    r.centerOn(this.player.px + T / 2, this.player.py + T / 2, this.w * T, this.h * T);
    r.begin();
    // Tiles: hand-authored ART (wave 3); void stays a solid fill.
    const vr = r.viewRect();
    const x0 = Math.max(0, Math.floor(vr.x0 / T)), x1 = Math.min(this.w - 1, Math.ceil(vr.x1 / T));
    const y0 = Math.max(0, Math.floor(vr.y0 / T)), y1 = Math.min(this.h - 1, Math.ceil(vr.y1 / T));
    for (let y = y0; y <= y1; y++) {
      for (let x = x0; x <= x1; x++) {
        const ch = this.map.rows[y][x];
        const spr = g.tileSprite(g.tileKind(ch));
        if (spr) r.blit(spr, x * T, y * T);
        else g.ctx2dfill('#101018', x * T, y * T, T, T); // void
      }
    }
    // Encounter rustle effect
    if (this.enc && this.enc.phase === 'rustle') {
      const jx = (this.game.rng.misc() - 0.5) * 3;
      const gspr = g.tileSprite('grass');
      if (gspr) r.blit(gspr, this.player.tx * T + jx, this.player.ty * T);
    }
    // Systems world dressing: item balls, boulders, cut stumps, cave darkness.
    if (this.sysRenderWorld) this.sysRenderWorld(r);
    // NPCs (2-frame idle) — challengers render at their walk-up position.
    for (const n of this.map.npcs) {
      let nx = n.x * T, ny = n.y * T - 4;
      const cq = this.challenge && this.challenge.parts.find((q) => q.npc === n);
      if (cq) { nx = cq.cx * T; ny = cq.cy * T - 4; }
      r.blit(g.npcFrame(n), nx, ny);
    }
    // Yellow-style spot "!" over each challenger during the alert beat.
    if (this.challenge && this.challenge.phase === 'spot') {
      for (const q of this.challenge.parts) {
        r.text('!', q.cx * T + 4, q.cy * T - 16, { size: 14, bold: true, color: '#e84040' });
      }
    }
    // Partner (hop) + player (walk cycle / idle blink)
    const hop = Math.abs(Math.sin(this.partner.hop)) * 3;
    r.blit(g.partnerFrame(), Math.round(this.partner.px), Math.round(this.partner.py) - Math.round(hop));
    r.blit(g.playerSprite(this.player), Math.round(this.player.px), Math.round(this.player.py));
    // "!" exclamation
    if (this.enc && this.enc.phase === 'exclaim') {
      r.text('!', this.player.px + 4, this.player.py - 14, { size: 14, bold: true, color: '#e84040' });
    }
    // P1/C6: movement tutorial — the coach line moved to a one-shot DOM toast
    // (syncHud). On the map only a subtle spawn ring remains: it fades out
    // over the first 1.2s after spawn and never pulses again (the old endless
    // pulse read as a target reticle). The partner '▼' fades with it.
    if (this.moveTut) {
      const fade = Math.max(0, 1 - this.moveTut.t / 1.2);
      if (fade > 0) {
        const gold = 'rgba(255,233,168,' + fade.toFixed(3) + ')';
        const c = r.ctx;
        c.strokeStyle = gold; c.lineWidth = 2;
        c.beginPath(); c.arc(this.player.px + 8, this.player.py + 8, 12, 0, Math.PI * 2); c.stroke();
        r.text('▼', Math.round(this.partner.px) + 4, Math.round(this.partner.py) - 28, { size: 14, bold: true, color: gold, shadow: false });
      }
    }
    // P1/D5: contextual interaction prompt bubble.
    const prompt = this.interactPrompt();
    if (prompt) {
      const bx = Math.round(this.player.px) - 24, by = Math.round(this.player.py) - 30;
      r.panel(bx, by, 76, 20, '#f8f8f0', '#202028');
      // Centered in the bubble: with align:'center', x is the center point.
      r.text(prompt, bx + 38, by + 3, { size: 14, color: '#202028', shadow: false, align: 'center' });
    }
    // P1/D8: clock glyph — day/night pixel icon + season bar (no text, ambient).
    this.renderClockGlyph(r);
    r.end();
    // HUD lives in DOM chips now (UI seat): the area banner, the permanent
    // objective line, the area-completion line and the Dex counter are no
    // longer draped over the map as canvas text. Values are pushed on change.
    this.syncHud();
  }

  // Push location / objective / dex values to the UI seat's DOM chips, only
  // when a value actually changed. Every call is guarded so builds (and
  // headless suites) without the new UI methods never crash. The strings are
  // byte-identical to the old canvas draws — only the presentation moved.
  // The area banner and the movement tutorial become one-shot toasts.
  syncHud() {
    const g = this.game;
    const ui = g && g.ui;
    if (!ui) return;
    if (ui.setLocationChip) {
      const loc = this.map.name;
      if (loc !== this._hudLoc) { this._hudLoc = loc; ui.setLocationChip(loc); }
    }
    if (ui.setObjectiveChip) {
      const obj = this.objectiveText();
      if (obj !== this._hudObj) { this._hudObj = obj; ui.setObjectiveChip(obj); }
    }
    if (ui.setDexChip) {
      const dex = 'Dex ' + dexCaughtCount(g.state.dex) + '/' + DEX_TOTAL;
      if (dex !== this._hudDex) { this._hudDex = dex; ui.setDexChip(dex); }
    }
    if (ui.hudToast) {
      // Banner trigger: the banner object is REPLACED on every trigger —
      // in onStep's warp path and in overworld-systems (surf/fly/safari) —
      // so a fresh object with t > 0 is exactly one toast, never per frame.
      if (this.banner && this.banner.t > 0 && this.banner !== this._hudBannerObj) {
        this._hudBannerObj = this.banner;
        ui.hudToast(this.banner.text, 2600);
      }
      // Movement tutorial toast: once, when the tutorial starts.
      if (this.moveTut && !this.moveTut._toastSent) {
        this.moveTut._toastSent = true;
        ui.hudToast('Walk with the D-pad — Pikachu follows you!', 3600);
      }
    }
  }

  // P1/D5: what would A do on the faced tile? (bubble text, or null)
  interactPrompt() {
    const p = this.player;
    const dx = p.dir === 'left' ? -1 : p.dir === 'right' ? 1 : 0;
    const dy = p.dir === 'up' ? -1 : p.dir === 'down' ? 1 : 0;
    const fx = p.tx + dx, fy = p.ty + dy;
    const ptx = Math.round(this.partner.px / TILE), pty = Math.round(this.partner.py / TILE);
    if (fx === ptx && fy === pty) return 'A: Pet';
    if (this.npcAt(fx, fy)) return 'A: Talk';
    if (this.signAt(fx, fy)) return 'A: Read';
    return null;
  }

  // P1/D6: current story objective — quest-driven (WS6), slice spine as fallback.
  objectiveText() {
    if (this.sysObjective) { const t = this.sysObjective(); if (t) return t; }
    const f = this.game.state.story.flags;
    if (!f.beat_brock) return '▶ Earn the Boulder Badge';
    return '▶ Explore Kanto';
  }

  // P1/D8: day/night pixel icon + season color bar, top-right of canvas.
  renderClockGlyph(r) {
    const g = this.game;
    let hour = 12;
    try { hour = new Date().getHours(); } catch (e) { /* headless */ }
    const day = hour >= 6 && hour < 18;
    const x = r.viewW - 20, y = 22;
    const c = r.ctx;
    if (day) {
      c.fillStyle = '#f8d030';
      c.fillRect(x + 3, y, 6, 12); c.fillRect(x, y + 3, 12, 6);
      c.fillStyle = '#fff2b0';
      c.fillRect(x + 4, y + 4, 4, 4);
    } else {
      c.fillStyle = '#bfe8f0';
      c.fillRect(x + 3, y + 1, 6, 10); c.fillRect(x + 5, y, 8, 12);
      c.fillStyle = '#101018';
      c.fillRect(x + 6, y + 2, 5, 8);
    }
    // season bar: spr green / sum gold / aut orange / win blue
    let m = 0;
    try { m = new Date().getMonth(); } catch (e) { /* headless */ }
    const seasonCol = m < 2 || m === 11 ? '#5a9ae8' : m < 5 ? '#58c94f' : m < 8 ? '#e8c832' : '#e08a4a';
    c.fillStyle = seasonCol;
    c.fillRect(x, y + 14, 12, 3);
  }
}


// ---- src/game/overworld-systems.mjs ----
// overworld-systems.mjs — the campaign + parity systems layer (WS6/WS9):
// story event interpreter + quest log state, item balls + hidden items,
// field moves (Cut/Surf/Strength/Flash/Fly), fishing, poison walk damage,
// Safari Zone session, Game Corner slots + prizes, PC boxes, marts, NPC
// trades/gifts/revival/ferry, evolution execution, blackout handling.
// Attached to OverworldScene.prototype; overworld.mjs calls the sys* hooks.


const BOX_COUNT = 12;
const BOX_CAP = 20;
const FOSSIL_OF = { helixfossil: 'omanyte', domefossil: 'kabuto', oldamber: 'aerodactyl' };

function key(x, y) { return x + ',' + y; }
function rtOf(game) { return game.state.settings.battleStyle !== 'classic'; }

Object.assign(OverworldScene.prototype, {
  // ---------- map lifecycle ----------
  sysLoadMap(id) {
    const g = this.game;
    this.fxState = {
      cut: new Set(),           // cut trees (regrow on map re-entry, as the original)
      boulders: new Map(),      // 'x,y' -> {x,y} current boulder positions
      strengthOn: false,
      flashLit: false,
    };
    if (this.map) {
      for (let y = 0; y < this.map.rows.length; y++) {
        for (let x = 0; x < this.map.rows[y].length; x++) {
          if (this.map.rows[y][x] === 'B') this.fxState.boulders.set(key(x, y), { x, y });
        }
      }
      if (this.map.centerCity) g.state.story.flags['visited_' + id] = true;
    }
    if (g.state.story.flags['in_' + id] === undefined) g.state.story.flags['in_' + id] = true;
    g.state.story.flags['reached_' + id] = true; // quest chain producers (WS6)
  },

  boulderAt(x, y) {
    if (!this.fxState) return null;
    for (const b of this.fxState.boulders.values()) if (b.x === x && b.y === y) return b;
    return null;
  },

  sysWalkableExtra(x, y) {
    // Called from walkable(): tiles the base set rejects but systems allow.
    const t = this.tileAt(x, y);
    if (t === 'T' && this.fxState && this.fxState.cut.has(key(x, y))) return true;
    if ((t === '~' || t === 'W') && this.surfing) return true;
    return false;
  },

  moveMs() {
    if (this.surfing) return 170;
    if (this.riding) return 105;
    return 200;
  },

  // ---------- per-step systems ----------
  sysOnStep(x, y) {
    const g = this.game;
    const t = this.tileAt(x, y);
    // Landing on shore ends surfing.
    if (this.surfing && t !== '~' && t !== 'W') this.surfing = false;
    // Safari session step budget.
    const saf = g.state.session.safari;
    if (saf) {
      saf.steps--;
      if (saf.steps <= 0) { this.endSafari('Your safari time is up!'); return true; }
      if (saf.steps === 50) g.ui.toast('Safari: 50 steps left!');
    }
    // Poison walk damage: every 4 steps, 1 HP per poisoned mon (original).
    this.poisonSteps = (this.poisonSteps || 0) + 1;
    if (this.poisonSteps >= 4) {
      this.poisonSteps = 0;
      let anyAlive = false;
      for (const m of g.state.party) {
        if (m.hp > 0 && (m.status === 'poison' || m.status === 'badlyPoisoned')) m.hp = Math.max(1, m.hp - 1);
        if (m.hp > 0) anyAlive = true;
      }
      if (!anyAlive && g.state.party.length) { this.blackout(); return true; }
      const hurt = g.state.party.find((m) => (m.status === 'poison' || m.status === 'badlyPoisoned') && m.hp > 0);
      if (hurt) g.ui.toast(displayName(hurt, SPECIES) + ' is hurt by poison...');
    }
    // Water + cave encounters (grass handled by the base onStep).
    if (this.sysEncounterStep(x, y, t)) return true;
    // Story event tiles.
    if (this.map.events) {
      for (const ev of this.map.events) {
        if (ev.x === x && ev.y === y && this.eventWhen(ev.when)) {
          this.runEvent(ev.id);
          return true;
        }
      }
    }
    return false;
  },

  sysEncounterStep(x, y, t) {
    const g = this.game;
    const enc = this.map.encounters;
    if (!enc || g.state.story.flags.noEncounters) return false;
    const saf = g.state.session.safari;
    let table = null, rate = 0;
    if (saf && this.mapId === 'safari' && t === ',') { table = enc.table; rate = enc.rate; }
    else if (this.surfing && (t === '~' || t === 'W') && enc.water) { table = enc.water; rate = enc.waterRate || 0.08; }
    else if (enc.cave && (t === '.' || t === 'R')) { table = enc.table; rate = enc.rate; }
    if (!table) return false;
    if (!roll(rate, g.rng.encounter)) return false;
    const spId = pickWeighted(table.map((e) => [e.weight, e.species]), g.rng.encounter);
    const entry = table.find((e) => e.species === spId);
    const level = intIn(entry.min, entry.max, g.rng.encounter);
    const foe = makeMon(spId, level, SPECIES, MOVES);
    dexRegister(g.state.dex, 'seen', SPECIES[spId].dexNo);
    g.audio.stopMusic();
    g.audio.encounter();
    if (saf) {
      g.scenes.push(new BattleScene({
        kind: 'wild', foe, returnTo: this, safari: true,
        onSafariAction: () => { const s = g.state.session.safari; if (s) { s.steps -= 5; } },
      }));
    } else {
      g.scenes.push(new BattleScene({ kind: 'wild', foe, returnTo: this, rt: rtOf(g) }));
    }
    return true;
  },

  // ---------- story events ----------
  eventWhen(when) {
    if (!when) return true;
    const g = this.game;
    const f = g.state.story.flags;
    if (when.flagNot && f[when.flagNot]) return false;
    if (when.flag && !f[when.flag]) return false;
    if (when.flagAny && !when.flagAny.some((k) => f[k])) return false;
    if (when.badgesAtLeast !== undefined && g.state.badges.kanto.length < when.badgesAtLeast) return false;
    if (when.badgesBelow !== undefined && g.state.badges.kanto.length >= when.badgesBelow) return false;
    if (when.bagHas && !(g.state.bag[when.bagHas] > 0)) return false;
    if (when.noBag && g.state.bag[when.noBag] > 0) return false;
    if (when.teach && !this.partyKnows(when.teach)) return false;
    return true;
  },

  partyKnows(moveId) {
    return this.game.state.party.some((m) => m.moves.some((mv) => mv.id === moveId));
  },
  partyHasType(type) {
    return this.game.state.party.some((m) => m.hp > 0 && SPECIES[m.speciesId].types.includes(type));
  },

  runEvent(id) {
    const steps = EVENTS[id];
    if (!steps) return;
    const g = this.game;
    // Completion flag convention (the placements gate on it):
    // ev_e4_1 -> ev_e4_1_done; bare ids -> ev_<id>_done.
    const doneFlag = id.startsWith('ev_') ? id + '_done' : 'ev_' + id + '_done';
    this.runSteps(steps, 0, () => { g.state.story.flags[doneFlag] = true; });
  },

  runSteps(steps, i, done) {
    const g = this.game;
    if (i >= steps.length) { if (done) done(); return; }
    const s = steps[i];
    const next = () => this.runSteps(steps, i + 1, done);
    if (s.say) { g.ui.say(s.say, next, s.who || ''); return; }
    if (s.toast) { g.ui.toast(s.toast); next(); return; }
    if (s.flag) { g.state.story.flags[s.flag] = true; next(); return; }
    if (s.quest) { g.state.story.quests[s.quest] = 'active'; next(); return; }
    if (s.questDone) { g.state.story.quests[s.questDone] = 'complete'; next(); return; }
    if (s.arc) { g.state.story.quests[s.arc] = s.stage; next(); return; }
    if (s.heal) { this.healParty(false); g.ui.toast('The party was healed!'); next(); return; }
    if (s.give) {
      for (const item of Object.keys(s.give.items || {})) {
        g.state.bag[item] = (g.state.bag[item] || 0) + s.give.items[item];
      }
      if (s.give.text) g.ui.toast(s.give.text);
      next(); return;
    }
    if (s.giveMon) { this.giftMon(s.giveMon.species, s.giveMon.level, next); return; }
    if (s.chapterCard !== undefined) {
      const ch = CHAPTERS[s.chapterCard];
      if (ch && g.ui.showChapterCard) g.ui.showChapterCard(ch);
      next(); return;
    }
    if (s.warp) {
      this.loadMap(s.warp.map);
      this.player.tx = s.warp.x; this.player.ty = s.warp.y;
      this.player.px = s.warp.x * TILE; this.player.py = s.warp.y * TILE;
      this.player.fx = s.warp.x; this.player.fy = s.warp.y;
      this.trail = [];
      g.state.story.position = { map: s.warp.map, x: s.warp.x, y: s.warp.y, dir: this.player.dir };
      this.banner = { text: this.map.name.toUpperCase(), t: 1.6 };
      g.audio.playMusic(this.map.music || 'route1-theme');
      next(); return;
    }
    if (s.battle) {
      const t = TRAINERS[s.battle];
      if (!t) { next(); return; }
      g.scenes.push(new BattleScene({
        kind: 'trainer', trainer: t, returnTo: this, rt: rtOf(g),
        onEnd: (won) => { if (won) next(); },
      }));
      return;
    }
    if (s.wildBattle) {
      const wb = s.wildBattle;
      const foe = makeMon(wb.species, wb.level, SPECIES, MOVES);
      dexRegister(g.state.dex, 'seen', SPECIES[wb.species].dexNo);
      g.scenes.push(new BattleScene({
        kind: 'wild', foe, returnTo: this, rt: rtOf(g),
        uncatchable: !!wb.uncatchable, legendary: !!wb.legendary,
        onEnd: (won) => { if (won) next(); },
      }));
      return;
    }
    if (s.ending) { this.runEnding(next); return; }
    next();
  },

  runEnding(done) {
    const g = this.game;
    // Hall of Fame registration: the winning team is recorded forever.
    const hof = g.state.story.hof || (g.state.story.hof = []);
    hof.push({
      team: g.state.party.map((m) => ({ speciesId: m.speciesId, level: m.level, nickname: m.nickname })),
      badges: g.state.badges.kanto.length,
    });
    g.state.story.flags.champion = true;
    g.ui.say(CREDITS_LINES.slice(), () => { if (done) done(); }, '');
  },

  giftMon(speciesId, level, next) {
    const g = this.game;
    const mon = makeMon(speciesId, level, SPECIES, MOVES);
    dexRegister(g.state.dex, 'caught', SPECIES[speciesId].dexNo);
    if (g.state.party.length < 6) g.state.party.push(mon);
    else {
      const boxId = g.state.currentBox || 'box1';
      const box = g.state.boxes[boxId] || (g.state.boxes[boxId] = []);
      box.push(mon);
    }
    g.audio.playSfx('dex-register');
    g.ui.toast('Received ' + SPECIES[speciesId].name + '!');
    if (next) next();
  },

  // ---------- interaction systems ----------
  sysInteract(fx, fy) {
    const g = this.game;
    const t = this.tileAt(fx, fy);
    // Item balls.
    if (this.map.items) {
      for (const b of this.map.items) {
        if (b.x === fx && b.y === fy) {
          const flag = 'item_' + this.mapId + '_' + fx + '_' + fy;
          if (g.state.story.flags[flag]) { g.ui.say(['There is nothing here.']); return true; }
          // Mt. Moon fossil pair: taking one seals the other (original beat).
          if ((b.item === 'helixfossil' || b.item === 'domefossil') && g.state.story.flags.fossil_taken) {
            g.ui.say(['Only crumbled stone remains. You chose your fossil already.']);
            return true;
          }
          g.state.story.flags[flag] = true;
          if (b.item === 'helixfossil' || b.item === 'domefossil') g.state.story.flags.fossil_taken = true;
          g.state.bag[b.item] = (g.state.bag[b.item] || 0) + (b.n || 1);
          g.audio.playSfx('dex-register');
          g.ui.say(['Found ' + (ITEMS[b.item] ? ITEMS[b.item].name : b.item) + '!']);
          return true;
        }
      }
    }
    // Hidden items (face the exact tile).
    if (this.map.hidden) {
      for (const hb of this.map.hidden) {
        if (hb.x === fx && hb.y === fy) {
          const flag = 'hidden_' + this.mapId + '_' + fx + '_' + fy;
          if (!g.state.story.flags[flag]) {
            g.state.story.flags[flag] = true;
            g.state.bag[hb.item] = (g.state.bag[hb.item] || 0) + (hb.n || 1);
            g.audio.playSfx('dex-register');
            g.ui.say(['Found a hidden ' + (ITEMS[hb.item] ? ITEMS[hb.item].name : hb.item) + '!']);
            return true;
          }
        }
      }
    }
    // Cut tree.
    if (t === 'T') {
      if (this.fxState.cut.has(key(fx, fy))) return false;
      if (this.partyKnows('cut') && g.state.badges.kanto.includes('cascadebadge')) {
        this.fxState.cut.add(key(fx, fy));
        g.audio.playSfx('map-enter');
        g.ui.say(['The tree was cut down!']);
      } else if (this.partyKnows('cut')) {
        g.ui.say(['A cuttable tree. The Cascade Badge is needed to use CUT out here.']);
      } else {
        g.ui.say(['A small tree blocks the way. It looks cuttable.']);
      }
      return true;
    }
    // Boulder: activate Strength.
    if (this.boulderAt(fx, fy)) {
      if (this.partyKnows('strength') && g.state.badges.kanto.includes('rainbowbadge')) {
        this.fxState.strengthOn = true;
        g.ui.say(['Strength made it possible to move boulders!']);
      } else {
        g.ui.say(['A huge boulder. It would take real STRENGTH to budge it.']);
      }
      return true;
    }
    // Water: Surf or fish.
    if (t === '~' || t === 'W') {
      if (!this.surfing) {
        if (this.partyKnows('surf') && g.state.badges.kanto.includes('soulbadge')) {
          g.ui.showMenu('The water is a deep blue... Surf?', [
            { label: 'Surf', value: 'surf' }, { label: 'Fish', value: 'fish' }, { label: 'Not now', value: 'no' },
          ], (v) => {
            if (v === 'surf') this.startSurf(fx, fy);
            else if (v === 'fish') this.startFishing();
          });
          return true;
        }
        this.startFishing();
        return true;
      }
      return false;
    }
    // Itemfinder hint on an empty interact.
    if ((g.state.bag.itemfinder || 0) > 0 && this.map.hidden) {
      for (const hb of this.map.hidden) {
        const flag = 'hidden_' + this.mapId + '_' + hb.x + '_' + hb.y;
        if (!g.state.story.flags[flag] && Math.abs(hb.x - fx) + Math.abs(hb.y - fy) <= 2) {
          g.ui.toast('The Itemfinder is reacting...');
          break;
        }
      }
    }
    return false;
  },

  startSurf(fx, fy) {
    const p = this.player;
    this.surfing = true;
    p.fx = p.tx; p.fy = p.ty;
    p.tx = fx; p.ty = fy;
    p.moving = true; p.moveT = 0;
    this.game.audio.playSfx('map-enter');
  },

  startFishing() {
    const g = this.game;
    const rod = (g.state.bag.superrod > 0) ? 'super' : (g.state.bag.goodrod > 0) ? 'good' : (g.state.bag.oldrod > 0) ? 'old' : null;
    if (!rod) { g.ui.say(['The water glitters. If only you had a fishing rod...']); return; }
    const fish = this.map.encounters && this.map.encounters.fish && this.map.encounters.fish[rod];
    g.audio.playSfx('menu-move');
    if (!fish || !roll(0.55, g.rng.encounter)) { g.ui.say(['...Not even a nibble.']); return; }
    const spId = pickWeighted(fish.map((e) => [e.weight, e.species]), g.rng.encounter);
    const entry = fish.find((e) => e.species === spId);
    const level = intIn(entry.min, entry.max, g.rng.encounter);
    const foe = makeMon(spId, level, SPECIES, MOVES);
    dexRegister(g.state.dex, 'seen', SPECIES[spId].dexNo);
    g.ui.say(['Oh! A bite!'], () => {
      g.audio.stopMusic();
      g.audio.encounter();
      g.scenes.push(new BattleScene({ kind: 'wild', foe, returnTo: this, rt: rtOf(g) }));
    });
  },

  sysSelect() {
    const g = this.game;
    if ((g.state.bag.bicycle || 0) > 0 && !this.map.indoor) {
      this.riding = !this.riding;
      g.ui.toast(this.riding ? 'Got on the bicycle!' : 'Got off the bicycle.');
      g.audio.playSfx('menu-move');
      return true;
    }
    return false;
  },

  // ---------- NPC systems ----------
  sysNpc(npc) {
    const g = this.game;
    const sayLines = (cb) => g.ui.say(npc.dialogue.map((l) => l.replace('{player}', g.state.player.name)), cb, npc.name);
    if (npc.event) {
      if (!g.state.story.flags['evdone_' + npc.event]) {
        g.state.story.flags['evdone_' + npc.event] = true;
        this.runEvent(npc.event);
      } else sayLines(null);
      return true;
    }
    if (npc.pc) { sayLines(() => this.openPc()); return true; }
    if (npc.mart) { sayLines(() => this.openMart(npc.mart.stock || [])); return true; }
    if (npc.slots) { sayLines(() => this.openSlots()); return true; }
    if (npc.prize) {
      sayLines(() => {
        const cost = npc.prize.coins;
        const coins = g.state.bag.coin || 0;
        g.ui.showMenu(SPECIES[npc.prize.species].name + ' — ' + cost + ' coins (you have ' + coins + ')', [
          { label: 'Exchange', value: 'yes', disabled: coins < cost },
          { label: 'Not now', value: 'no' },
        ], (v) => { if (v === 'yes') { g.state.bag.coin -= cost; this.giftMon(npc.prize.species, npc.prize.level || 15, null); } });
      });
      return true;
    }
    if (npc.trade) {
      sayLines(() => {
        const have = g.state.party.find((m) => m.speciesId === npc.trade.give);
        g.ui.showMenu('Trade your ' + SPECIES[npc.trade.give].name + ' for ' + SPECIES[npc.trade.get].name + '?', [
          { label: 'Trade', value: 'yes', disabled: !have },
          { label: 'Not now', value: 'no' },
        ], (v) => {
          if (v !== 'yes' || !have) return;
          const idx = g.state.party.indexOf(have);
          const mon = makeMon(npc.trade.get, have.level, SPECIES, MOVES);
          mon.nickname = npc.trade.nickname || null;
          mon.ot = npc.name;
          mon.tradedFrom = npc.trade.give;
          g.state.party.splice(idx, 1, mon);
          dexRegister(g.state.dex, 'caught', SPECIES[npc.trade.get].dexNo);
          g.audio.playSfx('dex-register');
          g.ui.say(['Trade complete! Take good care of ' + (mon.nickname || SPECIES[mon.speciesId].name) + '.'], null, npc.name);
        });
      });
      return true;
    }
    if (npc.giveMon) {
      const flag = 'gift_' + this.mapId + '_' + npc.name;
      if (g.state.story.flags[flag]) { sayLines(null); return true; }
      sayLines(() => {
        g.state.story.flags[flag] = true;
        this.giftMon(npc.giveMon.species, npc.giveMon.level, null);
      });
      return true;
    }
    if (npc.revive) {
      sayLines(() => {
        const fossils = Object.keys(FOSSIL_OF).filter((f) => (g.state.bag[f] || 0) > 0);
        if (!fossils.length) { g.ui.say(['Bring me a fossil or Old Amber and my machine will do the rest.'], null, npc.name); return; }
        const items = fossils.map((f) => ({ label: 'Revive ' + ITEMS[f].name + ' -> ' + SPECIES[FOSSIL_OF[f]].name, value: f }));
        items.push({ label: 'Not now', value: null });
        g.ui.showMenu('Fossil revival', items, (v) => {
          if (!v) return;
          g.state.bag[v]--;
          this.giftMon(FOSSIL_OF[v], 30, null);
        });
      });
      return true;
    }
    if (npc.ferry) {
      sayLines(() => {
        g.ui.showMenu('Sail to ' + npc.ferry + '?', [
          { label: 'Sail', value: 'yes' }, { label: 'Stay', value: 'no' },
        ], (v) => {
          if (v !== 'yes') return;
          const dest = MAPS[npc.ferry];
          const st = (dest && dest.start) || { x: 7, y: 7 };
          this.loadMap(npc.ferry);
          this.player.tx = st.x; this.player.ty = st.y;
          this.player.px = st.x * TILE; this.player.py = st.y * TILE;
          this.player.fx = st.x; this.player.fy = st.y;
          this.trail = [];
          g.state.story.position = { map: npc.ferry, x: st.x, y: st.y, dir: 'up' };
          this.banner = { text: this.map.name.toUpperCase(), t: 1.6 };
          g.audio.playMusic(this.map.music || 'route1-theme');
        });
      });
      return true;
    }
    if (npc.safariGate) {
      sayLines(() => {
        if (g.state.session.safari) { this.endSafari('You left the Safari Zone.'); return; }
        g.ui.showMenu('Safari Zone: $500 for 500 steps + 30 Safari Balls.', [
          { label: 'Enter ($500)', value: 'yes', disabled: g.state.player.money < 500 },
          { label: 'Not now', value: 'no' },
        ], (v) => {
          if (v !== 'yes') return;
          g.state.player.money -= 500;
          g.state.session.safari = { steps: 500 };
          g.state.bag.safariball = (g.state.bag.safariball || 0) + 30;
          const st = MAPS.safari.start || { x: 10, y: 17 };
          this.loadMap('safari');
          this.player.tx = st.x; this.player.ty = st.y;
          this.player.px = st.x * TILE; this.player.py = st.y * TILE;
          this.player.fx = st.x; this.player.fy = st.y;
          this.trail = [];
          g.state.story.position = { map: 'safari', x: st.x, y: st.y, dir: 'up' };
          this.banner = { text: 'SAFARI ZONE', t: 1.6 };
          g.ui.toast('Safari started: 500 steps, 30 balls!');
        });
      });
      return true;
    }
    if (npc.safariExit) {
      sayLines(() => this.endSafari('You left the Safari Zone.'));
      return true;
    }
    if (npc.nameRater) {
      sayLines(() => {
        const items = g.state.party.map((m, i) => ({ label: displayName(m, SPECIES) + ' (Lv' + m.level + ')', value: i }));
        items.push({ label: 'Not now', value: -1 });
        g.ui.showMenu('Whose name shall I rate?', items, (v) => {
          if (v === null || v === -1) return;
          const mon = g.state.party[v];
          g.ui.showNameEntry('Nickname for ' + SPECIES[mon.speciesId].name + '?', mon.nickname || SPECIES[mon.speciesId].name, 12, (name) => {
            mon.nickname = name && name.trim() ? name.trim().slice(0, 12) : null;
            g.ui.say([(mon.nickname || SPECIES[mon.speciesId].name) + '... A fine name!'], null, npc.name);
          });
        });
      });
      return true;
    }
    return false;
  },

  endSafari(msg) {
    const g = this.game;
    g.state.session.safari = null;
    g.state.bag.safariball = 0;
    g.ui.say([msg], () => {
      const st = MAPS.fuchsia.start || { x: 10, y: 10 };
      this.loadMap('fuchsia');
      this.player.tx = st.x; this.player.ty = st.y;
      this.player.px = st.x * TILE; this.player.py = st.y * TILE;
      this.player.fx = st.x; this.player.fy = st.y;
      this.trail = [];
      g.state.story.position = { map: 'fuchsia', x: st.x, y: st.y, dir: 'down' };
      this.banner = { text: 'FUCHSIA CITY', t: 1.6 };
      g.audio.playMusic(this.map.music || 'route1-theme');
    });
  },

  // ---------- PC boxes ----------
  // Platinum PC box (UI v2): a 'pcbox' wallpaper window whose stored
  // Pokemon render as sprite cells (Game#spriteDataUrl, the same helper
  // the party/bag rows use — accessed here via this.game). Navigation
  // rows (box-switch, party deposit/withdraw lists, link, log off / back)
  // are full-width `wide` rows under the cell grid. All values returned
  // to the callbacks, and the deposit/withdraw/box-switch semantics, are
  // exactly as before; the current box + capacity stay in the title.
  openPc() {
    const g = this.game;
    const boxes = g.state.boxes;
    for (let i = 1; i <= BOX_COUNT; i++) if (!Array.isArray(boxes['box' + i])) boxes['box' + i] = [];
    const cur = g.state.currentBox || 'box1';
    const spriteRowHtml = (getMon) => (it) => {
      const mon = getMon(it);
      if (!mon) return '<span>' + it.label + '</span>';
      const url = (typeof g.spriteDataUrl === 'function') ? g.spriteDataUrl(mon.speciesId) : '';
      return '<img class="picon" src="' + url + '" alt=""><span>' + it.label + '</span>';
    };
    const boxRowHtml = spriteRowHtml((it) => {
      if (typeof it.value === 'string' && it.value.indexOf('wd:') === 0) return boxes[cur][parseInt(it.value.slice(3), 10)];
      if (typeof it.value === 'number' && it.value >= 0) return boxes[cur][it.value];
      return null;
    });
    const partyRowHtml = spriteRowHtml((it) => {
      if (typeof it.value === 'number' && it.value >= 0) return g.state.party[it.value];
      return null;
    });
    const withdrawMon = (iv) => {
      if (g.state.party.length >= 6) { g.ui.say(['Your party is full!']); return; }
      const mon = boxes[cur].splice(iv, 1)[0];
      if (!mon) return;
      g.state.party.push(mon);
      g.ui.toast('Withdrew ' + displayName(mon, SPECIES) + '.');
    };
    const mainItems = boxes[cur].map((m, i) => ({
      label: displayName(m, SPECIES) + ' Lv' + m.level, value: 'wd:' + i,
    }));
    mainItems.push(
      { label: 'Deposit', value: 'dep', wide: true },
      { label: 'Withdraw', value: 'wd', wide: true },
      { label: 'Change box', value: 'chg', wide: true },
      { label: 'Link Transfer (Bill\'s system)', value: 'link', wide: true },
      { label: 'Log off', value: 'off', wide: true },
    );
    g.ui.showMenu('PC — someone\'s PC (current: ' + cur.replace('box', 'Box ') + ', ' + boxes[cur].length + '/' + BOX_CAP + ')', mainItems, (v) => {
      if (typeof v === 'string' && v.indexOf('wd:') === 0) {
        // Box-screen shortcut: choosing a stored Pokemon's cell withdraws
        // it, with the same party-full guard as the Withdraw list below.
        withdrawMon(parseInt(v.slice(3), 10));
        return;
      }
      if (v === 'dep') {
        const items = g.state.party.map((m, i) => ({ label: displayName(m, SPECIES) + ' Lv' + m.level, value: i, disabled: g.state.party.length <= 1 }));
        items.push({ label: 'Back', value: -1, wide: true });
        g.ui.showMenu('Deposit which?', items, (iv) => {
          if (iv === null || iv === -1) return;
          const mon = g.state.party[iv];
          const chk = boxCheck(mon);
          if (!chk.ok) { g.ui.say([chk.line]); return; }
          if (boxes[cur].length >= BOX_CAP) { g.ui.say(['That box is full!']); return; }
          g.state.party.splice(iv, 1);
          mon.status = null;
          boxes[cur].push(mon);
          g.ui.toast('Deposited ' + displayName(mon, SPECIES) + '.');
        }, { menuClass: 'pcbox', rowHtml: partyRowHtml });
      } else if (v === 'wd') {
        const items = boxes[cur].map((m, i) => ({ label: displayName(m, SPECIES) + ' Lv' + m.level, value: i }));
        items.push({ label: 'Back', value: -1, wide: true });
        g.ui.showMenu('Withdraw which?', items, (iv) => {
          if (iv === null || iv === -1) return;
          withdrawMon(iv);
        }, { menuClass: 'pcbox', rowHtml: boxRowHtml });
      } else if (v === 'chg') {
        const items = [];
        for (let i = 1; i <= BOX_COUNT; i++) items.push({ label: 'Box ' + i + ' (' + boxes['box' + i].length + '/' + BOX_CAP + ')', value: 'box' + i, wide: true });
        g.ui.showMenu('Change to which box?', items, (iv) => {
          if (iv) { g.state.currentBox = iv; g.ui.toast('Current box: ' + iv.replace('box', 'Box ') + '.'); }
        }, { menuClass: 'pcbox' });
      } else if (v === 'link') {
        // Bill's Link Transfer: trade-evolution species evolve here —
        // the honest single-player resolution (WS7 design call, ADR-019).
        const cand = g.state.party.filter((m) => {
          const sp = SPECIES[m.speciesId];
          return sp && sp.evo && sp.evo.method === 'trade';
        });
        if (!cand.length) { g.ui.say(['No Pokemon here is waiting on a trade evolution.']); return; }
        const items = cand.map((m) => ({ label: displayName(m, SPECIES) + ' -> ' + SPECIES[SPECIES[m.speciesId].evo.to].name, value: m.monId }));
        items.push({ label: 'Back', value: null, wide: true });
        const linkRowHtml = spriteRowHtml((it) => cand.find((m) => m.monId === it.value) || null);
        g.ui.showMenu('Link Transfer which?', items, (iv) => {
          const mon = cand.find((m) => m.monId === iv);
          if (mon) this.evolveMon(mon);
        }, { menuClass: 'pcbox', rowHtml: linkRowHtml });
      }
    }, { menuClass: 'pcbox', rowHtml: boxRowHtml });
  },

  // ---------- mart ----------
  openMart(stock) {
    const g = this.game;
    g.ui.showMenu('Mart — $' + g.state.player.money, [
      { label: 'Buy', value: 'buy' }, { label: 'Sell', value: 'sell' }, { label: 'Leave', value: 'leave' },
    ], (v) => {
      if (v === 'buy') {
        const items = stock.filter((id) => ITEMS[id] && ITEMS[id].price > 0).map((id) => ({
          label: ITEMS[id].name + ' — $' + ITEMS[id].price + ' (own ' + (g.state.bag[id] || 0) + ')', value: id,
          disabled: g.state.player.money < ITEMS[id].price,
        }));
        items.push({ label: 'Back', value: null });
        g.ui.showMenu('Buy what?', items, (iv) => {
          if (!iv) return;
          g.state.player.money -= ITEMS[iv].price;
          g.state.bag[iv] = (g.state.bag[iv] || 0) + 1;
          g.audio.playSfx('dex-register');
          g.ui.toast('Bought ' + ITEMS[iv].name + '.');
          this.openMart(stock);
        });
      } else if (v === 'sell') {
        const items = Object.keys(g.state.bag).filter((id) => ITEMS[id] && ITEMS[id].price > 0 && g.state.bag[id] > 0)
          .map((id) => ({ label: ITEMS[id].name + ' x' + g.state.bag[id] + ' — sell $' + Math.floor(ITEMS[id].price / 2), value: id }));
        items.push({ label: 'Back', value: null });
        g.ui.showMenu('Sell what?', items, (iv) => {
          if (!iv) return;
          g.state.bag[iv]--;
          g.state.player.money += Math.floor(ITEMS[iv].price / 2);
          g.ui.toast('Sold ' + ITEMS[iv].name + '.');
          this.openMart(stock);
        });
      }
    });
  },

  // ---------- Game Corner slots ----------
  openSlots() {
    const g = this.game;
    const coins = g.state.bag.coin || 0;
    g.ui.showMenu('Slots — ' + coins + ' coins (7-7-7 pays 300, three of a kind 50, any pair 8)', [
      { label: 'Spin (1 coin)', value: 'spin', disabled: coins < 1 },
      { label: 'Buy 50 coins ($1000)', value: 'buy', disabled: g.state.player.money < 1000 },
      { label: 'Leave', value: 'leave' },
    ], (v) => {
      if (v === 'buy') {
        g.state.player.money -= 1000;
        g.state.bag.coin = (g.state.bag.coin || 0) + 50;
        this.openSlots();
        return;
      }
      if (v !== 'spin') return;
      g.state.bag.coin--;
      const syms = ['7', 'BAR', '♣', '♦', '♥', '♠'];
      const reel = [0, 0, 0].map(() => syms[Math.floor(g.rng.misc() * syms.length)]);
      let win = 0;
      if (reel[0] === '7' && reel[1] === '7' && reel[2] === '7') win = 300;
      else if (reel[0] === reel[1] && reel[1] === reel[2]) win = 50;
      else if (reel[0] === reel[1] || reel[1] === reel[2] || reel[0] === reel[2]) win = 8;
      if (win > 0) g.state.bag.coin += win;
      g.audio.playSfx(win > 0 ? 'dex-register' : 'menu-move');
      g.ui.say(['[ ' + reel.join(' | ') + ' ]' + (win > 0 ? ' — WINNER! +' + win + ' coins!' : ' — no luck this spin.')], () => this.openSlots());
    });
  },

  // ---------- evolution ----------
  evolveMon(mon, stoneId) {
    const g = this.game;
    const chk = evolutionCheck(mon);
    if (!chk.ok) { g.ui.say([chk.line]); return false; }
    const sp = SPECIES[mon.speciesId];
    let evo = null;
    if (stoneId) {
      const evos = sp.evos || (sp.evo ? [sp.evo] : []);
      evo = evos.find((e) => e.method === 'stone' && e.stone === stoneId) || null;
    } else {
      evo = sp.evo || (sp.evos ? sp.evos[0] : null);
    }
    if (!evo) return false;
    const fromName = displayName(mon, SPECIES);
    const to = SPECIES[evo.to];
    const ivs = mon.ivs || {};
    const oldMax = mon.maxHp;
    mon.speciesId = evo.to;
    mon.maxHp = hpValue(to.base.hp, mon.level, ivs.hp);
    if (mon.hp > 0) mon.hp = Math.min(mon.maxHp, mon.hp + (mon.maxHp - oldMax));
    mon.stats = {
      atk: statValue(to.base.atk, mon.level, ivs.atk), def: statValue(to.base.def, mon.level, ivs.def),
      spa: statValue(to.base.spa, mon.level, ivs.spa), spd: statValue(to.base.spd, mon.level, ivs.spd),
      spe: statValue(to.base.spe, mon.level, ivs.spe),
    };
    dexRegister(g.state.dex, 'caught', to.dexNo);
    g.audio.playSfx('levelup');
    g.ui.say(['What? ' + fromName + ' is evolving!', fromName + ' evolved into ' + to.name + '!']);
    return true;
  },

  // ---------- blackout ----------
  blackout() {
    const g = this.game;
    g.state.player.money = Math.floor(g.state.player.money / 2);
    g.ui.say(['You scurried to a Pokemon Center, protecting your exhausted team...'], () => {
      this.loadMap('center');
      this.player.tx = 4; this.player.ty = 3;
      this.player.px = 4 * TILE; this.player.py = 3 * TILE;
      this.player.fx = 4; this.player.fy = 3;
      this.trail = [];
      this.healParty(false);
      g.state.story.position = { map: 'center', x: 4, y: 3, dir: 'down' };
      g.ui.toast('Your Pokemon were healed. (Lost half your money.)');
    });
  },

  // ---------- world dressing ----------
  sysRenderWorld(r) {
    const g = this.game;
    const T = TILE;
    // Cut trees become clearings.
    if (this.fxState) {
      for (const k of this.fxState.cut) {
        const [cx, cy] = k.split(',').map(Number);
        const spr = g.tileSprite('path');
        if (spr) r.blit(spr, cx * T, cy * T);
      }
      // Boulders at their runtime positions.
      for (const b of this.fxState.boulders.values()) {
        const spr = g.tileSprite('rock');
        if (spr) r.blit(spr, b.x * T, b.y * T);
      }
    }
    // Item balls: the classic red-and-white sphere on the ground.
    if (this.map.items) {
      for (const b of this.map.items) {
        const flag = 'item_' + this.mapId + '_' + b.x + '_' + b.y;
        if (g.state.story.flags[flag]) continue;
        if ((b.item === 'helixfossil' || b.item === 'domefossil') && g.state.story.flags.fossil_taken) continue;
        const c = r.ctx;
        c.save();
        c.fillStyle = '#e84040';
        c.beginPath(); c.arc(b.x * T + 8, b.y * T + 8, 5, Math.PI, 0); c.fill();
        c.fillStyle = '#f8f8f0';
        c.beginPath(); c.arc(b.x * T + 8, b.y * T + 8, 5, 0, Math.PI); c.fill();
        c.fillStyle = '#202028';
        c.fillRect(b.x * T + 3, b.y * T + 7, 10, 2);
        c.restore();
      }
    }
    // Dark caves: gloom with a glow around the player until FLASH is used.
    if (this.map.dark && !(this.fxState && this.fxState.flashLit)) {
      const c = r.ctx;
      c.save();
      c.fillStyle = 'rgba(6,6,18,0.86)';
      c.fillRect(0, 0, this.w * T, this.h * T);
      c.fillStyle = 'rgba(255,240,180,0.12)';
      c.beginPath(); c.arc(this.player.px + 8, this.player.py + 8, 34, 0, Math.PI * 2); c.fill();
      c.restore();
    }
  },

  // ---------- objective (quest-driven HUD line) ----------
  sysObjective() {
    const g = this.game;
    const q = QUESTS.find((qq) => qq.flag && !g.state.story.flags[qq.flag]);
    if (q) return '▶ ' + q.text;
    const active = Object.keys(g.state.story.quests).find((k) => g.state.story.quests[k] === 'active');
    if (active && LEGENDARY_ARCS[active]) return '▶ Arc: ' + LEGENDARY_ARCS[active].title;
    return '▶ Explore Kanto';
  },
});


// ---- src/game/main.mjs ----
// main.mjs — Game root: owns loop, renderer, input, audio, UI, scenes, save.
// Scene flow: BOOT (legal card) -> TITLE -> INTRO -> OVERWORLD <-> BATTLE.
// Battle/overworld menus (Bag/Party/Dex/Save/Options) live here as UI states.


function nextSeed() {
  if (typeof globalThis !== 'undefined' && globalThis.__SEED__) return globalThis.__SEED__ >>> 0;
  return (Date.now() ^ (Math.random() * 1e9)) >>> 0;
}

const doc = (typeof document !== 'undefined') ? document : {
  createElement: (tag) => {
    if (tag === 'canvas') {
      return {
        width: 0, height: 0, style: {},
        getContext: () => new Proxy({}, {
          get: (t, p) => {
            if (p === 'canvas') return {};
            if (p === 'measureText') return () => ({ width: 10 });
            if (p === 'getImageData') return () => ({ data: [] });
            return () => {};
          },
          set: () => true,
        }),
      };
    }
    return { style: {}, appendChild() {}, addEventListener() {} };
  },
  getElementById: () => null,
  addEventListener() {},
};

class Game {
  constructor(canvas) {
    this.canvas = canvas || doc.createElement('canvas');
    this.renderer = new Renderer(this.canvas);
    this.input = new Input();
    this.audio = new AudioEngine();
    this.ui = new UI(this);
    this.scenes = new SceneStack(this);
    this.loop = new Loop(this);
    this.store = new SaveStore();
    this.state = freshState();
    this.rng = makeRngStreams(nextSeed());
    this.tileCache = buildArtTileCache(doc); // hand-authored tileset (art.mjs); void -> solid fill
    this.spriteCache = {};
    this._spriteUrlCache = {}; // species id -> battle-art data URL (toDataURL once per species)
    this._iconUrlCache = {};   // item id -> uiIcon data URL (toDataURL once per item)
    this.npcCache = {};
    this.skipIntroVeteran = false;
    this._lastAutosave = 0;
    this.layoutMode = 'portrait';
    this._animT = 0;      // ms clock for sprite-frame animation (idle blink, NPCs, water)
    this.guestMode = false; // set by the Trainer ID Terminal guest path
    this.authUser = null;   // Track B: logged-in username (null = guest / logged out)
  }

  tileKind(ch) { return TILE_CHARS[ch] || 'void'; }

  tileSprite(kind) { return tileSprite(this.tileCache, kind, this._animT); }

  buildSprites() {
    // Wave 3: real ART data replaces the forge placeholders (README wiring handoff).
    for (const id of Object.keys(SPECIES)) {
      this.spriteCache[id] = speciesBattleArt(doc, id, SPECIES[id]);
    }
    this.playerSprites = {
      down: ashFrames(doc, 'down'),
      up: ashFrames(doc, 'up'),
      left: ashFrames(doc, 'left'),
      right: ashFrames(doc, 'right'),
    };
    this._partnerHop = partnerHopFrames(doc);
    this.npcCache = {};
  }

  // Battle-art data URL for a species (party/bag menu <img class="picon">).
  // Cached per species id on the game object so toDataURL runs once.
  // Headless stub canvases have no toDataURL — returns '' there (guarded).
  spriteDataUrl(speciesId) {
    if (!this._spriteUrlCache) this._spriteUrlCache = {};
    if (speciesId in this._spriteUrlCache) return this._spriteUrlCache[speciesId];
    let url = '';
    try {
      const entry = this.spriteCache && this.spriteCache[speciesId];
      const cv = entry && (entry.front || entry);
      if (cv && typeof cv.toDataURL === 'function') url = cv.toDataURL();
    } catch (e) { url = ''; }
    this._spriteUrlCache[speciesId] = url;
    return url;
  }

  // Icon name for a bag item, or null when no authored icon art exists:
  // balls -> pokeball, potion-class medicine -> potion, badges -> badge.
  itemIconName(itemId) {
    const it = ITEMS[itemId];
    if (itemId === 'potion' || itemId === 'superpotion' || itemId === 'hyperpotion' ||
        itemId === 'maxpotion' || itemId === 'fullrestore') return 'potion';
    if ((it && it.pocket === 'balls') || itemId === 'pokeball') return 'pokeball';
    if (itemId && String(itemId).endsWith('badge')) return 'badge';
    return null;
  }

  // Item-icon data URL for bag rows (uiIcon canvases from art.mjs).
  // Cached per item id on the game object so toDataURL runs once.
  itemIconDataUrl(itemId) {
    if (!this._iconUrlCache) this._iconUrlCache = {};
    if (itemId in this._iconUrlCache) return this._iconUrlCache[itemId];
    let url = '';
    try {
      const iconName = this.itemIconName(itemId);
      if (iconName) {
        const cv = uiIcon(doc, iconName);
        if (cv && typeof cv.toDataURL === 'function') url = cv.toDataURL();
      }
    } catch (e) { url = ''; }
    this._iconUrlCache[itemId] = url;
    return url;
  }

  // Overworld Ash: 4-dir walk cycle while moving, 2-frame idle blink at rest.
  playerSprite(p) {
    const frames = this.playerSprites[p.dir] || this.playerSprites.down;
    if (p.moving) {
      const fi = 2 + (Math.floor((p.moveT / 200) * 4) % 4); // 4 walk frames per tile
      return frames[fi];
    }
    return frames[Math.floor(this._animT / 500) % 2]; // idle-1 / idle-2 blink
  }

  npcFrame(npc) {
    if (!this.npcCache[npc.name]) this.npcCache[npc.name] = npcFrames(doc, npc);
    const f = this.npcCache[npc.name];
    return f[Math.floor(this._animT / 600) % 2]; // idle-1 / idle-2
  }

  partnerFrame() {
    if (!this._partnerHop) return this.spriteCache.partner.front;
    return this._partnerHop[Math.floor(this._animT / 280) % 2]; // hop-1 / hop-2
  }

  // Canvas 2D helpers used by scenes.
  ctx2dfill(color, x, y, w, h) {
    const c = this.renderer.ctx;
    c.fillStyle = color; c.fillRect(x, y, w, h);
  }
  ctx2drect(x, y, w, h, color) { this.ctx2dfill(color, x, y, w, h); }
  ctx2dcircle(x, y, rad, color) {
    const c = this.renderer.ctx;
    c.fillStyle = color;
    c.beginPath(); c.arc(x, y, rad, 0, Math.PI * 2); c.fill();
  }

  boot() {
    this.ui.init();
    // UI v2.1 (defect 1): kick off the Platinum faces NOW so the first
    // dialogue/menu paints in Galmuri, not in the fallback stack. The faces
    // are same-document data URIs (self-hosted in assets/fonts/, embedded by
    // scripts/build.mjs) and the production CSP allows them via
    // `font-src 'self' data:` — if either ever regresses, the deployed-
    // flavor QA gate (ashs-journey-qa/shoot4.mjs) fails loudly on
    // document.fonts.check instead of silently shipping a fallback again.
    try {
      if (typeof document !== 'undefined' && document.fonts && document.fonts.load) {
        document.fonts.load('16px "PtGalmuri"', 'ASH');
        document.fonts.load('700 16px "PtGalmuri"', 'ASH');
        document.fonts.load('16px "PtGothic"', 'ASH');
      }
    } catch (e) { /* headless / stub DOM */ }
    // Track B: auth health probe (503 banner) + sync dot. Guest target: no-ops.
    AUTH.init(this);
    SYNC.init(this);
    this.input.bindKeyboard();
    this.buildSprites();
    this.applyLayout();
    if (typeof window !== 'undefined' && window.addEventListener) {
      window.addEventListener('resize', () => this.applyLayout());
    }
    // P1/A6: tap the canvas to advance (title + tap-to-advance dialogue).
    if (this.canvas && this.canvas.addEventListener) {
      this.canvas.addEventListener('pointerdown', (e) => {
        e.preventDefault();
        this.audio.unlock();
        this.input.inject('a');
      });
    }
    // P1/I4: honor prefers-reduced-motion on first boot.
    try {
      if (typeof window !== 'undefined' && window.matchMedia &&
          window.matchMedia('(prefers-reduced-motion: reduce)').matches &&
          !this.store.exists()) {
        this.state.settings.reducedMotion = true;
      }
    } catch (e) { /* headless / no matchMedia */ }
    this.loop.onAutosave = () => {
      // P1/H2: visibilitychange autosaves — never mid-battle-turn.
      const top = this.scenes.top;
      const midResolve = !!(top && top.state === 'resolve' && top.foe);
      if (!midResolve) this.saveGame(true);
      SYNC.onHidden(this); // Track B: best-effort cloud flush on tab hide
    };
    this.loop.bindVisibility(() => { /* sim halts via rAF freeze; autosave queued above */ });
    this.audio.applySettings(this.state.settings);
    // Gameplay Designer co-design note (C7): the tutorial catch gate must be
    // robust to a Spearow-class foe — the script is deterministic (balance-seat
    // gate), never luck. Recorded here so the gate lives with the flow.
    this.scenes.push(new BootScene());
    this.loop.start();
  }

  applyLayout() {
    const r = this.renderer;
    if (typeof window === 'undefined') {
      r.resize(256, 192, 256, 192);
      this.layoutMode = 'desktop';
      return;
    }
    const w = window.innerWidth, h = window.innerHeight;
    const fine = window.matchMedia && window.matchMedia('(pointer: fine)').matches;
    // D3: desktop = fine pointer at >=700px, OR a laptop-class width regardless of
    // what the browser reports (some browsers/headless never match
    // '(pointer: fine)' — without the width fallback they fell into the phone
    // landscape path and rendered stretched with touch controls on a laptop).
    // Coarse-pointer wide tablets still land here and get controls back via the
    // (pointer:coarse) CSS override.
    if (w >= 700 && (fine || w >= 1024)) {
      this.layoutMode = 'desktop';
      // D3: aspect-locked 16:9 canvas. The old h*0.62 cap stretched the buffer
      // on 1280x800-class viewports (1120x496 CSS over a 384x216 backing store).
      // Height now reserves room for the hint card instead of a fixed fraction.
      const cssW0 = Math.min(1120, w * 0.9);
      let cw = cssW0, ch = cssW0 * 9 / 16;
      const maxH = Math.min(630, Math.max(240, h - 140));
      if (ch > maxH) { ch = maxH; cw = ch * 16 / 9; }
      r.resize(384, 216, Math.round(cw), Math.round(ch));
      document.body.classList.add('desktop');
    } else if (w > h) {
      this.layoutMode = 'landscape';
      // D3: aspect-locked 4:3 (was w*0.72 x h — stretched on every landscape phone).
      const lw = Math.min(w * 0.72, h * 4 / 3);
      r.resize(256, 192, Math.round(lw), Math.round(lw * 3 / 4));
      document.body.classList.remove('desktop');
    } else {
      this.layoutMode = 'portrait';
      // Portrait: canvas takes 58% of the height (was 45% — left a dead
      // void below and shrank the game's subject). Logical stays 256x256.
      r.resize(256, 256, w, h * 0.58);
      document.body.classList.remove('desktop');
    }
    // P1/K2: landscape gets the right-edge command rail (CSS re-rails the HUD strip).
    document.body.classList.toggle('landscape', this.layoutMode === 'landscape');
    document.body.classList.toggle('flip', !!this.state.settings.controlsFlip);
    // P1/K3 + I2: desktop hint card; show-touch toggle honored on hybrids.
    document.body.classList.toggle('showtouch', !!this.state.settings.showTouch);
    // Headless harness stubs document without documentElement — guard it.
    if (document.documentElement) document.documentElement.style.setProperty('--hudscale', this.state.settings.hudScale || 1);
    this.ui.showHintCard(this.layoutMode === 'desktop');
    // UI v2.1: the frame layer tracks the canvas box on every layout pass
    // (boot, resize, orientation, fullscreen) — not just the UI tick throttle.
    if (this.ui._syncChipAnchor) this.ui._syncChipAnchor();
  }

  update(dt) {
    this._animT += dt * 1000;
    // Global M-key mute toggle (options spec §4.8: "Mute (M key too)"). Persists.
    if (this.input.wasPressed('mute')) this.toggleMute();
    // P1/I3: F = fullscreen toggle on #stage (KEYMAP defines it; now consumed).
    if (this.input.wasPressed('fullscreen') && typeof document !== 'undefined') {
      const stage = document.getElementById('stage');
      if (stage) {
        if (document.fullscreenElement) document.exitFullscreen();
        else if (stage.requestFullscreen) stage.requestFullscreen();
      }
    }
    this.ui.update(dt);
    SYNC.tick(this); // Track B: idle flush (60s) + deferred conflict sheet. Guest: no-op.
    this.scenes.update(dt);
    if (this.processQueues) this.processQueues(); // WS6/WS9: learn + evolution prompts
    if (this.checkDiploma) this.checkDiploma(); // WS7: the 151 payoff
  }

  toggleMute() {
    const s = this.state.settings;
    s.mute = !s.mute;
    this.audio.setMuted(s.mute);
    this.ui.toast(s.mute ? 'Muted.' : 'Sound on.');
    this.saveGame(true);
  }

  render(alpha) {
    this.scenes.render(this.renderer, alpha);
  }

  // ---- game flow ----
  // P0/B1: title menu routes through the Trainer ID Terminal.
  // Track B (vercel): full LOG IN / REGISTER / GUEST panel (auth.mjs).
  // Guest target: the stub keeps Track-A behavior (guest only, zero network).
  openLogin(mode) {
    this._loginMode = mode;
    this.ui.showLogin((choice, data) => {
      if (choice === 'login') {
        this.guestMode = false;
        this.authUser = (data && data.username) || null;
        AUTH.user = this.authUser;
        this.ui.hideGuestBanner();
        this.onLoggedIn(mode);
        return;
      }
      // 'guest' — also the only path in the guest target and the headless harness
      this.guestMode = true;
      this.authUser = null;
      AUTH.user = null;
      if (this._loginMode === 'continue') this.continueGame();
      else this.newGame();
    });
  }

  // Track B: post-login — pull cloud meta, merge (claim/conflict/newest-wins),
  // then load the resolved save or start fresh.
  onLoggedIn(mode) {
    const name = this.authUser || 'trainer';
    this.ui.toast('Welcome back, ' + name + '!'); // toast = textContent (C12-safe)
    SYNC.runLoginMerge(this, mode, (res) => {
      if (!res) return;
      if (res.load === 'state' && res.state) {
        this.state = res.state;
        this.audio.applySettings(this.state.settings);
        this.scenes.replace(new OverworldScene());
        this.ui.toast('Save loaded.');
      } else if (res.load === 'new') {
        this.newGame();
      } else {
        // fallback (offline / unavailable / expired): play on this device.
        if (mode === 'continue') this.continueGame();
        else this.newGame();
      }
    });
  }

  quitToTitle(saveIt) {
    if (saveIt !== false) this.saveGame(true);
    this.ui.hideGuestBanner();
    this.scenes.replace(new BootScene());
  }

  newGame() {
    // Settings are player preferences, not save data: options chosen on the
    // title screen (text speed, battle style, mute...) survive a new game.
    const keepSettings = this.state && this.state.settings;
    this.state = freshState();
    if (keepSettings) this.state.settings = keepSettings;
    this.state.player.name = 'ASH';
    this.rng = makeRngStreams(nextSeed());
    this.skipIntroVeteran = this.store.exists();
    this.scenes.replace(new IntroScene());
  }

  continueGame() {
    const res = this.store.load();
    if (!res.ok) {
      this.ui.toast('Save data invalid (' + res.reason + '). Starting fresh is safest.');
      return;
    }
    this.state = res.data;
    this.audio.applySettings(this.state.settings);
    this.scenes.replace(new OverworldScene());
    this.ui.toast('Welcome back, ' + this.state.player.name + '!');
  }

  startOverworld(opts) {
    this.scenes.replace(new OverworldScene());
    if (this.guestMode) this.ui.showGuestBanner(); // UI v2.1: no-op (banner retired; notice lives in the terminal guest pane)
    // D2: fresh runs open on the Chapter 1 title card (anime spine, ADR-015).
    if (opts && typeof opts.chapterCard === 'number') {
      this.ui.showChapterCard(CHAPTERS[opts.chapterCard]);
    }
  }

  saveGame(quiet) {
    // Track B: logged-in saves go to the local cloud-cache + background queue
    // (SYNC) — the game never waits on network. Guest path is byte-identical.
    if (AUTH.user) {
      const res = SYNC.saveLocal(this);
      if (!quiet || !res.ok) {
        if (res.ok) { this.ui.toast('Game saved. (' + Math.round(res.bytes / 1024) + ' KB)'); this.audio.playSfx('save-confirm'); }
        else this.ui.toast('Save failed: ' + res.reason);
      }
      SYNC.afterLocalSave(this);
      return res;
    }
    const res = this.store.save(this.state);
    if (!quiet || !res.ok) {
      if (res.ok) { this.ui.toast('Game saved. (' + Math.round(res.bytes / 1024) + ' KB)'); this.audio.playSfx('save-confirm'); }
      else this.ui.toast('Save failed: ' + res.reason);
    }
    return res;
  }

  autosave(reason) {
    if (this.state.settings.autosave === false) return; // P1/I5: autosave toggle
    const now = Date.now();
    if (now - this._lastAutosave < 5000) return; // 5s throttle floor
    this._lastAutosave = now;
    this.saveGame(true);
  }

  // ---- menus (UI states, no scene reload) ----
  openBag() {
    const g = this;
    const items = [];
    // P1/G4: pocket tabs as group headers (44px rows, description in the label).
    for (const pocket of POCKETS) {
      const inPocket = Object.keys(ITEMS).filter((id) => ITEMS[id].pocket === pocket && (g.state.bag[id] || 0) > 0);
      if (!inPocket.length) continue;
      items.push({ label: '— ' + pocket + ' —', value: null, disabled: true, band: true });
      for (const id of inPocket) {
        const hint = id === 'potion' ? ' (heals 20 HP — uses your turn in battle)' : '';
        items.push({ label: ITEMS[id].name + ' x' + g.state.bag[id] + hint, value: id });
      }
    }
    if (!items.length) items.push({ label: '(empty)', value: null, disabled: true });
    items.push({ label: 'Close', value: 'close' });
    // Bag rows carry the item's authored icon (uiIcon -> data URL, cached
    // per item id) where art exists; headers/Close stay plain text.
    const bagRowHtml = (it) => {
      if (!it.value || it.value === 'close') return '<span>' + it.label + '</span>';
      const url = g.itemIconDataUrl(it.value);
      // Emit the icon whenever authored icon art exists for the item —
      // in the browser url is its data URL; headless stub canvases have
      // no toDataURL (url ''), but the row still carries the <img>.
      let hasIcon = !!url;
      if (!hasIcon) {
        try {
          const iconName = g.itemIconName(it.value);
          hasIcon = !!(iconName && uiIcon(doc, iconName));
        } catch (e) { hasIcon = false; }
      }
      const img = hasIcon ? '<img class="picon" src="' + url + '" alt="">' : '';
      return img + '<span>' + it.label + '</span>';
    };
    g.ui.showMenu('Bag', items, (v) => {
      if (!v || v === 'close') return;
      if (v === 'potion') {
        const targets = g.state.party.map((m, i) => ({
          label: displayName(m, SPECIES) + ' ' + m.hp + '/' + m.maxHp, value: i,
          disabled: m.hp <= 0 || m.hp >= m.maxHp,
        }));
        targets.push({ label: 'Back', value: -1 });
        const targetRowHtml = (it) => {
          if (it.value === -1 || it.value === null) return '<span>' + it.label + '</span>';
          const m = g.state.party[it.value];
          if (!m) return '<span>' + it.label + '</span>';
          return '<img class="picon" src="' + g.spriteDataUrl(m.speciesId) + '" alt=""><span>' + it.label + '</span>';
        };
        g.ui.showMenu('Use Potion on...', targets, (t) => {
          if (t === null || t === -1) { g.openBag(); return; }
          const m = g.state.party[t];
          g.state.bag.potion--;
          m.hp = Math.min(m.maxHp, m.hp + 20);
          g.audio.playSfx('heal');
          g.ui.toast(displayName(m, SPECIES) + ' recovered 20 HP!');
        }, { rowHtml: targetRowHtml });
      } else if (g.useBagItem) {
        g.useBagItem(v); // WS9: full item-use system (main-systems.mjs)
      }
    }, { rowHtml: bagRowHtml });
  }

  openParty() {
    const g = this;
    // P1/G1: rows carry the species battle-art sprite, an HP mini-bar +
    // numbers, status chip, and a PARTNER text chip for the partner.
    const rowHtml = (it) => {
      // UI v2.1 (defect 3): every party plate leads with its Poke Ball slot
      // marker, Platinum-style — filled rows and empty slots alike.
      const ball = '<img class="pball" src="' + g.itemIconDataUrl('pokeball') + '" alt="">';
      if (it.value === -1) return ball + '<span class="emptyslot">Empty slot</span>';
      if (it.value === 'close') return '<span>' + it.label + '</span>';
      const m = g.state.party[it.value];
      if (!m) return '<span>' + it.label + '</span>';
      const pct = Math.max(0, Math.round((m.hp / m.maxHp) * 100));
      const col = pct > 50 ? '#58c94f' : pct > 25 ? '#e8c832' : '#e84040';
      const badge = m.speciesId === 'partner' ? '<span class="pbadge">PARTNER</span>' : '';
      const st = m.status ? '<span class="pstat">' + m.status.toUpperCase().slice(0, 3) + '</span>' : '';
      return ball + '<img class="picon" src="' + g.spriteDataUrl(m.speciesId) + '" alt="">'
        + '<span><b>' + displayName(m, SPECIES) + '</b> Lv' + m.level + badge + '</span>'
        + '<span class="phpbar"><i style="width:' + pct + '%;background:' + col + '"></i></span>'
        + '<span>' + m.hp + '/' + m.maxHp + '</span>' + st;
    };
    const items = g.state.party.map((m, i) => {
      return { label: displayName(m, SPECIES) + ' Lv' + m.level + '  ' + m.hp + '/' + m.maxHp, value: i };
    });
    for (let i = g.state.party.length; i < 6; i++) items.push({ label: 'Empty', value: -1, disabled: true });
    items.push({ label: 'Close', value: 'close', closeRow: true });
    // Platinum tabbed summary (UI v2): INFO / STATUS / MOVES, composed only
    // from real mon/species/move data. The mon object carries `xp` (total
    // XP for its level, set by makeMon and level-ups); there is no stored
    // next-level figure on the mon, so INFO shows that total and never a
    // derived or invented next-level number.
    const sumRow = (k, val) => '<div class="sumrow"><span>' + k + '</span><b>' + val + '</b></div>';
    const summaryData = (m) => {
      const sp = SPECIES[m.speciesId];
      const xpVal = (typeof m.xp === 'number') ? m.xp : ((typeof m.exp === 'number') ? m.exp : null);
      let info = '<div class="sumhead"><img class="sumsprite" src="' + g.spriteDataUrl(m.speciesId) + '" alt="">'
        + '<div><div class="sumname">' + displayName(m, SPECIES) + '</div>'
        + '<div class="sumsub">No. ' + sp.dexNo + ' · ' + sp.types.join(' / ') + '</div></div></div>';
      if (m.ot !== undefined && m.ot !== null && m.ot !== '') info += sumRow('OT', m.ot);
      info += sumRow('Level', m.level);
      info += sumRow('HP', m.hp + '/' + m.maxHp);
      if (xpVal !== null) info += sumRow('EXP', xpVal);
      if (sp.flavor) info += '<div class="sumflavor">' + sp.flavor + '</div>';
      let statusBody = '';
      statusBody += sumRow('ATK', m.stats.atk);
      statusBody += sumRow('DEF', m.stats.def);
      statusBody += sumRow('SPA', m.stats.spa);
      statusBody += sumRow('SPD', m.stats.spd);
      statusBody += sumRow('SPE', m.stats.spe);
      statusBody += sumRow('Status', m.status ? m.status : 'None');
      let movesBody = '';
      for (const mm of (m.moves || [])) {
        const mv = MOVES[mm.id];
        if (!mv) {
          movesBody += '<div class="sum-move"><span class="sum-mvname">' + mm.id + '</span>'
            + '<span class="sum-mvmeta">PP ' + mm.pp + '/' + mm.maxPp + '</span></div>';
          continue;
        }
        movesBody += '<div class="sum-move"><span class="sum-mvname">' + mv.name + '</span>'
          + typePill(mv.type)
          + '<span class="sum-mvmeta">Pow ' + (mv.power ? mv.power : '—')
          + ' · Acc ' + ((mv.acc !== undefined && mv.acc !== null) ? mv.acc : '—')
          + ' · PP ' + mm.pp + '/' + mm.maxPp + ' · ' + mv.cat + '</span></div>';
      }
      if (!movesBody) movesBody = '<div class="sumflavor">No moves known.</div>';
      return {
        name: displayName(m, SPECIES),
        tabs: [
          { id: 'info', label: 'INFO', bodyHtml: info },
          { id: 'status', label: 'STATUS', bodyHtml: statusBody },
          { id: 'moves', label: 'MOVES', bodyHtml: movesBody },
        ],
      };
    };
    // Per-Pokemon action submenu: a standard Platinum window (no menuClass).
    // Closing the summary panel reopens this submenu, so B backs out one
    // level like Platinum instead of dropping back to the overworld.
    const openMonMenu = (monIndex) => {
      const m = g.state.party[monIndex];
      if (!m) return;
      const fieldMoves = (m.moves || []).filter((x) => ['cut', 'fly', 'surf', 'strength', 'flash'].includes(x.id));
      const rows = [{ label: 'Summary', value: 'summary' }];
      if (fieldMoves.length) rows.push({ label: 'Field moves', value: 'field' });
      rows.push({ label: 'Close', value: 'close' });
      g.ui.showMenu(displayName(m, SPECIES), rows, (a) => {
        if (a === 'field' && g.openFieldMove) { g.openFieldMove(m); return; }
        if (a === 'summary') {
          g.ui.showSummary(summaryData(m), () => openMonMenu(monIndex));
        }
      });
    };
    g.ui.showMenu('Party', items, (v) => {
      if (v === null || v === 'close' || v === -1) return;
      openMonMenu(v);
    }, { rowHtml, menuClass: 'plate-full' });
  }

  openDex(filter) {
    const g = this;
    filter = filter || {};
    const caught = dexCaughtCount(g.state.dex);
    const matchSpecies = (id) => {
      const sp = SPECIES[id];
      const c = !!g.state.dex.caught[sp.dexNo], s = !!g.state.dex.seen[sp.dexNo];
      if (filter.status === 'caught' && !c) return false;
      if (filter.status === 'seen' && !(s && !c)) return false;
      if (filter.status === 'unseen' && (s || c)) return false;
      if (filter.type && !sp.types.includes(filter.type)) return false;
      if (filter.q && sp.name.toLowerCase().indexOf(filter.q.toLowerCase()) < 0) return false;
      return true;
    };
    const items = Object.keys(SPECIES).filter((id) => id !== 'partner' && matchSpecies(id)).map((id) => {
      const sp = SPECIES[id];
      const c = g.state.dex.caught[sp.dexNo], s = g.state.dex.seen[sp.dexNo];
      const mark = c ? '[CAUGHT]' : (s ? '[SEEN]' : '[???]');
      return { label: 'No.' + sp.dexNo + ' ' + (c || s ? sp.name : '???') + ' ' + mark, value: id };
    });
    const fdesc = (filter.q ? ' q=' + filter.q : '') + (filter.type ? ' ' + filter.type : '') + (filter.status ? ' ' + filter.status : '');
    items.unshift({ label: 'Caught ' + caught + ' / ' + DEX_TOTAL + ' (tracked)', value: null, disabled: true });
    items.unshift({ label: "Prof. Hawthorn's rating", value: 'rating' });
    items.unshift({ label: 'Search / Filter' + (fdesc ? ':' + fdesc : ''), value: 'filter' });
    items.unshift({ label: 'Areas — caught per area', value: 'areas' });
    // D2: arc progression surfaced in the Dex — current chapter header row.
    const curCh = chapterOf((g.state.story.chapter || 0) + 1);
    items.unshift({ label: 'Journey — Ch.' + curCh.n + ' · ' + curCh.title, value: null, disabled: true });
    if (!items.length) items.push({ label: '(no matches)', value: null, disabled: true });
    items.push({ label: 'Close', value: 'close' });
    g.ui.showMenu('Pokedex', items, (v) => {
      if (!v || v === 'close') return;
      if (v === 'rating') { g.ui.say([g.oakRating()], () => g.openDex(filter), 'Prof. Hawthorn'); return; }
      if (v === 'filter') { g.openDexFilter(filter); return; }
      if (v === 'areas') { g.openDexAreas(); return; }
      const sp = SPECIES[v];
      const c = g.state.dex.caught[sp.dexNo], s = g.state.dex.seen[sp.dexNo];
      if (!c && !s) { g.openDex(filter); return; }
      g.ui.say([
        'No.' + sp.dexNo + '  ' + sp.name + '  ' + sp.types.join('/'),
        sp.flavor,
        'Status: ' + (c ? 'CAUGHT' : 'SEEN'),
      ], () => g.openDex(filter), 'Dex');
    });
  }

  // P1/G3: dex filter submenu — status, type, and name search (reuses the A-Z grid).
  openDexFilter(filter) {
    const g = this;
    const types = [...new Set(Object.keys(SPECIES).flatMap((id) => SPECIES[id].types))].sort();
    g.ui.showMenu('Filter: status', [
      { label: 'All', value: 'all' },
      { label: 'Caught', value: 'caught' },
      { label: 'Seen', value: 'seen' },
      { label: 'Unseen', value: 'unseen' },
      { label: 'Back', value: 'back' },
    ], (st) => {
      if (st === 'back' || st === null) { g.openDex(filter); return; }
      const f2 = Object.assign({}, filter, { status: st === 'all' ? null : st });
      const titems = [{ label: 'All types', value: null }].concat(types.map((t) => ({ label: t, value: t })));
      titems.push({ label: 'Back', value: 'back' });
      g.ui.showMenu('Filter: type', titems, (tp) => {
        if (tp === 'back' || tp === null) { g.openDex(filter); return; }
        const f3 = Object.assign({}, f2, { type: tp });
        g.ui.showNameEntry('Search the Dex (blank = all)', '', 8, (q) => {
          f3.q = q || null;
          g.openDex(f3);
        });
      });
    });
  }

  // D2: Journey menu — the anime-chronology spine (ADR-015). Playable chapters
  // open a detail card; locked chapters and the BONUS shelf are honest
  // disabled rows (no fake content, no "coming soon" placeholders).
  openJourney() {
    const g = this;
    const cur = g.state.story.chapter || 0; // 0-based chapter index
    const items = [];
    items.push({ label: 'Quest Log — the road so far', value: 'quests' });
    items.push({ label: 'Regions — the journey chain', value: 'regions' });
    items.push({ label: '— ACT I: THE BEGINNING (v1) —', value: null, disabled: true });
    for (const ch of CHAPTERS) {
      if (ch.scope === 'playable') {
        const isCur = (ch.n - 1) === cur;
        items.push({
          label: (isCur ? '\u25b8 ' : '  ') + 'Ch.' + ch.n + ' — ' + ch.title + (isCur ? ' (now)' : ''),
          value: 'ch' + ch.n,
        });
      } else {
        items.push({
          label: 'Ch.' + ch.n + ' — ' + ch.title + ' · locked (future act)',
          value: null, disabled: true,
        });
      }
    }
    items.push({ label: '— BONUS SHELF (non-canon, not on the spine) —', value: null, disabled: true });
    for (const b of BONUS_SHELF) {
      items.push({ label: b, value: null, disabled: true });
    }
    items.push({ label: 'Close', value: 'close' });
    g.ui.showMenu('Journey', items, (v) => {
      if (!v || v === 'close') return;
      if (v === 'quests') { g.openQuestLog(); return; }
      if (v === 'regions') { g.openRegions(); return; }
      const ch = CHAPTERS.find((c) => 'ch' + c.n === v);
      if (ch) {
        g.ui.say([
          'CHAPTER ' + ch.n + ' — ACT ' + ch.act,
          ch.title,
          ch.arc,
          'Anime: ' + ch.anime,
          ch.movies.length ? 'Special events: ' + ch.movies.join(' · ') : '',
        ], () => g.openJourney(), 'Journey');
      }
    });
  }

  // P1/G3: Areas tab — per-area "caught n/m" checklists (B2W2 Habitat pattern).
  openDexAreas() {
    const g = this;
    const items = Object.keys(MAPS).filter((id) => MAPS[id].encounters).map((id) => {
      const map = MAPS[id];
      const species = [...new Set(map.encounters.table.map((e) => e.species))];
      const n = species.filter((s) => g.state.dex.caught[SPECIES[s].dexNo]).length;
      return { label: map.name + ' — ' + n + '/' + species.length + ' caught', value: id };
    });
    items.push({ label: 'Back', value: 'back' });
    g.ui.showMenu('Dex — Areas', items, (v) => {
      if (!v || v === 'back') { g.openDex(); return; }
      const map = MAPS[v];
      const rows = map.encounters.table.map((e) => {
        const sp = SPECIES[e.species];
        const c = g.state.dex.caught[sp.dexNo], s = g.state.dex.seen[sp.dexNo];
        return { label: (c || s ? sp.name : '???') + '  Lv' + e.min + '-' + e.max + (c ? ' [CAUGHT]' : s ? ' [SEEN]' : ''), value: null, disabled: true };
      });
      rows.push({ label: 'Back', value: 'back' });
      g.ui.showMenu(map.name, rows, () => g.openDexAreas());
    });
  }

  openSave() {
    const g = this;
    // Track B: logged-in players get the cloud slot list (3 slots + sync state).
    if (AUTH.user) { g.openSaveCloud(); return; }
    const caught = dexCaughtCount(g.state.dex);
    const badges = g.state.badges.kanto.length;
    const mins = Math.floor((g.state.player.playtimeSec || 0) / 60);
    const when = g.state.meta.updatedAt ? new Date(g.state.meta.updatedAt).toLocaleString() : 'never';
    g.ui.showMenu('Save', [
      { label: g.state.meta.location + ' · ' + mins + 'm · ' + badges + ' badges · Dex ' + caught, value: null, disabled: true },
      { label: 'Last saved: ' + when, value: null, disabled: true },
      { label: 'Sync: guest-local (Track B: cloud)', value: null, disabled: true },
      { label: 'Save now', value: 'save' },
      { label: 'Close', value: 'close' },
    ], (v) => {
      if (v === 'save') g.saveGame(false);
    }, { menuClass: 'syswin' });
  }

  // Track B: cloud slot picker (labels are formatted numbers/dates only —
  // no player strings, so the menu's innerHTML path is safe here).
  openSaveCloud() {
    const g = this;
    const slots = SYNC.getSlots();
    const items = [{ label: 'Cloud saves — pick a slot', value: null, disabled: true }];
    for (const s of slots) {
      const h = Math.floor((s.playtimeSec || 0) / 3600);
      const m = Math.floor(((s.playtimeSec || 0) % 3600) / 60);
      const st = s.pending ? 'Sync pending' : (s.cloudMeta || s.hasLocal) ? 'Synced' : 'Empty';
      items.push({
        label: (s.active ? '▶ ' : '') + 'Slot ' + s.slot + ' — ' + h + 'h ' + (m < 10 ? '0' + m : '' + m) +
          'm · ' + s.badgeCount + ' badges · ' + st,
        value: 'slot:' + s.slot,
      });
    }
    items.push({ label: 'Save now', value: 'save' });
    items.push({ label: 'Sync now', value: 'sync' });
    items.push({ label: 'Close', value: 'close' });
    g.ui.showMenu('Save', items, (v) => {
      if (!v || v === 'close') return;
      if (v === 'save') g.saveGame(false);
      else if (v === 'sync') SYNC.syncNow(g, true);
      else if (v.indexOf('slot:') === 0) {
        SYNC.setActiveSlot(parseInt(v.slice(5), 10));
        g.ui.toast('Slot ' + v.slice(5) + ' selected.');
        g.openSave();
      }
    }, { menuClass: 'syswin' });
  }

  openOptions() {
    const g = this;
    const s = g.state.settings;
    const yn = (b) => b ? 'ON' : 'OFF';
    const rows = [
      { label: 'Text speed: ' + s.textSpeed, value: 'text' },
      { label: 'Mute: ' + yn(s.mute), value: 'mute' },
      { label: 'Music volume: ' + Math.round(s.musicVol * 100) + '%', value: 'music' },
      { label: 'SFX volume: ' + Math.round(s.sfxVol * 100) + '%', value: 'sfx' },
      { label: 'Battle animations: ' + yn(s.battleAnims), value: 'banim' },
      { label: 'Battle style: ' + (s.battleStyle === 'classic' ? 'CLASSIC (turns)' : 'REAL-TIME'), value: 'bstyle' },
      { label: 'Screen shake: ' + yn(s.shake), value: 'shake' },
      { label: 'Vibration: ' + yn(s.vibration), value: 'vib' },
      { label: 'Autosave: ' + yn(s.autosave), value: 'asave' },
      { label: 'Reduced motion: ' + yn(s.reducedMotion), value: 'rmotion' },
      { label: 'Flip controls: ' + yn(s.controlsFlip), value: 'flip' },
      { label: 'Show touch controls: ' + yn(s.showTouch), value: 'showtouch' },
      { label: 'HUD scale: ' + Math.round(s.hudScale * 100) + '%', value: 'hudscale' },
      { label: 'Legal / credits', value: 'legal' },
    ];
    // Track B: account surface (wireframes §10). Labels are static — the
    // username itself is only ever rendered via textContent (AppSec C12).
    if (g.authUser) {
      rows.push({ label: 'Account', value: 'account' });
      rows.push({ label: 'Sync now', value: 'syncnow' });
    }
    rows.push(
      { label: 'Erase save', value: 'erase' },
      { label: 'Close', value: 'close' },
    );
    g.ui.showMenu('Options', rows, (v) => {
      if (v === 'text') {
        const order = ['slow', 'normal', 'fast', 'instant'];
        s.textSpeed = order[(order.indexOf(s.textSpeed) + 1) % order.length];
      } else if (v === 'mute') { s.mute = !s.mute; g.audio.setMuted(s.mute); }
      else if (v === 'music') { s.musicVol = s.musicVol >= 0.99 ? 0 : Math.round((s.musicVol + 0.1) * 10) / 10; g.audio.setMusicVolume(s.musicVol); }
      else if (v === 'sfx') { s.sfxVol = s.sfxVol >= 0.99 ? 0 : Math.round((s.sfxVol + 0.1) * 10) / 10; g.audio.setSfxVolume(s.sfxVol); }
      else if (v === 'banim') s.battleAnims = !s.battleAnims;
      else if (v === 'bstyle') { s.battleStyle = s.battleStyle === 'classic' ? 'rt' : 'classic'; g.ui.toast('Battle style: ' + (s.battleStyle === 'classic' ? 'Classic turns' : 'Real-time')); }
      else if (v === 'shake') s.shake = !s.shake;
      else if (v === 'vib') s.vibration = !s.vibration;
      else if (v === 'asave') s.autosave = !s.autosave;
      else if (v === 'rmotion') { s.reducedMotion = !s.reducedMotion; g.audio.setReducedMotion(s.reducedMotion); }
      else if (v === 'flip') { s.controlsFlip = !s.controlsFlip; g.applyLayout(); }
      else if (v === 'showtouch') {
        s.showTouch = !s.showTouch;
        if (typeof document !== 'undefined') document.body.classList.toggle('showtouch', !!s.showTouch);
      }
      else if (v === 'hudscale') {
        // P1/I2: HUD scale row (the setting existed with no UI).
        s.hudScale = s.hudScale >= 1.5 ? 1 : Math.round((s.hudScale + 0.25) * 100) / 100;
        if (typeof document !== 'undefined') document.documentElement.style.setProperty('--hudscale', s.hudScale);
      }
      else if (v === 'legal') { g.ui.say(DISCLAIMER_CREDITS, null, ''); return; }
      else if (v === 'account') { AUTH.openAccountMenu(g); return; }
      else if (v === 'syncnow') { SYNC.syncNow(g, true); return; }
      else if (v === 'erase') {
        g.ui.showMenu('Erase ALL save data?', [
          { label: 'Yes, erase everything', value: 'yes' },
          { label: 'No, keep it', value: 'no' },
        ], (a) => {
          if (a === 'yes') {
            g.ui.showMenu('Really sure? This cannot be undone.', [
              { label: 'Yes, erase', value: 'yes2' },
              { label: 'No', value: 'no' },
            ], (b) => {
              if (b === 'yes2') {
                // P1/H4: third gate — type-to-confirm DELETE (deletion is irreversible).
                g.ui.showNameEntry('Type DELETE to confirm', '', 6, (typed) => {
                  if (typed === 'DELETE') {
                    g.store.erase();
                    g.ui.toast('Save data erased.');
                  } else {
                    g.ui.toast('Erase cancelled.');
                  }
                });
              }
            }, { menuClass: 'syswin' });
          }
        }, { menuClass: 'syswin' });
        return;
      } else return;
      g.saveGame(true);
      g.openOptions();
    }, { menuClass: 'syswin' });
  }
}

// Bootstrap (browser). Headless harness imports Game directly.
if (typeof window !== 'undefined') {
  window.addEventListener('DOMContentLoaded', () => {
    const canvas = document.getElementById('game');
    const game = new Game(canvas);
    game.boot();
  });
}


// ---- src/game/main-systems.mjs ----
// main-systems.mjs — Game-level systems (WS6/WS9): bag item use incl.
// medicine/stones/Rare Candy, TM/HM teaching with HM overwrite protection,
// post-battle learn + evolution queues, the quest log, the region chain,
// and the diploma / Oak-rating payoffs. Extends the Game class prototype.


const REGIONS = [
  { id: 'kanto', name: 'Kanto', note: 'The beginning. Eight badges, one League, a storm over New Island.' },
  { id: 'orange', name: 'Orange Islands', note: 'A southern sea league of trials. Complete Kanto first.' },
  { id: 'johto', name: 'Johto', note: 'Old towers, older legends. Complete the Orange voyage first.' },
  { id: 'hoenn', name: 'Hoenn', note: 'Sea and land at war with the sky. Complete Johto first.' },
  { id: 'sinnoh', name: 'Sinnoh', note: 'Myths written in stone and time. Complete Hoenn first.' },
  { id: 'unova', name: 'Unova', note: 'Truth against ideals. Complete Sinnoh first.' },
  { id: 'kalos', name: 'Kalos', note: 'Beauty, bonds, and a flare of war. Complete Unova first.' },
  { id: 'alola', name: 'Alola', note: 'An island challenge under twin lights. Complete Kalos first.' },
  { id: 'galar', name: 'Galar / Hisui', note: 'Stadiums roar; an older land remembers. Complete Alola first.' },
  { id: 'paldea', name: 'Paldea', note: 'A treasure hunt in three directions. Complete Galar first.' },
  { id: 'liko', name: 'A New Horizon', note: 'The next traveler\'s opening. Complete Paldea first.' },
];

Object.assign(Game.prototype, {
  // ---------- bag ----------
  // Bag target rows (Rare Candy / medicine / stones / TM teaching) carry
  // the target Pokemon's battle-art sprite, same treatment as the Party
  // menu in main.mjs: <img class="picon"> from the species data URL,
  // cached per species id via Game#spriteDataUrl (main.mjs) so toDataURL
  // runs once per species. Back/empty rows stay plain text. The bag's own
  // item rows get their icons in main.mjs openBag (uiIcon data URLs).
  partyTargetRowHtml(it) {
    if (!it || it.value === -1 || it.value === null || it.value === undefined) {
      return '<span>' + (it ? it.label : '') + '</span>';
    }
    const mon = this.state && this.state.party ? this.state.party[it.value] : null;
    if (!mon) return '<span>' + it.label + '</span>';
    const img = (typeof this.spriteDataUrl === 'function')
      ? '<img class="picon" src="' + this.spriteDataUrl(mon.speciesId) + '" alt="">' : '';
    return img + '<span>' + it.label + '</span>';
  },

  useBagItem(id) {
    const g = this;
    const it = ITEMS[id];
    if (!it) return;
    const ow = g.scenes.top;
    const finish = () => g.openBag();
    if (it.pocket === 'tm' || it.pocket === 'hm') { this.teachFromBag(id, it); return; }
    if (it.levelUp) { // Rare Candy
      const targets = g.state.party.map((m, i) => ({ label: displayName(m, SPECIES) + ' Lv' + m.level, value: i, disabled: m.level >= 100 }));
      targets.push({ label: 'Back', value: -1 });
      g.ui.showMenu('Use Rare Candy on...', targets, (t) => {
        if (t === null || t === -1) { finish(); return; }
        const m = g.state.party[t];
        g.state.bag[id]--;
        m.level++;
        m.xp = xpForLevel(SPECIES[m.speciesId].growth, m.level);
        this.recalcMon(m, true);
        g.audio.playSfx('levelup');
        g.ui.say([displayName(m, SPECIES) + ' grew to Lv ' + m.level + '!'], () => { this.queueEvolution(m); finish(); });
      }, { rowHtml: (it) => g.partyTargetRowHtml(it) });
      return;
    }
    if (it.pocket === 'medicine') {
      const targets = g.state.party.map((m, i) => {
        let dis = false;
        if (it.revive) dis = m.hp > 0;
        else if (it.cure) dis = m.hp <= 0 || (it.cure !== 'all' && m.status !== it.cure) || (it.cure === 'all' && !m.status);
        else if (it.heal) dis = m.hp <= 0 || m.hp >= m.maxHp;
        else if (it.ppRestore || it.ppRestoreAll) dis = m.hp <= 0;
        return { label: displayName(m, SPECIES) + ' ' + m.hp + '/' + m.maxHp + (m.status ? ' [' + m.status + ']' : ''), value: i, disabled: dis };
      });
      targets.push({ label: 'Back', value: -1 });
      g.ui.showMenu('Use ' + it.name + ' on...', targets, (t) => {
        if (t === null || t === -1) { finish(); return; }
        const m = g.state.party[t];
        const apply = () => {
          g.state.bag[id]--;
          g.audio.playSfx('heal');
          g.ui.toast(displayName(m, SPECIES) + ' — ' + it.name + ' used.');
          finish();
        };
        if (it.revive) { m.hp = Math.floor(m.maxHp * it.revive); m.status = null; apply(); return; }
        if (it.heal) { m.hp = Math.min(m.maxHp, m.hp + it.heal); if (it.cureStatus) m.status = null; apply(); return; }
        if (it.cure) { m.status = null; m.confused = false; apply(); return; }
        if (it.ppRestore) {
          const mvItems = m.moves.map((mv, mi) => ({ label: MOVES[mv.id].name + ' ' + mv.pp + '/' + mv.maxPp, value: mi }));
          mvItems.push({ label: 'Back', value: -1 });
          g.ui.showMenu('Restore which move?', mvItems, (mi) => {
            if (mi === null || mi === -1) { finish(); return; }
            m.moves[mi].pp = Math.min(m.moves[mi].maxPp, m.moves[mi].pp + it.ppRestore);
            apply();
          });
          return;
        }
        if (it.ppRestoreAll) { for (const mv of m.moves) mv.pp = Math.min(mv.maxPp, mv.pp + it.ppRestoreAll); apply(); return; }
        finish();
      }, { rowHtml: (it) => g.partyTargetRowHtml(it) });
      return;
    }
    if (['firestone', 'waterstone', 'thunderstone', 'leafstone', 'moonstone'].includes(id)) {
      const stoneTargets = g.state.party.filter((m) => {
        const sp = SPECIES[m.speciesId];
        const evos = sp.evos || (sp.evo ? [sp.evo] : []);
        return evos.some((e) => e.method === 'stone' && e.stone === id);
      });
      if (id === 'thunderstone') {
        const partner = g.state.party.find((m) => m.speciesId === 'partner');
        if (partner && !stoneTargets.length) { g.ui.say(['PIKACHU shook its head hard. It will never use that stone.']); return; }
      }
      if (!stoneTargets.length) { g.ui.say(['It won\'t have any effect on your party.']); return; }
      const items = stoneTargets.map((m) => ({ label: displayName(m, SPECIES) + ' Lv' + m.level, value: m.monId }));
      items.push({ label: 'Back', value: null });
      const stoneRowHtml = (row) => {
        if (!row || row.value === null || row.value === undefined) return '<span>' + (row ? row.label : '') + '</span>';
        const mon = stoneTargets.find((m) => m.monId === row.value);
        if (!mon || typeof g.spriteDataUrl !== 'function') return '<span>' + row.label + '</span>';
        return '<img class="picon" src="' + g.spriteDataUrl(mon.speciesId) + '" alt=""><span>' + row.label + '</span>';
      };
      g.ui.showMenu('Use ' + it.name + ' on...', items, (v) => {
        const mon = stoneTargets.find((m) => m.monId === v);
        if (!mon) { finish(); return; }
        g.state.bag[id]--;
        if (ow && ow.evolveMon) ow.evolveMon(mon, id);
        finish();
      }, { rowHtml: stoneRowHtml });
      return;
    }
    // Key items + balls: honest guidance lines.
    const hints = {
      bicycle: 'Press SELECT outdoors to ride. Twice the speed, zero dignity loss.',
      oldrod: 'Face water and press A to cast.',
      goodrod: 'Face water and press A to cast.',
      superrod: 'Face water and press A to cast.',
      townmap: null, // opens the map view below
      itemfinder: 'It reacts on its own near hidden items when you search a tile.',
      pokeflute: 'Its tune wakes sleeping Pokemon — even very large roadblocks.',
      coincase: 'Coins: ' + (g.state.bag.coin || 0) + '. Win more at the Game Corner slots.',
    };
    if (id === 'townmap') { this.openTownMap(); return; }
    if (id === 'escaperope') {
      // Warp to the last Center town (the overworld tracks centerReturn).
      const owNow = g.scenes.top;
      const ret = owNow && owNow.centerReturn;
      if (ret && ret.map !== (g.state.story.position && g.state.story.position.map)) {
        g.state.bag[id]--;
        g.state.story.position = { map: ret.map, x: ret.x, y: ret.y, dir: 'down' };
        g.startOverworld();
        g.ui.toast('You warped out with the Escape Rope!');
      } else {
        g.ui.say(['No need for a rope here — fresh air is right there.']);
      }
      return;
    }
    if (it.pocket === 'balls') { g.ui.say(['Throw balls in battle — A in real-time mode, BAG in classic mode.']); return; }
    if (hints[id]) { g.ui.say([hints[id]]); return; }
    g.ui.say([it.desc || it.name + '.']);
  },

  recalcMon(m, keepHpRatio) {
    const sp = SPECIES[m.speciesId];
    const ivs = m.ivs || {};
    const oldMax = m.maxHp;
    m.maxHp = hpValue(sp.base.hp, m.level, ivs.hp);
    m.hp = keepHpRatio ? Math.min(m.maxHp, m.hp + (m.maxHp - oldMax)) : Math.min(m.hp, m.maxHp);
    m.stats = {
      atk: statValue(sp.base.atk, m.level, ivs.atk), def: statValue(sp.base.def, m.level, ivs.def),
      spa: statValue(sp.base.spa, m.level, ivs.spa), spd: statValue(sp.base.spd, m.level, ivs.spd),
      spe: statValue(sp.base.spe, m.level, ivs.spe),
    };
  },

  queueEvolution(mon) {
    const g = this;
    const sp = SPECIES[mon.speciesId];
    if (sp.evo && sp.evo.method === 'level' && mon.level >= sp.evo.level) {
      const q = g.state.session.evolveQueue || (g.state.session.evolveQueue = []);
      if (!q.some((e) => e.monId === mon.monId)) q.push({ monId: mon.monId });
    }
  },

  teachFromBag(itemId, it) {
    const g = this;
    const moveId = it.move;
    const mv = MOVES[moveId];
    const isHm = it.pocket === 'hm';
    const targets = g.state.party.map((m, i) => {
      const sp = SPECIES[m.speciesId];
      // TM eligibility from the species' tm list; HMs encode as 100+n there.
      // Species without a tm list (the original slice roster) predate the
      // data and are allowed, as before.
      const can = isHm
        ? (!sp.tm || sp.tm.includes(100 + parseInt(itemId.slice(2), 10)))
        : (!sp.tm || sp.tm.includes(parseInt(itemId.slice(2), 10)));
      const knows = m.moves.some((x) => x.id === moveId);
      return { label: displayName(m, SPECIES) + (knows ? ' (knows it)' : can ? '' : ' (cannot learn)'), value: i, disabled: knows || !can };
    });
    targets.push({ label: 'Back', value: -1 });
    g.ui.showMenu('Teach ' + mv.name + ' (' + itemId.toUpperCase() + ') to...', targets, (t) => {
      if (t === null || t === -1) { g.openBag(); return; }
      const m = g.state.party[t];
      this.teachMove(m, moveId, isHm, () => { if (!isHm) g.state.bag[itemId]--; g.openBag(); });
    }, { rowHtml: (it) => g.partyTargetRowHtml(it) });
  },

  teachMove(mon, moveId, isHm, done) {
    const g = this;
    const mv = MOVES[moveId];
    if (mon.moves.some((x) => x.id === moveId)) { g.ui.say([displayName(mon, SPECIES) + ' already knows ' + mv.name + '.']); if (done) done(); return; }
    const learn = (slotIdx) => {
      const entry = { id: moveId, pp: mv.pp, maxPp: mv.pp };
      if (slotIdx === -1) mon.moves.push(entry);
      else mon.moves[slotIdx] = entry;
      if (isHm) { mon.hmMoves = mon.hmMoves || []; if (!mon.hmMoves.includes(moveId)) mon.hmMoves.push(moveId); }
      g.audio.playSfx('dex-register');
      g.ui.say([displayName(mon, SPECIES) + ' learned ' + mv.name + '!'], () => { if (done) done(); });
    };
    if (mon.moves.length < 4) { learn(-1); return; }
    // Full set: the learn/forget prompt. HM-taught moves are protected —
    // they can never be the forgotten slot (the original's rule).
    const items = mon.moves.map((x, i) => {
      const prot = (mon.hmMoves || []).includes(x.id);
      return { label: MOVES[x.id].name + (prot ? ' (HM — cannot forget)' : ''), value: i, disabled: prot };
    });
    items.push({ label: 'Give up learning ' + mv.name, value: -2 });
    g.ui.showMenu(displayName(mon, SPECIES) + ' wants to learn ' + mv.name + '. Forget which move?', items, (v) => {
      if (v === -2 || v === null) { g.ui.say([displayName(mon, SPECIES) + ' did not learn ' + mv.name + '.']); if (done) done(); return; }
      learn(v);
    });
  },

  // ---------- post-battle queues ----------
  processQueues() {
    const g = this;
    if (g.ui.menu || g.ui.dialogue) return;
    const top = g.scenes.top;
    if (!top || typeof top.evolveMon !== 'function') return;
    const sq = g.state.session;
    if (sq.learnQueue && sq.learnQueue.length) {
      const entry = sq.learnQueue.shift();
      const mon = g.state.party.find((m) => m.monId === entry.monId);
      if (mon) { this.teachMove(mon, entry.moveId, false, null); return; }
    }
    if (sq.evolveQueue && sq.evolveQueue.length) {
      const entry = sq.evolveQueue.shift();
      const mon = g.state.party.find((m) => m.monId === entry.monId);
      if (mon) top.evolveMon(mon);
    }
  },

  // ---------- quest log / regions / payoffs ----------
  openQuestLog() {
    const g = this;
    const items = [];
    items.push({ label: '— MAIN QUEST —', value: null, disabled: true });
    for (const q of QUESTS) {
      const doneF = q.flag && g.state.story.flags[q.flag];
      const active = !doneF && QUESTS.find((x) => !x.flag || !g.state.story.flags[x.flag]) === q;
      items.push({
        label: (doneF ? '★ ' : active ? '▶ ' : '· ') + q.text,
        value: 'q:' + q.id, disabled: !active && !doneF,
      });
    }
    const arcs = Object.keys(g.state.story.quests || {});
    if (arcs.length) {
      items.push({ label: '— SIDE ARCS —', value: null, disabled: true });
      for (const id of arcs) {
        const arc = LEGENDARY_ARCS[id];
        if (!arc) continue;
        items.push({ label: (g.state.story.quests[id] === 'complete' ? '★ ' : '▶ ') + arc.title, value: 'arc:' + id });
      }
    }
    items.push({ label: 'Close', value: 'close' });
    g.ui.showMenu('Quest Log', items, (v) => {
      if (!v || v === 'close') return;
      if (v.startsWith('q:')) {
        const q = QUESTS.find((x) => 'q:' + x.id === v);
        if (q) g.ui.say([q.text, q.hint], () => g.openQuestLog(), 'Quest');
      } else if (v.startsWith('arc:')) {
        const arc = LEGENDARY_ARCS[v.slice(4)];
        if (arc) {
          const lines = [arc.title + ' — ' + (arc.species ? SPECIES[arc.species] ? SPECIES[arc.species].name : arc.species : '')];
          lines.push('Hook: ' + arc.hook);
          for (const st of arc.steps || []) lines.push('· ' + (typeof st === 'string' ? st : st.text));
          if (arc.lair) lines.push('Lair: ' + arc.lair);
          g.ui.say(lines, () => g.openQuestLog(), 'Arc');
        }
      }
    });
  },

  openRegions() {
    const g = this;
    const cur = g.state.story.region || 'kanto';
    const doneList = g.state.story.regionsDone || [];
    const items = REGIONS.map((r) => {
      const isDone = doneList.includes(r.id);
      const isCur = r.id === cur;
      return {
        label: (isDone ? '★ ' : isCur ? '▶ ' : '· ') + r.name + (isCur ? ' (you are here)' : isDone ? '' : ' — sealed'),
        value: r.id,
      };
    });
    items.push({ label: 'Close', value: 'close' });
    g.ui.showMenu('Journey — Regions', items, (v) => {
      if (!v || v === 'close') return;
      const r = REGIONS.find((x) => x.id === v);
      if (r) g.ui.say([r.name, r.note], () => g.openRegions(), 'Journey');
    });
  },

  openTownMap() {
    const g = this;
    const visited = Object.keys(g.state.story.flags).filter((k) => k.startsWith('reached_')).map((k) => k.slice(8));
    g.ui.say(['KANTO — places you have been:', visited.length ? visited.join(' · ') : 'Nowhere yet. Walk!'], null, 'Town Map');
  },

  // ---------- field moves (WS9) ----------
  openFieldMove(mon) {
    const g = this;
    const known = (mon.moves || []).map((x) => x.id).filter((id) => ['cut', 'fly', 'surf', 'strength', 'flash'].includes(id));
    const badges = g.state.badges.kanto;
    const gate = { cut: 'cascadebadge', fly: 'thunderbadge', surf: 'soulbadge', strength: 'rainbowbadge', flash: 'boulderbadge' };
    const items = known.map((id) => ({
      label: MOVES[id].name + (badges.includes(gate[id]) ? '' : ' (needs ' + gate[id].replace('badge', ' Badge') + ')'),
      value: id, disabled: !badges.includes(gate[id]),
    }));
    items.push({ label: 'Back', value: null });
    g.ui.showMenu('Field moves — ' + displayName(mon, SPECIES), items, (v) => {
      if (!v) return;
      const ow = g.scenes.top;
      if (v === 'flash') {
        if (ow && ow.map && ow.map.dark && ow.fxState) {
          ow.fxState.flashLit = true;
          g.audio.playSfx('dex-register');
          g.ui.toast(displayName(mon, SPECIES) + ' lit up the dark!');
        } else g.ui.say(['Flash only helps inside a dark cave.']);
        return;
      }
      if (v === 'fly') {
        const cities = Object.keys(g.state.story.flags)
          .filter((k) => k.startsWith('visited_'))
          .map((k) => k.slice(8))
          .filter((id) => MAPS[id]);
        if (!cities.length) { g.ui.say(['No town visited yet — nowhere to fly to.']); return; }
        const dests = cities.map((id) => ({ label: MAPS[id].name, value: id }));
        dests.push({ label: 'Back', value: null });
        g.ui.showMenu('Fly to...', dests, (d) => {
          if (!d) return;
          const city = MAPS[d];
          const viaWarp = (city.warps || []).find((w) => w.via);
          const spot = viaWarp ? viaWarp.via : (city.start || { x: 8, y: 8 });
          g.state.story.position = { map: d, x: spot.x, y: spot.y, dir: 'down' };
          g.audio.playSfx('warp');
          g.startOverworld();
          g.ui.toast('Flew to ' + city.name + '!');
        });
        return;
      }
      // Cut / Surf / Strength are contextual: used by facing the obstacle.
      const hints = {
        cut: 'Face a small tree and press A to cut it down.',
        surf: 'Face the water\'s edge and press A to surf.',
        strength: 'Face a round boulder and press A, then push it by walking.',
      };
      g.ui.say([hints[v] || '']);
    });
  },

  // Oak's rating + the diploma moment (WS7 payoff).
  oakRating() {
    const n = dexCaughtCount(this.state.dex);
    if (n < 10) return 'Hmm. ' + n + ' caught. The journey is young — walk the grass, meet them all.';
    if (n < 50) return n + ' caught! You are learning what a Pokedex is for. Keep going!';
    if (n < 100) return n + ' caught! A genuine collector\'s eye. The rare ones hide well — patience.';
    if (n < 151) return n + ' caught! Nearly there. The last pages are always the hardest.';
    return 'ALL 151! Every Kanto species, in one journey. This is a historic Pokedex!';
  },

  checkDiploma() {
    const g = this;
    const kanto = Object.values(SPECIES).filter((s) => s.dexNo >= 1 && s.dexNo <= 151);
    const done = kanto.every((s) => g.state.dex.caught[s.dexNo]);
    if (done && !g.state.story.flags.diploma) {
      g.state.story.flags.diploma = true;
      g.audio.playSfx('badge');
      g.ui.say([
        'DIPLOMA — This certifies that ' + g.state.player.name + ' completed the Kanto Pokedex:',
        'all 151 species, caught in a single journey. Sealed by Prof. Hawthorn, with enormous pride.',
      ], null, 'Prof. Hawthorn');
    }
  },
});
